export class RingBuffer<T> {
  private readonly buf: Array<T | undefined>;
  private readonly mask: number;
  private head = 0;
  private tail = 0;

  constructor(capacityPow2: number) {
    if (capacityPow2 <= 0 || (capacityPow2 & (capacityPow2 - 1)) !== 0) {
      throw new RangeError("capacity must be a positive power of 2");
    }
    this.buf = new Array<T | undefined>(capacityPow2);
    this.mask = capacityPow2 - 1;
  }

  get size(): number {
    return this.tail - this.head;
  }

  push(item: T): boolean {
    if (this.size === this.buf.length) return false;
    this.buf[this.tail & this.mask] = item;
    this.tail += 1;
    return true;
  }

  pop(): T | undefined {
    if (this.head === this.tail) return undefined;
    const idx = this.head & this.mask;
    const val = this.buf[idx];
    this.buf[idx] = undefined; // release reference for GC
