```rust
use std::collections::HashMap;
use std::hash::Hash;

const NONE: usize = usize::MAX;

struct Node<K, V> {
    key: K,
    val: V,
    prev: usize,
    next: usize,
}

pub struct LruCache<K, V> {
    cap: usize,
    map: HashMap<K, usize>,
    entries: Vec<Node<K, V>>,
    head: usize,
    tail: usize,
}

impl<K: Eq + Hash + Clone, V> LruCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0);
        Self { cap, map: HashMap::with_capacity(cap), entries: Vec::with_capacity(cap), head: NONE, tail: NONE }
    }

    fn detach(&mut self, idx: usize) {
        let (prev, next) = (self.entries[idx].prev, self.entries[idx].next);
        if prev != NONE { self.entries[prev].next = next; } else { self.head = next; }
        if next != NONE { self.entries[next].prev = prev; } else { self.tail = prev; }
    }

    fn attach_front(&mut self, idx: usize) {
        self.entries[idx].prev = NONE;
        self.entries[idx].next = self.head;
        if self.head != NONE { self.entries[self.head].prev = idx; }
        self.head = idx;
        if self.tail == NONE { self.tail = idx; }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let &idx = self.map.get(key)?;
        self.detach(idx);
        self.attach_front(idx);
        Some(&self.entries[idx].val)
    }

    pub fn put(&mut self, key: K, val: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.entries[idx].val = val;
            self.detach(idx);
            self.attach_front(idx);
            return;
        }
        let idx = if self.entries.len() == self.cap {
            let old = self.tail;
            self.detach(old);
            self.map.remove(&self.entries[old].key);
            self.entries[old] = Node { key: key.clone(), val, prev: NONE, next: NONE };
            old
        } else {
            let idx = self.entries.len();
            self.entries.push(Node { key: key.clone(), val, prev: NONE, next: NONE });
            idx
        };
        self.map.insert(key, idx);
        self.attach_front(idx);
    }
}
```

