use std::cell::UnsafeCell;
use std::mem::MaybeUninit;
use std::sync::atomic::{AtomicUsize, Ordering};

pub struct SpscRing<T, const CAP: usize> {
    buf: [UnsafeCell<MaybeUninit<T>>; CAP],
    head: AtomicUsize,
    tail: AtomicUsize,
}

unsafe impl<T: Send, const CAP: usize> Sync for SpscRing<T, CAP> {}

impl<T, const CAP: usize> SpscRing<T, CAP> {
    pub fn new() -> Self {
        assert!(CAP.is_power_of_two());
        Self {
            buf: std::array::from_fn(|_| UnsafeCell::new(MaybeUninit::uninit())),
            head: AtomicUsize::new(0),
            tail: AtomicUsize::new(0),
        }
    }

    pub unsafe fn push_producer(&self, val: T) -> Result<(), T> {
        let tail = self.tail.load(Ordering::Relaxed);
        let head = self.head.load(Ordering::Acquire);
        if tail.wrapping_sub(head) == CAP {
            return Err(val);
        }
        (*self.buf[tail & (CAP - 1)].get()).write(val);
        self.tail.store(tail.wrapping_add(1), Ordering::Release);
        Ok(())
    }

    pub unsafe fn pop_consumer(&self) -> Option<T> {
        let head = self.head.load(Ordering::Relaxed);
        let tail = self.tail.load(Ordering::Acquire);
        if head == tail {
            return None;
        }
        let val = (*self.buf[head & (CAP - 1)].get()).assume_init_read();
        self.head.store(head.wrapping_add(1), Ordering::Release);
        Some(val)
    }
}
```

