from collections import deque


def plan_build_dag(
    targets: dict[str, tuple[float, list[str]]],
) -> tuple[list[list[str]], float, list[str]]:
    in_deg: dict[str, int] = {t: 0 for t in targets}
    rev_adj: dict[str, list[str]] = {t: [] for t in targets}
    dur: dict[str, float] = {t: targets[t][0] for t in targets}

    for node, (_, deps) in targets.items():
        for dep in deps:
            if dep not in targets:
                raise KeyError(f"Unknown dependency: {dep}")
            rev_adj[dep].append(node)
            in_deg[node] += 1

    earliest_finish: dict[str, float] = {t: dur[t] for t in targets}
    parent_on_crit: dict[str, str | None] = {t: None for t in targets}

    queue = deque(sorted(t for t, d in in_deg.items() if d == 0))
    waves: list[list[str]] = []
    processed = 0

    while queue:
        wave = list(queue)
        waves.append(wave)
        queue.clear()
        next_ready: list[str] = []

        for u in wave:
            processed += 1
            for v in rev_adj[u]:
                cand = earliest_finish[u] + dur[v]
                if cand > earliest_finish[v]:
                    earliest_finish[v] = cand
                    parent_on_crit[v] = u
                in_deg[v] -= 1
                if in_deg[v] == 0:
                    next_ready.append(v)

        queue.extend(sorted(next_ready))

    if processed != len(targets):
        raise ValueError("Cycle detected in build DAG")

    if not targets:
        return [], 0.0, []

    sink = max(targets, key=lambda t: earliest_finish[t])
    crit_path: list[str] = []
    cur: str | None = sink
    while cur is not None:
        crit_path.append(cur)
        cur = parent_on_crit[cur]
    crit_path.reverse()

    return waves, earliest_finish[sink], crit_path
```

