```python
def tarjan_scc[T](adj: dict[T, list[T]]) -> list[list[T]]:
    index_counter = 0
    indices: dict[T, int] = {}
    lowlink: dict[T, int] = {}
    scc_stack: list[T] = []
    on_stack: set[T] = set()
    sccs: list[list[T]] = []

    all_nodes = set(adj.keys())
    for nbrs in adj.values():
        all_nodes.update(nbrs)

    for start in all_nodes:
        if start in indices:
            continue
        call_stack: list[tuple[T, int]] = [(start, 0)]
        while call_stack:
            v, ni = call_stack[-1]
            if ni == 0 and v not in indices:
                indices[v] = lowlink[v] = index_counter
                index_counter += 1
                scc_stack.append(v)
                on_stack.add(v)
            nbrs = adj.get(v, [])
            if ni < len(nbrs):
                w = nbrs[ni]
                call_stack[-1] = (v, ni + 1)
                if w not in indices:
                    call_stack.append((w, 0))
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])
            else:
                call_stack.pop()
                if call_stack:
                    parent = call_stack[-1][0]
                    lowlink[parent] = min(lowlink[parent], lowlink[v])
                if lowlink[v] == indices[v]:
                    comp: list[T] = []
                    while True:
                        w = scc_stack.pop()
                        on_stack.remove(w)
                        comp.append(w)
                        if w == v:
                            break
                    sccs.append(comp)
    return sccs
```

