package router

import "encoding/binary"

func mix64(k uint64) uint64 {
	k ^= k >> 33
	k *= 0xff51afd7ed558ccd
	k ^= k >> 33
	k *= 0xc4ceb9fe1a85ec53
	k ^= k >> 33
	return k
}

func weight(node, key string) uint64 {
	const offset64 = 14695981039346656037
	const prime64 = 1099511628211
