	for i := 0; i < len(key); i++ {
		h ^= uint64(key[i])
		h *= prime64
	}
	var buf [8]byte
	binary.LittleEndian.PutUint64(buf[:], h)
	return mix64(binary.LittleEndian.Uint64(buf[:]))
}

// PickBuilder returns the healthy builder endpoint with highest weight for repoKey.
func PickBuilder(healthyBuilders []string, repoKey string) (string, bool) {
