```rust
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

pub struct BloomFilter {
    bits: Vec<u64>,
    num_bits: u64,
    k: u32,
}

impl BloomFilter {
    pub fn new(num_bits: usize, k: u32) -> Self {
        let words = num_bits.div_ceil(64).max(1);
        Self { bits: vec![0u64; words], num_bits: (words * 64) as u64, k }
    }

    fn hash_pair<T: Hash + ?Sized>(item: &T) -> (u64, u64) {
        let mut h1 = DefaultHasher::new();
        0x9e3779b97f4a7c15u64.hash(&mut h1);
        item.hash(&mut h1);
        let a = h1.finish();
        let b = a.rotate_left(32) ^ 0xbf58476d1ce4e5b9u64;
        (a, b | 1)
    }

    pub fn insert<T: Hash + ?Sized>(&mut self, item: &T) {
        let (h1, h2) = Self::hash_pair(item);
        for i in 0..self.k as u64 {
            let bit = h1.wrapping_add(i.wrapping_mul(h2)) % self.num_bits;
            self.bits[(bit / 64) as usize] |= 1u64 << (bit % 64);
        }
    }

    pub fn contains<T: Hash + ?Sized>(&self, item: &T) -> bool {
        let (h1, h2) = Self::hash_pair(item);
        for i in 0..self.k as u64 {
            let bit = h1.wrapping_add(i.wrapping_mul(h2)) % self.num_bits;
            if (self.bits[(bit / 64) as usize] & (1u64 << (bit % 64))) == 0 {
                return false;
            }
        }
        true
    }
}
```

