class BufferedInvertedIndex:
    def __init__(self, pending_byte_limit: int = 4096) -> None:
        self.pending_byte_limit = pending_byte_limit
        self.pending_bytes = 0
        self.pending: list[tuple[str, int]] = []
        self.main_index: dict[str, list[int]] = defaultdict(list)

    def insert_doc(self, doc_id: int, terms: set[str]) -> bool:
        for term in terms:
            self.pending.append((term, doc_id))
            self.pending_bytes += len(term) + 8
        if self.pending_bytes >= self.pending_byte_limit:
            self.flush_pending()
            return True
        return False

    def flush_pending(self) -> None:
        grouped: dict[str, list[int]] = defaultdict(list)
        for term, doc_id in self.pending:
            grouped[term].append(doc_id)
        for term, new_ids in grouped.items():
            posting = self.main_index[term]
            for doc_id in sorted(set(new_ids)):
                idx = bisect.bisect_left(posting, doc_id)
                if idx == len(posting) or posting[idx] != doc_id:
                    posting.insert(idx, doc_id)
        self.pending.clear()
        self.pending_bytes = 0

    def search_term(self, term: str) -> list[int]:
        res = set(self.main_index.get(term, []))
        for p_term, doc_id in self.pending:
            if p_term == term:
                res.add(doc_id)
        return sorted(res)
```

