from collections import defaultdict

def build_waves(deps: dict[str, list[str]]) -> list[list[str]]:
    # deps[pkg] = list of prerequisite packages pkg depends on
    nodes = set(deps.keys()) | {d for ds in deps.values() for d in ds}
    rev_adj: dict[str, list[str]] = defaultdict(list)
    indeg: dict[str, int] = {u: 0 for u in nodes}
    for pkg, prereqs in deps.items():
        for pre in set(prereqs):
            rev_adj[pre].append(pkg)
            indeg[pkg] += 1

    wave = sorted(u for u, d in indeg.items() if d == 0)
    waves: list[list[str]] = []
    visited = 0
    while wave:
        waves.append(wave)
        visited += len(wave)
        nxt_wave: list[str] = []
        for u in wave:
            for v in rev_adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    nxt_wave.append(v)
        wave = sorted(nxt_wave)

    if visited != len(nodes):
        stuck = sorted(u for u, d in indeg.items() if d > 0)
        raise ValueError(f"Dependency cycle detected involving: {stuck}")
    return waves
```

