```python
from typing import Mapping, Sequence


def find_dependency_cycles(graph: Mapping[str, Sequence[str]]) -> list[list[str]]:
    index_counter = 0
    indices: dict[str, int] = {}
    lowlink: dict[str, int] = {}
    on_stack: set[str] = set()
    tarjan_stack: list[str] = []
    cycles: list[list[str]] = []

    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    for root in sorted(all_nodes):
        if root in indices:
            continue

        call_stack: list[tuple[str, int]] = [(root, 0)]
        indices[root] = lowlink[root] = index_counter
        index_counter += 1
        tarjan_stack.append(root)
        on_stack.add(root)

        while call_stack:
            u, edge_idx = call_stack[-1]
            neighbors = graph.get(u, ())

            if edge_idx < len(neighbors):
                call_stack[-1] = (u, edge_idx + 1)
                v = neighbors[edge_idx]
                if v not in indices:
                    indices[v] = lowlink[v] = index_counter
                    index_counter += 1
                    tarjan_stack.append(v)
                    on_stack.add(v)
                    call_stack.append((v, 0))
                elif v in on_stack:
                    if indices[v] < lowlink[u]:
                        lowlink[u] = indices[v]
            else:
                call_stack.pop()
                if call_stack:
                    parent = call_stack[-1][0]
                    if lowlink[u] < lowlink[parent]:
                        lowlink[parent] = lowlink[u]

                if lowlink[u] == indices[u]:
                    scc: list[str] = []
                    while True:
                        w = tarjan_stack.pop()
                        on_stack.remove(w)
                        scc.append(w)
                        if w == u:
                            break
                    # Nontrivial cycle: >1 node OR self-loop (u -> u)
                    if len(scc) > 1 or u in graph.get(u, ()):
                        cycles.append(sorted(scc))

    return cycles
```

Checking `len(scc) > 1 or u in graph.get(u, ())` catches both multi-package cycles (`A -> B -> C -> A`) 4nd accidental self-dependencies (`A -> A`).

