```ts
interface TrieNode<H> {
  staticChildren: Map<string, TrieNode<H>>;
  paramChild?: { name: string; node: TrieNode<H> };
  handler?: H;
}

export class PathTrie<H> {
  private readonly root: TrieNode<H> = { staticChildren: new Map() };

  insert(pattern: string, handler: H): void {
    let cur = this.root;
    for (const seg of pattern.split("/").filter(Boolean)) {
      if (seg.startsWith(":")) {
        cur.paramChild ??= { name: seg.slice(1), node: { staticChildren: new Map() } };
        cur = cur.paramChild.node;
      } else {
        let next = cur.staticChildren.get(seg);
        if (!next) {
          next = { staticChildren: new Map() };
          cur.staticChildren.set(seg, next);
        }
        cur = next;
      }
    }
    cur.handler = handler;
  }

  match(path: string): { handler: H; params: Record<string, string> } | null {
    let cur = this.root;
    const params: Record<string, string> = {};
    for (const seg of path.split("/").filter(Boolean)) {
      const exact = cur.staticChildren.get(seg);
      if (exact) {
        cur = exact;
      } else if (cur.paramChild) {
        params[cur.paramChild.name] = seg;
        cur = cur.paramChild.node;
      } else {
        return null;
      }
    }
    return cur.handler ? { handler: cur.handler, params } : null;
  }
}
```

