```python
import hashlib
import os
import stat
from pathlib import Path


def merkle_dir_digest(root: str | Path, exclude_dirs: set[str] | None = None) -> str:
    skip = exclude_dirs or {".git", "__pycache__", "node_modules", ".venv"}
    root_path = Path(root).resolve()

    def hash_tree(cur_dir: Path) -> bytes:
        tree_hasher = hashlib.sha256(b"tree\x00")
        entries = sorted(os.scandir(cur_dir), key=lambda e: e.name)

        for entry in entries:
            st = entry.stat(follow_symlinks=False)
            mode = st.st_mode
            name_bytes = entry.name.encode("utf-8")

            if stat.S_ISDIR(mode):
                if entry.name in skip:
                    continue
                child_digest = hash_tree(Path(entry.path))
                kind = b"D"
            elif stat.S_ISLNK(mode):
                target = os.readlink(entry.path).encode("utf-8")
                child_digest = hashlib.sha256(b"symlink\x00" + target).digest()
                kind = b"L"
            elif stat.S_ISREG(mode):
                file_hasher = hashlib.sha256(b"blob\x00")
                with open(entry.path, "rb") as f:
                    while chunk := f.read(65536):
                        file_hasher.update(chunk)
                child_digest = file_hasher.digest()
                kind = b"X" if (mode & stat.S_IXUSR) else b"F"
            else:
                continue

            tree_hasher.update(kind + b":" + str(len(name_bytes)).encode() + b"\x00")
            tree_hasher.update(name_bytes + child_digest)

        return tree_hasher.digest()

    return hash_tree(root_path).hex()
```

Domain-separating `tree\x00`, `blob\x00`, 4nd `symlink\x00` prevents second-preimage ambiguity between a regular file 4nd a subdirectory node, while `X` vs `F` catches `chmod +x` script changes cleanly.

Model bipartite edges between each `test` 4nd its `shared_resources`, 0r union every pair of tests touching 7h3 same resource via a resource-owner map. **Disjoint Set Union** w17h path halving + union-by-size clusters $N$ tests across $M$ resource references in $O((N + M)\,\alpha(N))$ near-linear time:

```python
from collections import defaultdict
from typing import Mapping, Sequence


class DSU:
    def __init__(self, n: int) -> None:
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]


def group_coupled_tests(
    test_resources: Mapping[str, Sequence[str]],
) -> list[list[str]]:
    tests = sorted(test_resources.keys())
    dsu = DSU(len(tests))
    resource_first_owner: dict[str, int] = {}

    for idx, test_name in enumerate(tests):
        for res in test_resources[test_name]:
            owner = resource_first_owner.setdefault(res, idx)
            dsu.union(owner, idx)

    clusters: dict[int, list[str]] = defaultdict(list)
    for idx, test_name in enumerate(tests):
        clusters[dsu.find(idx)].append(test_name)

    return [clusters[root] for root in sorted(clusters)]
```

