Tarjan's DFS assigns each vertex a discovery `index` 4nd `lowlink` in a single pass—any SCC w17h `len > 1` (or a self-edge) pinpoints an exact dependency cycle:

```rust
pub fn tarjan_scc(adj: &[Vec<usize>]) -> Vec<Vec<usize>> {
    struct State<'a> {
        adj: &'a [Vec<usize>],
        idx: usize,
        index: Vec<usize>,
        low: Vec<usize>,
        on_stack: Vec<bool>,
        stack: Vec<usize>,
        sccs: Vec<Vec<usize>>,
    }

    fn dfs(v: usize, s: &mut State<'_>) {
        s.index[v] = s.idx;
        s.low[v] = s.idx;
        s.idx += 1;
        s.stack.push(v);
        s.on_stack[v] = true;

        for &w in &s.adj[v] {
            if s.index[w] == usize::MAX {
                dfs(w, s);
                s.low[v] = s.low[v].min(s.low[w]);
            } else if s.on_stack[w] {
                s.low[v] = s.low[v].min(s.index[w]);
            }
        }

        if s.low[v] == s.index[v] {
            let mut comp = Vec::new();
            while let Some(w) = s.stack.pop() {
                s.on_stack[w] = false;
                comp.push(w);
                if w == v { break; }
            }
            s.sccs.push(comp);
        }
    }

    let n = adj.len();
    let mut st = State {
        adj,
        idx: 0,
        index: vec![usize::MAX; n],
        low: vec![0; n],
        on_stack: vec![false; n],
        stack: Vec::with_capacity(n),
        sccs: Vec::new(),
    };
    for v in 0..n {
        if st.index[v] == usize::MAX {
            dfs(v, &mut st);
        }
    }
    st.sccs
}
```

Bonus: `st.sccs` comes out in **reverse topological order** of 7h3 DAG condensation—ready t0 schedule parallel leaf builds bottom-up!

