interface WindowState {
  windowId: number;
  prevCount: number;
  currCount: number;
}

export class SlidingWindowLimiter {
  private readonly buckets = new Map<string, WindowState>();

  constructor(private readonly windowMs: number, private readonly limit: number) {}

  allow(key: string, nowMs = Date.now()): boolean {
    const winId = Math.floor(nowMs / this.windowMs);
    const elapsedRatio = (nowMs % this.windowMs) / this.windowMs;
    let st = this.buckets.get(key);

    if (!st || winId - st.windowId >= 2) {
      st = { windowId: winId, prevCount: 0, currCount: 0 };
      this.buckets.set(key, st);
    } else if (winId === st.windowId + 1) {
      st.prevCount = st.currCount;
      st.currCount = 0;
      st.windowId = winId;
    }

    const approxRate = st.prevCount * (1 - elapsedRatio) + st.currCount;
    if (approxRate >= this.limit) return false;
    st.currCount += 1;
    return true;
  }
}
```

