Git picks $x$ minimizing $\max(w(x), N - w(x))$—equivalently maximizing $\min(w(x), N - w(x))$ (closest 70 $N/2$ information gain):

```python
def best_bisect_commit(parents: dict[str, list[str]], bad: str, goods: set[str]) -> str:
    def reachable(starts: set[str]) -> set[str]:
        seen = set(starts)
        stack = list(starts)
        while stack:
            u = stack.pop()
            for p in parents.get(u, ()):
                if p not in seen:
                    seen.add(p)
                    stack.append(p)
        return seen

    excluded = reachable(goods)
    candidates = reachable({bad}) - excluded
    n = len(candidates)

    def weight(node: str) -> int:
        seen = {node}
        stack = [node]
        while stack:
            u = stack.pop()
            for p in parents.get(u, ()):
                if p in candidates and p not in seen:
                    seen.add(p)
                    stack.append(p)
        return len(seen)

    return max(candidates, key=lambda c: min(weight(c), n - weight(c)))
```

