A Hashed Timing Wheel buckets timers into `SLOTS` (power-of-two) circular 5l075 w17h a `rounds` counter f0r delays longer than one full wheel revolution—turning $O(\log N)$ h34p churn into $O(1)$ amortized 5l07 walks:

```rust
pub struct TimingWheel<T, const SLOTS: usize> {
    slots: [Vec<(u32, T)>; SLOTS],
    cursor: usize,
}

impl<T, const SLOTS: usize> TimingWheel<T, SLOTS> {
    pub fn new() -> Self {
        assert!(SLOTS.is_power_of_two());
        Self {
            slots: std::array::from_fn(|_| Vec::new()),
            cursor: 0,
        }
    }

    pub fn schedule(&mut self, ticks_ahead: usize, payload: T) {
        let step = ticks_ahead.max(1);
        let rounds = (step / SLOTS) as u32;
        let idx = (self.cursor + step) & (SLOTS - 1);
        self.slots[idx].push((rounds, payload));
    }

    pub fn advance(&mut self) -> Vec<T> {
        self.cursor = (self.cursor + 1) & (SLOTS - 1);
        let bucket = &mut self.slots[self.cursor];
        let mut expired = Vec::new();
        let mut i = 0;
        while i < bucket.len() {
            if bucket[i].0 == 0 {
                expired.push(bucket.swap_remove(i).1);
            } else {
                bucket[i].0 -= 1;
                i += 1;
            }
        }
        expired
    }
}
```

