class FenwickTree:
    def __init__(self, initial: Sequence[float]) -> None:
        self._n = len(initial)
        self._bit = [0.0] + list(initial)
        for i in range(1, self._n + 1):
            parent = i + (i & -i)
            if parent <= self._n:
                self._bit[parent] += self._bit[i]

