            raise IndexError("index out of range")
        i = index + 1
        while i <= self._n:
            self._bit[i] += delta
            i += i & -i

    def prefix_sum(self, right_exclusive: int) -> float:
        if not (0 <= right_exclusive <= self._n):
            raise IndexError("bound out of range")
        total = 0.0
        i = right_exclusive
        while i > 0:
            total += self._bit[i]
            i -= i & -i
        return total

    def range_sum(self, left: int, right_exclusive: int) -> float:
        if left > right_exclusive:
            raise ValueError("left must be <= right_exclusive")
        return self.prefix_sum(right_exclusive) - self.prefix_sum(left)
