@dataclass(order=True, slots=True)
class _OpenEntry[T]:
    f: float
    g: float
    node: T = field(compare=False)

def astar[T: Hashable](
    start: T,
    goal: T,
    neighbors: Callable[[T], Iterable[tuple[T, float]]],
    heuristic: Callable[[T], float],
) -> tuple[float, list[T]] | None:
