        for nxt, step_cost in neighbors(cur.node):
            tentative_g = cur.g + step_cost
            if tentative_g < g_score.get(nxt, float("inf")):
                came_from[nxt] = cur.node
                g_score[nxt] = tentative_g
                f = tentative_g + heuristic(nxt)
                heapq.heappush(pq, _OpenEntry(f, tentative_g, nxt))
    return None
