@dataclass(frozen=True, slots=True)
class Edge[T]:
    u: T
    v: T
    weight: float

def bellman_ford[T: Hashable](
    nodes: set[T],
    edges: list[Edge[T]],
    source: T,
) -> tuple[dict[T, float], list[T] | None]:
    dist: dict[T, float] = {source: 0.0}
    parent: dict[T, T] = {}
    n = len(nodes)

    last_relaxed: T | None = None
    for step in range(n):
        last_relaxed = None
        for e in edges:
            du = dist.get(e.u)
            if du is None:
                continue
            cand = du + e.weight
            if cand < dist.get(e.v, float("inf")):
                dist[e.v] = cand
                parent[e.v] = e.u
                if step == n - 1:
                    last_relaxed = e.v
        if last_relaxed is None and step < n - 1:
            if step > 0:
                break

    if last_relaxed is None:
        return dist, None

    curr = last_relaxed
    for _ in range(n):
        curr = parent[curr]

    cycle: list[T] = [curr]
    walk = parent[curr]
    while walk != curr:
        cycle.append(walk)
        walk = parent[walk]
    cycle.append(curr)
    cycle.reverse()
    return dist, cycle
