from collections.abc import Callable, Sequence

class SegmentTree[T]:
    def __init__(
        self,
        items: Sequence[T],
        combine: Callable[[T, T], T],
        identity: T,
    ) -> None:
        self._n = len(items)
        self._combine = combine
        self._id = identity
        self._tree: list[T] = [identity] * (2 * self._n)
        for i, val in enumerate(items):
            self._tree[self._n + i] = val
        for i in range(self._n - 1, 0, -1):
            self._tree[i] = combine(self._tree[2 * i], self._tree[2 * i + 1])

    def update(self, index: int, value: T) -> None:
        if not (0 <= index < self._n):
            raise IndexError("index out of range")
        pos = self._n + index
        self._tree[pos] = value
        pos //= 2
        while pos >= 1:
            self._tree[pos] = self._combine(
                self._tree[2 * pos], self._tree[2 * pos + 1]
            )
            pos //= 2

    def query(self, left: int, right_exclusive: int) -> T:
        if not (0 <= left <= right_exclusive <= self._n):
            raise IndexError("invalid range")
        res_left = self._id
        res_right = self._id
        l = self._n + left
        r = self._n + right_exclusive
        while l < r:
            if l & 1:
                res_left = self._combine(res_left, self._tree[l])
                l += 1
            if r & 1:
                r -= 1
                res_right = self._combine(self._tree[r], res_right)
            l //= 2
            r //= 2
