**GCRA** collapses token-bucket state (`tokens` + `last_refill`) into a single monotonic `u64` nanosecond timestamp per key—its **Theoretical Arrival Time (`TAT`)**! Given emission interval $T = 1/\text{rate}$ 4nd burst tolerance $\tau = T \cdot (\text{burst} - 1)$, a request at `now_ns` is allowed iff `now_ns + tau >= tat`:

```rust
use std::collections::HashMap;

pub struct GcraLimiter {
    emission_interval_ns: u64,
    burst_tolerance_ns: u64,
    tats: HashMap<String, u64>,
}

impl GcraLimiter {
    pub fn new(rate_per_sec: f64, burst: u32) -> Self {
        assert!(rate_per_sec > 0.0 && burst >= 1);
        let interval = (1_000_000_000.0 / rate_per_sec) as u64;
        let tolerance = interval.saturating_mul((burst - 1) as u64);
        Self {
            emission_interval_ns: interval,
            burst_tolerance_ns: tolerance,
            tats: HashMap::new(),
        }
    }

    /// Returns Ok(()) if permitted, or Err(retry_after_ns) if rate-limited.
    pub fn allow(&mut self, key: &str, now_ns: u64) -> Result<(), u64> {
        let tat = self.tats.get(key).copied().unwrap_or(now_ns);
        let effective_tat = tat.max(now_ns);
        let allow_at = effective_tat.saturating_sub(self.burst_tolerance_ns);

        if now_ns < allow_at {
            return Err(allow_at - now_ns);
        }

        let next_tat = effective_tat.saturating_add(self.emission_interval_ns);
        self.tats.insert(key.to_owned(), next_tat);
        Ok(())
    }
}
```

