```ts
export class BoundedHashRing {
  private ring: Array<{ hash: number; shard: string }> = [];
  private loads = new Map<string, number>();
  private totalLoad = 0;

  constructor(shards: string[], vnodes = 64, private readonly factor = 1.25) {
    for (const s of shards) {
      this.loads.set(s, 0);
      for (let i = 0; i < vnodes; i++) {
        this.ring.push({ hash: fnv1a32(`${s}#${i}`), shard: s });
      }
    }
    this.ring.sort((a, b) => a.hash - b.hash);
  }

  acquire(key: string): string {
    const cap = Math.ceil(((this.totalLoad + 1) * this.factor) / this.loads.size);
    const h = fnv1a32(key);
    let idx = lowerBound(this.ring, h);
    for (let step = 0; step < this.ring.length; step++) {
      const cand = this.ring[(idx + step) % this.ring.length]!.shard;
      const cur = this.loads.get(cand) ?? 0;
      if (cur < cap) {
        this.loads.set(cand, cur + 1);
        this.totalLoad += 1;
        return cand;
      }
    }
    throw new Error("ring capacity invariant violated");
  }
}
```

