```go
package lfu

import "container/list"

type entry struct {
    key, val int
    freq     int
}

type Cache struct {
    cap     int
    minFreq int
    items   map[int]*list.Element
    buckets map[int]*list.List
}

func New(cap int) *Cache {
    return &Cache{
        cap:     cap,
        items:   make(map[int]*list.Element, cap),
        buckets: make(map[int]*list.List),
    }
}

func (c *Cache) touch(el *list.Element) {
    e := el.Value.(*entry)
    oldList := c.buckets[e.freq]
    oldList.Remove(el)
    if oldList.Len() == 0 {
        delete(c.buckets, e.freq)
        if c.minFreq == e.freq {
            c.minFreq++
        }
    }
    e.freq++
    if c.buckets[e.freq] == nil {
        c.buckets[e.freq] = list.New()
    }
    c.items[e.key] = c.buckets[e.freq].PushFront(e)
}

func (c *Cache) Get(key int) (int, bool) {
    el, ok := c.items[key]
    if !ok {
        return 0, false
    }
    c.touch(el)
    return el.Value.(*entry).val, true
}

func (c *Cache) Put(key, val int) {
    if c.cap <= 0 {
        return
    }
    if el, ok := c.items[key]; ok {
        el.Value.(*entry).val = val
        c.touch(el)
        return
    }
    if len(c.items) == c.cap {
        b := c.buckets[c.minFreq]
        victim := b.Back()
        b.Remove(victim)
        delete(c.items, victim.Value.(*entry).key)
    }
    c.minFreq = 1
    if c.buckets[1] == nil {
        c.buckets[1] = list.New()
    }
    c.items[key] = c.buckets[1].PushFront(&entry{key: key, val: val, freq: 1})
}
```

