class FreeSpaceMap:
    def __init__(self, num_pages: int, initial_free: int = 8168) -> None:
        size = 1
        while size < max(1, num_pages):
            size <<= 1
        self.num_pages = num_pages
        self.leaf_base = size
        self.tree = [0] * (2 * size)
        for p in range(num_pages):
            self.tree[self.leaf_base + p] = initial_free
        for idx in range(self.leaf_base - 1, 0, -1):
            self.tree[idx] = max(self.tree[2 * idx], self.tree[2 * idx + 1])

    def record_free_space(self, page_id: int, free_bytes: int) -> None:
        idx = self.leaf_base + page_id
        self.tree[idx] = max(0, free_bytes)
        idx >>= 1
        while idx >= 1:
            self.tree[idx] = max(self.tree[2 * idx], self.tree[2 * idx + 1])
            idx >>= 1

    def find_and_allocate(self, needed: int) -> int | None:
        if self.tree[1] < needed:
            return None  # must extend relation with a new 8KB page
        idx = 1
        while idx < self.leaf_base:
            left = 2 * idx
            idx = left if self.tree[left] >= needed else left + 1
        page_id = idx - self.leaf_base
        self.record_free_space(page_id, self.tree[idx] - needed)
        return page_id
```

