```python
from dataclasses import dataclass, field
from typing import Iterable


@dataclass
class _TrieNode:
    children: dict[str, "_TrieNode"] = field(default_factory=dict)
    targets: set[str] = field(default_factory=set)


class PathRuleTrie:
    def __init__(self) -> None:
        self._root = _TrieNode()

    def add_rule(self, pattern: str, target: str) -> None:
        node = self._root
        for seg in (s for s in pattern.strip("/").split("/") if s):
            node = node.children.setdefault(seg, _TrieNode())
        node.targets.add(target)

    def match_files(self, paths: Iterable[str]) -> set[str]:
        matched: set[str] = set()
        for raw_path in paths:
            segs = [s for s in raw_path.strip("/").split("/") if s]
            matched.update(self._match_one(segs))
        return matched

    def _match_one(self, segs: list[str]) -> set[str]:
        n = len(segs)
        hits: set[str] = set()
        seen: set[tuple[int, int]] = set()
        stack: list[tuple[_TrieNode, int]] = [(self._root, 0)]

        while stack:
            node, idx = stack.pop()
            state = (id(node), idx)
            if state in seen:
                continue
            seen.add(state)

            star2 = node.children.get("**")
            if star2 is not None:
                stack.append((star2, idx))
                if idx < n:
                    stack.append((node, idx + 1))

            if idx == n:
                hits.update(node.targets)
                continue

            seg = segs[idx]
            lit = node.children.get(seg)
            if lit is not None:
                stack.append((lit, idx + 1))
            star1 = node.children.get("*")
            if star1 is not None:
                stack.append((star1, idx + 1))

        return hits
```

