```rust
pub struct TinySketch {
    words: Vec<u64>, // 16 x 4-bit counters per u64
    mask: usize,
    ops: usize,
    reset_at: usize,
}

impl TinySketch {
    pub fn new(counters_pow2: usize) -> Self {
        assert!(counters_pow2 >= 16 && counters_pow2.is_power_of_two());
        let n_words = counters_pow2 / 16;
        Self { words: vec![0; n_words], mask: counters_pow2 - 1, ops: 0, reset_at: counters_pow2 * 10 }
    }

    fn seeds(h: u64) -> [u64; 4] {
        [
            h,
            h.wrapping_mul(0x9e3779b97f4a7c15),
            h.wrapping_mul(0xbf58476d1ce4e5b9),
            h.wrapping_mul(0x94d049bb133111eb),
        ]
    }

    pub fn record(&mut self, hash: u64) {
        for s in Self::seeds(hash) {
            let idx = (s as usize) & self.mask;
            let shift = (idx & 15) * 4;
            let w = &mut self.words[idx >> 4];
            let cur = (*w >> shift) & 0xF;
            if cur < 15 {
                *w += 1u64 << shift;
            }
        }
        self.ops += 1;
        if self.ops >= self.reset_at {
            for w in &mut self.words {
                *w = (*w >> 1) & 0x7777_7777_7777_7777;
            }
            self.ops = 0;
        }
    }

    pub fn estimate(&self, hash: u64) -> u8 {
        Self::seeds(hash)
            .into_iter()
            .map(|s| {
                let idx = (s as usize) & self.mask;
                ((self.words[idx >> 4] >> ((idx & 15) * 4)) & 0xF) as u8
            })
            .min()
            .unwrap_or(0)
    }
}
```

