        return int.from_bytes(h, "little") % self.w

    def add(self, key: str, count: int = 1) -> int:
        est = 1 << 63
        for r in range(self.d):
            idx = self._slot(key, r)
            val = self.rows[r][idx] + count
            self.rows[r][idx] = val
            if val < est:
                est = val
