from collections.abc import Hashable

def find_bridges[T: Hashable](adj: dict[T, list[T]]) -> list[tuple[T, T]]:
    timer = 0
    tin: dict[T, int] = {}
    low: dict[T, int] = {}
    bridges: list[tuple[T, T]] = []

    for root in adj:
        if root in tin:
            continue
        stack: list[tuple[T, T | None, int]] = [(root, None, 0)]
        tin[root] = low[root] = timer
        timer += 1

        while stack:
            u, parent, idx = stack[-1]
            nbrs = adj.get(u, [])
            if idx < len(nbrs):
                v = nbrs[idx]
                stack[-1] = (u, parent, idx + 1)
                if v == parent:
                    continue
                if v in tin:
                    low[u] = min(low[u], tin[v])
                else:
                    tin[v] = low[v] = timer
                    timer += 1
                    stack.append((v, u, 0))
            else:
                stack.pop()
                if parent is not None:
                    low[parent] = min(low[parent], low[u])
                    if low[u] > tin[parent]:
                        bridges.append((parent, u))
    return bridges
```

