```go
package skiplist

import "math/rand/v2"

const maxLevel = 16

type node struct {
    key  int
    val  string
    next [maxLevel]*node
}

type SkipList struct {
    head  *node
    level int
}

func New() *SkipList {
    return &SkipList{head: &node{}, level: 1}
}

func randomLevel() int {
    lvl := 1
    for lvl < maxLevel && (rand.Uint32()&3) == 0 { // p = 0.25
        lvl++
    }
    return lvl
}

func (s *SkipList) Search(key int) (string, bool) {
    cur := s.head
    for i := s.level - 1; i >= 0; i-- {
        for cur.next[i] != nil && cur.next[i].key < key {
            cur = cur.next[i]
        }
    }
    cur = cur.next[0]
    if cur != nil && cur.key == key {
        return cur.val, true
    }
    return "", false
}

func (s *SkipList) Insert(key int, val string) {
    var update [maxLevel]*node
    cur := s.head
    for i := s.level - 1; i >= 0; i-- {
        for cur.next[i] != nil && cur.next[i].key < key {
            cur = cur.next[i]
        }
        update[i] = cur
    }
    if cur.next[0] != nil && cur.next[0].key == key {
        cur.next[0].val = val
        return
    }
    lvl := randomLevel()
    if lvl > s.level {
        for i := s.level; i < lvl; i++ {
            update[i] = s.head
        }
        s.level = lvl
    }
    n := &node{key: key, val: val}
    for i := 0; i < lvl; i++ {
        n.next[i] = update[i].next[i]
        update[i].next[i] = n
    }
}
```

