```rust
pub struct MaxSegTree {
    n: usize,
    tree: Vec<i64>,
}

impl MaxSegTree {
    pub fn from_slice(values: &[i64]) -> Self {
        let n = values.len();
        let mut tree = vec![i64::MIN; 2 * n];
        tree[n..2 * n].copy_from_slice(values);
        for i in (1..n).rev() {
            tree[i] = tree[2 * i].max(tree[2 * i + 1]);
        }
        Self { n, tree }
    }

    pub fn update(&mut self, mut pos: usize, val: i64) {
        pos += self.n;
        self.tree[pos] = val;
        while pos > 1 {
            pos >>= 1;
            self.tree[pos] = self.tree[2 * pos].max(self.tree[2 * pos + 1]);
        }
    }

    pub fn query_max(&self, mut l: usize, mut r: usize) -> i64 {
        let mut res = i64::MIN;
        l += self.n;
        r += self.n;
        while l < r {
            if (l & 1) == 1 {
                res = res.max(self.tree[l]);
                l += 1;
            }
            if (r & 1) == 1 {
                r -= 1;
                res = res.max(self.tree[r]);
            }
            l >>= 1;
            r >>= 1;
        }
        res
    }
}
```

