```go
package logmerge

import "container/heap"

type LogEntry struct {
	TimestampNano int64
	Shard         int
	Line          string
}

type heapNode struct {
	entry LogEntry
	src   <-chan LogEntry
}

type minHeap []heapNode

func (h minHeap) Len() int { return len(h) }
func (h minHeap) Less(i, j int) bool {
	if h[i].entry.TimestampNano != h[j].entry.TimestampNano {
		return h[i].entry.TimestampNano < h[j].entry.TimestampNano
	}
	return h[i].entry.Shard < h[j].entry.Shard
}
func (h minHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x interface{}) { *h = append(*h, x.(heapNode)) }
func (h *minHeap) Pop() interface{} {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func MergeLogStreams(streams []<-chan LogEntry) <-chan LogEntry {
	out := make(chan LogEntry, 64)
	go func() {
		defer close(out)
		h := make(minHeap, 0, len(streams))
		for _, ch := range streams {
			if first, ok := <-ch; ok {
				h = append(h, heapNode{entry: first, src: ch})
			}
		}
		heap.Init(&h)

		for h.Len() > 0 {
			smallest := heap.Pop(&h).(heapNode)
			out <- smallest.entry
			if next, ok := <-smallest.src; ok {
				heap.Push(&h, heapNode{entry: next, src: smallest.src})
			}
		}
	}()
	return out
}
```

