class LogHistogram:
    def __init__(self, gamma: float = 1.02) -> None:
        self.gamma = gamma
        self.inv_ln = 1.0 / math.log(gamma)
        self.buckets: Counter[int] = Counter()
        self.total = 0

    def record(self, value: float) -> None:
