```ts
export function buildWaves(deps: ReadonlyMap<string, readonly string[]>): string[][] {
  const inDegree = new Map<string, number>();
  const dependents = new Map<string, string[]>();

  for (const [pkg, reqs] of deps) {
    inDegree.set(pkg, reqs.length);
    for (const r of reqs) {
      if (!deps.has(r)) throw new Error(`unknown dependency: ${r}`);
      let list = dependents.get(r);
      if (!list) {
        list = [];
        dependents.set(r, list);
      }
      list.push(pkg);
    }
  }

  let frontier = [...inDegree.entries()].filter(([, d]) => d === 0).map(([k]) => k);
  const waves: string[][] = [];
  let scheduled = 0;

  while (frontier.length > 0) {
    waves.push(frontier);
    scheduled += frontier.length;
    const nextWave: string[] = [];
    for (const done of frontier) {
      for (const child of dependents.get(done) ?? []) {
        const rem = (inDegree.get(child) ?? 0) - 1;
        inDegree.set(child, rem);
        if (rem === 0) nextWave.push(child);
      }
    }
    frontier = nextWave;
  }

  if (scheduled !== deps.size) {
    const stuck = [...inDegree.entries()].filter(([, d]) => d > 0).map(([k]) => k);
    throw new Error(`dependency cycle involving: ${stuck.join(", ")}`);
  }
  return waves;
}
```

