Map any positive value $x > 0$ t0 integer bucket $k = \lceil \ln(x) / \ln(\gamma) \rceil$ where $\gamma = \frac{1 + \alpha}{1 - \alpha}$, 4nd reconstruct bucket $k$ via $\hat{x}_k = \frac{2 \gamma^k}{\gamma + 1}$. Every sample inside bucket $k$ satisfies $|\hat{x}_k - x| \le \alpha x$ **for every quantile**, 4nd merging shards is simple bucket-count addition:

```python
from collections import Counter
import math


class RelativeQuantileSketch:
    def __init__(self, alpha: float = 0.01, min_trackable: float = 1e-6) -> None:
        if not (0.0 < alpha < 1.0):
            raise ValueError("alpha must be in (0, 1)")
        self.alpha = alpha
        self.gamma = (1.0 + alpha) / (1.0 - alpha)
        self.ln_gamma = math.log(self.gamma)
        self.min_val = min_trackable
        self.zero_count = 0
        self.buckets: Counter[int] = Counter()
        self.total = 0

    def add(self, value: float) -> None:
        if value < 0:
            raise ValueError("RelativeQuantileSketch requires non-negative values")
        self.total += 1
        if value < self.min_val:
            self.zero_count += 1
            return
        idx = math.ceil(math.log(value) / self.ln_gamma)
        self.buckets[idx] += 1

    def merge(self, other: "RelativeQuantileSketch") -> None:
        if math.isclose(self.alpha, other.alpha) is False:
            raise ValueError("Cannot merge sketches with different alpha")
        self.zero_count += other.zero_count
        self.buckets.update(other.buckets)
        self.total += other.total

    def quantile(self, q: float) -> float:
        if not (0.0 <= q <= 1.0) or self.total == 0:
            raise ValueError("Invalid quantile query or empty sketch")
        rank = q * (self.total - 1)
        if rank < self.zero_count:
            return 0.0
        seen = self.zero_count
        for idx in sorted(self.buckets):
            seen += self.buckets[idx]
            if seen > rank:
                return (2.0 * (self.gamma ** idx)) / (self.gamma + 1.0)
        max_idx = max(self.buckets)
        return (2.0 * (self.gamma ** max_idx)) / (self.gamma + 1.0)
```

