from dataclasses import dataclass

@dataclass
class BufferDesc:
    tag: tuple[int, int] | None = None
    usage_count: int = 0
    pin_count: int = 0

class ClockSweepBufferPool:
    MAX_USAGE = 5

    def __init__(self, size: int) -> None:
        self.pool = [BufferDesc() for _ in range(size)]
        self.page_table: dict[tuple[int, int], int] = {}
        self.clock_hand = 0

    def read_page(self, rel_id: int, block_no: int, bulk_ring_slot: int | None = None) -> int:
        tag = (rel_id, block_no)
        if tag in self.page_table:
            slot = self.page_table[tag]
            buf = self.pool[slot]
            if buf.usage_count < self.MAX_USAGE:
                buf.usage_count += 1
            return slot

        if bulk_ring_slot is not None and self.pool[bulk_ring_slot].pin_count == 0:
            slot = bulk_ring_slot
        else:
            slot = self._evict_victim()

        old_tag = self.pool[slot].tag
        if old_tag is not None:
            self.page_table.pop(old_tag, None)
        self.pool[slot] = BufferDesc(tag=tag, usage_count=1, pin_count=0)
        self.page_table[tag] = slot
        return slot

    def _evict_victim(self) -> int:
        n = len(self.pool)
        while True:
            slot = self.clock_hand
            self.clock_hand = (self.clock_hand + 1) % n
            buf = self.pool[slot]
            if buf.pin_count > 0:
                continue
            if buf.usage_count == 0:
                return slot
            buf.usage_count -= 1
