```python
def sort_merge_join(
    left: list[tuple[int, str]],
    right: list[tuple[int, str]],
) -> list[tuple[int, str, str]]:
    out: list[tuple[int, str, str]] = []
    i, j = 0, 0
    n, m = len(left), len(right)
    mark: int | None = None

    while i < n and (j < m or mark is not None):
        if mark is None:
            while i < n and j < m and left[i][0] != right[j][0]:
                if left[i][0] < right[j][0]:
                    i += 1
                else:
                    j += 1
            if i >= n or j >= m:
                break
            mark = j

        if j < m and left[i][0] == right[j][0]:
            out.append((left[i][0], left[i][1], right[j][1]))
            j += 1
        else:
            next_same_key = (i + 1 < n) and (left[i + 1][0] == left[i][0])
            i += 1
            if next_same_key:
                j = mark  # rewind inner stream to start of duplicate group
            else:
                mark = None
    return out
```

