```python
from collections import deque
from collections.abc import Hashable

def hopcroft_karp[U: Hashable, V: Hashable](
    adj: dict[U, list[V]],
) -> dict[U, V]:
    pair_u: dict[U, V] = {}
    pair_v: dict[V, U] = {}
    inf = 10**9

    while True:
        dist: dict[U, int] = {}
        q: deque[U] = deque()
        for u in adj:
            if u not in pair_u:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = inf

        found_augmenting = False
        while q:
            u = q.popleft()
            for v in adj[u]:
                u2 = pair_v.get(v)
                if u2 is None:
                    found_augmenting = True
                elif dist[u2] == inf:
                    dist[u2] = dist[u] + 1
                    q.append(u2)

        if not found_augmenting:
            break

        def dfs(u_curr: U) -> bool:
            for v in adj[u_curr]:
                u_next = pair_v.get(v)
                if u_next is None or (
                    dist[u_next] == dist[u_curr] + 1 and dfs(u_next)
                ):
                    pair_u[u_curr] = v
                    pair_v[v] = u_curr
                    return True
            dist[u_curr] = inf
            return False

        for u in adj:
            if u not in pair_u:
                dfs(u)

    return pair_u
```

