```python
from collections.abc import Hashable

def articulation_points[T: Hashable](adj: dict[T, list[T]]) -> set[T]:
    timer = 0
    tin: dict[T, int] = {}
    low: dict[T, int] = {}
    cuts: set[T] = set()

    for root in adj:
        if root in tin:
            continue
        tin[root] = low[root] = timer
        timer += 1
        root_children = 0
        stack: list[tuple[T, T | None, int]] = [(root, None, 0)]

        while stack:
            u, parent, idx = stack[-1]
            nbrs = adj.get(u, [])
            if idx < len(nbrs):
                v = nbrs[idx]
                stack[-1] = (u, parent, idx + 1)
                if v == parent:
                    continue
                if v in tin:
                    low[u] = min(low[u], tin[v])
                else:
                    if parent is None:
                        root_children += 1
                    tin[v] = low[v] = timer
                    timer += 1
                    stack.append((v, u, 0))
            else:
                stack.pop()
                if parent is not None:
                    low[parent] = min(low[parent], low[u])
                    if parent != root and low[u] >= tin[parent]:
                        cuts.add(parent)

        if root_children >= 2:
            cuts.add(root)

    return cuts
```

