package runner

import (
	"bytes"
	"context"
	"os/exec"
	"syscall"
	"time"
)

func RunStep(ctx context.Context, script string) (string, error) {
	cmd := exec.CommandContext(ctx, "/bin/sh", "-c", script)
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}

	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out

	// Send SIGTERM to the ENTIRE process group (-pgid) on context cancel!
	cmd.Cancel = func() error {
		if cmd.Process == nil {
