		return syscall.Kill(-cmd.Process.Pid, syscall.SIGTERM)
	}
	// If grandchildren ignore SIGTERM or hold pipes open past 5s, close pipes & SIGKILL!
	cmd.WaitDelay = 5 * time.Second

	err := cmd.Run()
	return out.String(), err
}
