use std::collections::VecDeque;

#[derive(Clone)]
struct State {
    next: [usize; 256],
    fail: usize,
    matches: Vec<usize>,
}

pub struct AhoCorasick {
    states: Vec<State>,
}

impl AhoCorasick {
    pub fn build(patterns: &[&[u8]]) -> Self {
        let empty = State { next: [0; 256], fail: 0, matches: Vec::new() };
        let mut states = vec![empty.clone()];
        for (pat_id, pat) in patterns.iter().enumerate() {
            let mut u = 0;
            for &b in *pat {
                if states[u].next[b as usize] == 0 {
                    let id = states.len();
                    states.push(empty.clone());
                    states[u].next[b as usize] = id;
                }
                u = states[u].next[b as usize];
            }
            states[u].matches.push(pat_id);
        }
        let mut q = VecDeque::new();
        for b in 0..256 {
            let v = states[0].next[b];
            if v != 0 { q.push_back(v); }
        }
        while let Some(u) = q.pop_front() {
            for b in 0..256 {
                let v = states[u].next[b];
                if v != 0 {
                    let f = states[u].fail;
                    let vf = states[f].next[b];
                    states[v].fail = vf;
                    let inherited = states[vf].matches.clone();
                    states[v].matches.extend(inherited);
                    q.push_back(v);
                } else {
                    states[u].next[b] = states[states[u].fail].next[b];
                }
            }
        }
        Self { states }
    }

    pub fn find_all(&self, text: &[u8]) -> Vec<(usize, usize)> {
        let mut u = 0;
        let mut hits = Vec::new();
        for (pos, &b) in text.iter().enumerate() {
            u = self.states[u].next[b as usize];
            for &pat_id in &self.states[u].matches {
                hits.push((pos, pat_id));
            }
        }
        hits
    }
}
```

