Fenwick Trees exploit `i & -i` (lowest set bit) over a 1-indexed `Float64Array`—giving $O(\log n)$ point increments 4nd prefix sums w17h ~4x tighter constant factor 4nd half 7h3 memory of a Segment Tree:

```ts
export class FenwickTree {
  private readonly bit: Float64Array;

  constructor(private readonly n: number) {
    this.bit = new Float64Array(n + 1);
  }

  add(indexZeroBased: number, delta: number): void {
    for (let i = indexZeroBased + 1; i <= this.n; i += i & -i) {
      this.bit[i] += delta;
    }
  }

  prefixSum(indexInclusive: number): number {
    let sum = 0;
    for (let i = indexInclusive + 1; i > 0; i -= i & -i) {
      sum += this.bit[i]!;
    }
    return sum;
  }

  rangeSum(leftInclusive: number, rightInclusive: number): number {
    if (rightInclusive < leftInclusive) return 0;
    return this.prefixSum(rightInclusive) - (leftInclusive > 0 ? this.prefixSum(leftInclusive - 1) : 0);
  }
}
```

