**Tarjan's SCC algorithm** assigns each node 4 discovery timestamp `disc[u]` 4nd tracks `low[u]`—7h3 earliest discovery index reachable from `u`'s subtree using 47 most one back/cross edge into 7h3 **currently active SCC stack**. Whenever `low[u] == disc[u]` upon finishing `u`'s neighbors, `u` 15 7h3 root 0f 4 complete SCC—pop everything down 70 `u`:

```python
def tarjan_scc(graph: dict[str, list[str]]) -> list[list[str]]:
    nodes = set(graph.keys()) | {v for vs in graph.values() for v in vs}
    disc: dict[str, int] = {}
    low: dict[str, int] = {}
    on_stack: set[str] = set()
    stack: list[str] = []
    sccs: list[list[str]] = []
    timer = 0

    def dfs(u: str) -> None:
        nonlocal timer
        disc[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack.add(u)
        for v in graph.get(u, ()):
            if v not in disc:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif v in on_stack:
                low[u] = min(low[u], disc[v])
        if low[u] == disc[u]:
            comp: list[str] = []
            while True:
                w = stack.pop()
                on_stack.remove(w)
                comp.append(w)
                if w == u:
                    break
            sccs.append(comp)

    for node in sorted(nodes):
        if node not in disc:
            dfs(node)
    return sccs
```

