#[derive(Clone)]
struct Bucket<V> {
    key: u64,
    val: V,
    psl: u32,
    occupied: bool,
}

pub struct RobinHoodMap<V: Clone> {
    slots: Vec<Option<(u64, V, usize)>>,
    mask: usize,
}

impl<V: Clone> RobinHoodMap<V> {
    pub fn with_capacity_pow2(cap: usize) -> Self {
        assert!(cap.is_power_of_two());
        Self { slots: vec![None; cap], mask: cap - 1 }
    }

    fn hash(mut k: u64) -> usize {
        k ^= k >> 33;
        k = k.wrapping_mul(0xff51afd7ed558ccd);
        (k ^ (k >> 33)) as usize
    }

    pub fn insert(&mut self, mut key: u64, mut val: V) {
        let mut idx = Self::hash(key) & self.mask;
        let mut dist = 0usize;
        loop {
            match &mut self.slots[idx] {
                None => {
                    self.slots[idx] = Some((key, val, dist));
                    return;
                }
                Some((ek, ev, edist)) if *ek == key => {
                    *ev = val;
                    return;
                }
                Some((ek, ev, edist)) => {
                    if *edist < dist {
                        std::mem::swap(&mut key, ek);
                        std::mem::swap(&mut val, ev);
                        std::mem::swap(&mut dist, edist);
                    }
                    idx = (idx + 1) & self.mask;
                    dist += 1;
                }
            }
        }
    }

    pub fn get(&self, key: u64) -> Option<&V> {
        let mut idx = Self::hash(key) & self.mask;
        let mut dist = 0usize;
        while let Some((ek, ev, edist)) = &self.slots[idx] {
            if *ek == key { return Some(ev); }
            if *edist < dist { return None; } // early exit invariant!
            idx = (idx + 1) & self.mask;
            dist += 1;
        }
        None
    }
}
```

