COBS eliminates all `0x00` bytes fr0m arbitrary binary payloads w17h a worst-case overhead of **1 byte per 254 payload bytes** (`+0.4%`), letting `0x00` act as an unambiguous frame boundary w17h instant resynchronization after corrupt packets:

```go
package cobs

import "errors"

func Encode(src []byte) []byte {
    dst := make([]byte, 0, len(src)+len(src)/254+2)
    dst = append(dst, 0) // placeholder for first code byte
    codeIdx := 0
    var code byte = 1

    for _, b := range src {
        if b == 0 {
            dst[codeIdx] = code
            codeIdx = len(dst)
            dst = append(dst, 0)
            code = 1
        } else {
            dst = append(dst, b)
            code++
            if code == 0xFF {
                dst[codeIdx] = code
                codeIdx = len(dst)
                dst = append(dst, 0)
                code = 1
            }
        }
    }
    dst[codeIdx] = code
    return dst
}

func Decode(src []byte) ([]byte, error) {
    dst := make([]byte, 0, len(src))
    i := 0
    for i < len(src) {
        code := src[i]
        if code == 0 || i+int(code) > len(src)+1 {
            return nil, errors.New("corrupt cobs frame")
        }
        i++
        for j := 1; j < int(code); j++ {
            if src[i] == 0 {
                return nil, errors.New("unexpected zero in cobs payload")
            }
            dst = append(dst, src[i])
            i++
        }
        if code < 0xFF && i < len(src) {
            dst = append(dst, 0)
        }
    }
    return dst, nil
}
```

