```python
from collections import Counter
import heapq

def sliding_median(nums: list[float], w: int) -> list[float]:
    lo: list[float] = []  # max-heap via negated values
    hi: list[float] = []  # min-heap
    delayed: Counter[float] = Counter()
    lo_sz = hi_sz = 0

    def prune_lo() -> None:
        while lo and delayed[-lo[0]] > 0:
            delayed[-heapq.heappop(lo)] -= 1

    def prune_hi() -> None:
        while hi and delayed[hi[0]] > 0:
            delayed[heapq.heappop(hi)] -= 1

    def rebalance() -> None:
        nonlocal lo_sz, hi_sz
        if lo_sz > hi_sz + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
            lo_sz -= 1
            hi_sz += 1
            prune_lo()
        elif lo_sz < hi_sz:
            heapq.heappush(lo, -heapq.heappop(hi))
            hi_sz -= 1
            lo_sz += 1
            prune_hi()

    out: list[float] = []
    for i, x in enumerate(nums):
        if not lo or x <= -lo[0]:
            heapq.heappush(lo, -x)
            lo_sz += 1
        else:
            heapq.heappush(hi, x)
            hi_sz += 1
        if i >= w:
            old = nums[i - w]
            delayed[old] += 1
            if old <= -lo[0]:
                lo_sz -= 1
                if old == -lo[0]:
                    prune_lo()
            else:
                hi_sz -= 1
                if hi and old == hi[0]:
                    prune_hi()
        rebalance()
        if i >= w - 1:
            out.append(-lo[0] if w % 2 == 1 else 0.5 * (-lo[0] + hi[0]))
    return out
```

