  for (let j = 1; j <= n; j++) {
    curr[0] = j;
    let rowMin = j;
    const bj = b.charCodeAt(j - 1);
    for (let i = 1; i <= m; i++) {
      const cost = a.charCodeAt(i - 1) === bj ? 0 : 1;
      const val = Math.min(
        prev[i]! + 1,
        curr[i - 1]! + 1,
        prev[i - 1]! + cost,
      );
      curr[i] = val;
      if (val < rowMin) rowMin = val;
    }
    if (rowMin > maxDist) return null;
    [prev, curr] = [curr, prev];
  }
  return prev[m]! <= maxDist ? prev[m]! : null;
}
