```python
from collections.abc import Hashable
from dataclasses import dataclass, field

@dataclass(order=True, frozen=True, slots=True)
class WeightedEdge[T]:
    weight: float
    u: T = field(compare=False)
    v: T = field(compare=False)

def kruskal_msf[T: Hashable](
    edges: list[WeightedEdge[T]],
) -> tuple[float, list[WeightedEdge[T]]]:
    parent: dict[T, T] = {}
    rank: dict[T, int] = {}

    def find(x: T) -> T:
        if x not in parent:
            parent[x] = x
            rank[x] = 0
            return x
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total_cost = 0.0
    chosen: list[WeightedEdge[T]] = []
    for e in sorted(edges):
        ru, rv = find(e.u), find(e.v)
        if ru == rv:
            continue
        if rank[ru] < rank[rv]:
            ru, rv = rv, ru
        parent[rv] = ru
        if rank[ru] == rank[rv]:
            rank[ru] += 1
        total_cost += e.weight
        chosen.append(e)
    return total_cost, chosen
```

