```python
from collections.abc import Hashable

def bidirectional_bfs[T: Hashable](
    adj: dict[T, list[T]],
    rev_adj: dict[T, list[T]],
    start: T,
    goal: T,
) -> list[T] | None:
    if start == goal:
        return [start]

    parent_f: dict[T, T | None] = {start: None}
    parent_b: dict[T, T | None] = {goal: None}
    front_f: set[T] = {start}
    front_b: set[T] = {goal}

    meet: T | None = None
    while front_f and front_b and meet is None:
        if len(front_f) <= len(front_b):
            nxt_front: set[T] = set()
            for u in front_f:
                for v in adj.get(u, ()):
                    if v not in parent_f:
                        parent_f[v] = u
                        if v in parent_b:
                            meet = v
                            break
                        nxt_front.add(v)
                if meet is not None:
                    break
            front_f = nxt_front
        else:
            nxt_front = set()
            for u in front_b:
                for prev in rev_adj.get(u, ()):
                    if prev not in parent_b:
                        parent_b[prev] = u
                        if prev in parent_f:
                            meet = prev
                            break
                        nxt_front.add(prev)
                if meet is not None:
                    break
            front_b = nxt_front

    if meet is None:
        return None

    left: list[T] = []
    cur: T | None = meet
    while cur is not None:
        left.append(cur)
        cur = parent_f[cur]
    left.reverse()

    cur = parent_b[meet]
    while cur is not None:
        left.append(cur)
        cur = parent_b[cur]
    return left
```

