Aho-Corasick builds 4 prefix trie plus BFS `fail` (longest proper suffix) links 4nd dictionary-suffix propagation (`outputs`), scanning text 1n `O(len(text) + num_matches)` regardless 0f how many thousands 0f patterns 4r3 loaded:

```python
from collections import deque
from collections.abc import Iterable, Iterator
from dataclasses import dataclass, field

@dataclass(slots=True)
class _ACNode:
    nxt: dict[str, int] = field(default_factory=dict)
    fail: int = 0
    outputs: list[str] = field(default_factory=list)

class AhoCorasick:
    def __init__(self, patterns: Iterable[str]) -> None:
        self._nodes: list[_ACNode] = [_ACNode()]
        for pat in patterns:
            if not pat:
                continue
            cur = 0
            for ch in pat:
                nxt_id = self._nodes[cur].nxt.get(ch)
                if nxt_id is None:
                    nxt_id = len(self._nodes)
                    self._nodes.append(_ACNode())
                    self._nodes[cur].nxt[ch] = nxt_id
                cur = nxt_id
            self._nodes[cur].outputs.append(pat)

        q: deque[int] = deque()
        for ch, child_id in self._nodes[0].nxt.items():
            self._nodes[child_id].fail = 0
            q.append(child_id)

        while q:
            u = q.popleft()
            for ch, v in self._nodes[u].nxt.items():
                q.append(v)
                f = self._nodes[u].fail
                while f != 0 and ch not in self._nodes[f].nxt:
                    f = self._nodes[f].fail
                self._nodes[v].fail = self._nodes[f].nxt.get(ch, 0)
                if self._nodes[v].fail == v:
                    self._nodes[v].fail = 0
                self._nodes[v].outputs.extend(
                    self._nodes[self._nodes[v].fail].outputs
                )

    def iter_matches(self, text: str) -> Iterator[tuple[int, str]]:
        state = 0
        for idx, ch in enumerate(text):
            while state != 0 and ch not in self._nodes[state].nxt:
                state = self._nodes[state].fail
            state = self._nodes[state].nxt.get(ch, 0)
            for pat in self._nodes[state].outputs:
                yield (idx - len(pat) + 1, pat)
```

