```python
from collections.abc import Iterable, Iterator
from itertools import chain, groupby, repeat

def rle_encode[T](stream: Iterable[T]) -> Iterator[tuple[T, int]]:
    for val, grp in groupby(stream):
        count = sum(1 for _ in grp)
        yield (val, count)

