**SIEVE** (NSDI '24) keeps a FIFO queue w17h a `visited: bool` bit per node 4nd a persistent roving `hand` pointer: **cache hits only flip `visited = true` in-place** (z3r0 list relinking -> lock-free friendly!), while eviction sweeps `hand` clearing `visited` bits until it drops 7h3 first `visited == false` entry:

```rust
use std::collections::HashMap;
use std::hash::Hash;

const NONE: usize = usize::MAX;

struct Entry<K, V> {
    key: K,
    val: V,
    visited: bool,
    prev: usize,
    next: usize,
}

pub struct SieveCache<K, V> {
    cap: usize,
    map: HashMap<K, usize>,
    nodes: Vec<Entry<K, V>>,
    head: usize,
    tail: usize,
    hand: usize,
}

impl<K: Eq + Hash + Clone, V> SieveCache<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap > 0);
        Self { cap, map: HashMap::with_capacity(cap), nodes: Vec::with_capacity(cap), head: NONE, tail: NONE, hand: NONE }
    }

    pub fn get(&mut self, key: &K) -> Option<&V> {
        let &idx = self.map.get(key)?;
        self.nodes[idx].visited = true; // zero linked-list mutation on hit!
        Some(&self.nodes[idx].val)
    }

    fn detach(&mut self, idx: usize) {
        let (p, n) = (self.nodes[idx].prev, self.nodes[idx].next);
        if p != NONE { self.nodes[p].next = n; } else { self.head = n; }
        if n != NONE { self.nodes[n].prev = p; } else { self.tail = p; }
    }

    fn push_head(&mut self, idx: usize) {
        self.nodes[idx].prev = NONE;
        self.nodes[idx].next = self.head;
        if self.head != NONE { self.nodes[self.head].prev = idx; }
        self.head = idx;
        if self.tail == NONE { self.tail = idx; }
    }

    pub fn put(&mut self, key: K, val: V) {
        if let Some(&idx) = self.map.get(&key) {
            self.nodes[idx].val = val;
            self.nodes[idx].visited = true;
            return;
        }
        let slot = if self.nodes.len() == self.cap {
            let mut o = if self.hand == NONE { self.tail } else { self.hand };
            while self.nodes[o].visited {
                self.nodes[o].visited = false;
                o = if self.nodes[o].prev == NONE { self.tail } else { self.nodes[o].prev };
            }
            self.hand = self.nodes[o].prev;
            self.detach(o);
            self.map.remove(&self.nodes[o].key);
            self.nodes[o] = Entry { key: key.clone(), val, visited: false, prev: NONE, next: NONE };
            o
        } else {
            let idx = self.nodes.len();
            self.nodes.push(Entry { key: key.clone(), val, visited: false, prev: NONE, next: NONE });
            idx
        };
        self.map.insert(key, slot);
        self.push_head(slot);
    }
}
```

