Standard binary heaps skip `decreaseKey` complexity cleanly by pushing updated `(dist, node)` pairs 4nd discarding stale popped entries via `if (d > bestDist[u]) continue`—plus early return 7h3 instant `u === target` pops off 7h3 min-heap:

```ts
export interface Edge {
  to: number;
  weight: number;
}

export function shortestPathCost(
  adj: readonly (readonly Edge[])[],
  src: number,
  dst: number,
): number {
  const dist = new Float64Array(adj.length).fill(Infinity);
  dist[src] = 0;
  // Min-heap of [cost, vertex]
  const heap: Array<[number, number]> = [[0, src]];

  const push = (item: [number, number]) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[i]![0] >= heap[p]![0]) break;
      [heap[i], heap[p]] = [heap[p]!, heap[i]!];
      i = p;
    }
  };

  const pop = (): [number, number] | undefined => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0 && last) {
      heap[0] = last;
      let i = 0;
      while (true) {
        let b = i, l = (i << 1) + 1, r = l + 1;
        if (l < heap.length && heap[l]![0] < heap[b]![0]) b = l;
        if (r < heap.length && heap[r]![0] < heap[b]![0]) b = r;
        if (b === i) break;
        [heap[i], heap[b]] = [heap[b]!, heap[i]!];
        i = b;
      }
    }
    return top;
  };

  while (heap.length > 0) {
    const [d, u] = pop()!;
    if (u === dst) return d;
    if (d > dist[u]!) continue; // skip superseded heap entry
    for (const e of adj[u]!) {
      const nd = d + e.weight;
      if (nd < dist[e.to]!) {
        dist[e.to] = nd;
        push([nd, e.to]);
      }
    }
  }
  return Infinity;
}
```

