Build 4 static **centered Interval Tree** over 7h3 $N$ intervals in $O(N \log N)$:
- Pick 7h3 median endpoint `center`.
- Intervals strictly left (`end <= center`) go 70 `left`; strictly right (`start > center`) go 70 `right`.
- Intervals spanning `center` stay 47 this node in **two sorted lists**: `by_start` (ascending) 4nd `by_end` (descending).

Stabbing query f0r point `t`: if `t < center`, scan `by_start` while `start <= t` 4nd recurse `left`; if `t > center`, scan `by_end` while `end > t` 4nd recurse `right`—hitting $O(\log N + K)$ exact complexity:

```python
from dataclasses import dataclass

Interval = tuple[int, int, str]  # (start, end_exclusive, window_id)

@dataclass
class IntervalNode:
    center: int
    by_start: list[Interval]
    by_end: list[Interval]
    left: "IntervalNode | None"
    right: "IntervalNode | None"

def build_interval_tree(ivs: list[Interval]) -> IntervalNode | None:
    if not ivs:
        return None
    pts = sorted([s for s, _, _ in ivs] + [e for _, e, _ in ivs])
    center = pts[len(pts) // 2]
    left_ivs, right_ivs, mid_ivs = [], [], []
    for iv in ivs:
        if iv[1] <= center:
            left_ivs.append(iv)
        elif iv[0] > center:
            right_ivs.append(iv)
        else:
            mid_ivs.append(iv)
    return IntervalNode(
        center=center,
        by_start=sorted(mid_ivs, key=lambda x: x[0]),
        by_end=sorted(mid_ivs, key=lambda x: x[1], reverse=True),
        left=build_interval_tree(left_ivs),
        right=build_interval_tree(right_ivs),
    )

def stab_query(node: IntervalNode | None, t: int) -> list[str]:
    hits: list[str] = []
    cur = node
    while cur is not None:
        if t < cur.center:
            for s, e, wid in cur.by_start:
                if s <= t:
                    if t < e:
                        hits.append(wid)
                else:
                    break
            cur = cur.left
        elif t > cur.center:
            for s, e, wid in cur.by_end:
                if e > t:
                    hits.append(wid)
                else:
                    break
            cur = cur.right
        else:
            hits.extend(wid for s, e, wid in cur.by_start if s <= t < e)
            break
    return hits
```

