```python
def find_deadlock_victim(
    start_tx: int,
    waits_for: dict[int, set[int]],
    work_done: dict[int, int],
) -> tuple[list[int], int] | None:
    path: list[int] = [start_tx]
    on_path: dict[int, int] = {start_tx: 0}
    visited: set[int] = set()

    def dfs(curr: int) -> list[int] | None:
        for holder in sorted(waits_for.get(curr, ())):
            if holder == start_tx:
                return list(path)
            if holder in on_path or holder in visited:
                continue
            on_path[holder] = len(path)
            path.append(holder)
            cyc = dfs(holder)
            if cyc is not None:
                return cyc
            path.pop()
            del on_path[holder]
        visited.add(curr)
        return None

    cycle = dfs(start_tx)
    if cycle is None:
        return None
    victim = min(cycle, key=lambda tx: (work_done.get(tx, 0), -tx))
    return cycle, victim
```

