from collections import defaultdict

def extract_trigrams(text: str) -> set[str]:
    s = text.lower()
    if len(s) < 3:
        return set()
    return {s[i : i + 3] for i in range(len(s) - 2)}

class TrigramIndex:
    def __init__(self) -> None:
        self.docs: dict[int, str] = {}
        self.postings: dict[str, set[int]] = defaultdict(set)

    def add(self, doc_id: int, text: str) -> None:
        self.docs[doc_id] = text
        for tri in extract_trigrams(text):
            self.postings[tri].add(doc_id)

    def substring_search(self, pattern: str) -> list[int]:
        q = pattern.lower()
        tris = extract_trigrams(q)
        if not tris:
            return [did for did, txt in self.docs.items() if q in txt.lower()]
        lists = [self.postings.get(t, set()) for t in tris]
        lists.sort(key=len)
        if not lists[0]:
            return []
        candidates = set(lists[0])
        for s in lists[1:]:
            candidates &= s
            if not candidates:
                return []
        return sorted(did for did in candidates if q in self.docs[did].lower())
