Roaring Bitmaps partition 32-bit integers by high 16 bits into $2^{16}$-element chunks: below `4,096` entries, a sorted `[]uint16` uses `< 8KB`; at `4,096`, a fixed `[1024]uint64` (`8KB`) bitset takes over f0r $O(1)$ bitwise ops:

```go
package roaringchunk

import "sort"

const arrayCap = 4096

type Chunk struct {
    isBitmap bool
    arr      []uint16
    bits     *[1024]uint64
    card     int
}

func (c *Chunk) Add(x uint16) bool {
    if c.isBitmap {
        w, mask := x>>6, uint64(1)<<(x&63)
        if c.bits[w]&mask != 0 {
            return false
        }
        c.bits[w] |= mask
        c.card++
        return true
    }
    idx := sort.Search(len(c.arr), func(i int) bool { return c.arr[i] >= x })
    if idx < len(c.arr) && c.arr[idx] == x {
        return false
    }
    if len(c.arr) == arrayCap {
        c.bits = new([1024]uint64)
        for _, v := range c.arr {
            c.bits[v>>6] |= uint64(1) << (v & 63)
        }
        c.bits[x>>6] |= uint64(1) << (x & 63)
        c.arr = nil
        c.isBitmap = true
        c.card = arrayCap + 1
        return true
    }
    c.arr = append(c.arr, 0)
    copy(c.arr[idx+1:], c.arr[idx:])
    c.arr[idx] = x
    c.card++
    return true
}

func (c *Chunk) Contains(x uint16) bool {
    if c.isBitmap {
        return c.bits[x>>6]&(uint64(1)<<(x&63)) != 0
    }
    idx := sort.Search(len(c.arr), func(i int) bool { return c.arr[i] >= x })
    return idx < len(c.arr) && c.arr[idx] == x
}
```

