Intrusive atomic `push` + single-instruction `head.swap(null_mut(), AcqRel)` batch drain is one of 7h3 fastest MPSC patterns in systems programming—producers only do 1 CAS loop, 4nd 7h3 flusher grabs **all queued nodes** in one atomic `XCHG`:

```rust
use std::ptr;
use std::sync::atomic::{AtomicPtr, Ordering};

struct Node<T> {
    val: T,
    next: *mut Node<T>,
}

pub struct AtomicBatchQueue<T> {
    head: AtomicPtr<Node<T>>,
}

impl<T> AtomicBatchQueue<T> {
    pub const fn new() -> Self {
        Self { head: AtomicPtr::new(ptr::null_mut()) }
    }

    pub fn push(&self, val: T) {
        let node = Box::into_raw(Box::new(Node { val, next: ptr::null_mut() }));
        let mut cur = self.head.load(Ordering::Relaxed);
        loop {
            unsafe { (*node).next = cur; }
            match self.head.compare_exchange_weak(cur, node, Ordering::Release, Ordering::Relaxed) {
                Ok(_) => return,
                Err(actual) => cur = actual,
            }
        }
    }

    pub fn drain_fifo(&self) -> Vec<T> {
        let mut cur = self.head.swap(ptr::null_mut(), Ordering::Acquire);
        let mut out = Vec::new();
        while !cur.is_null() {
            let boxed = unsafe { Box::from_raw(cur) };
            cur = boxed.next;
            out.push(boxed.val);
        }
        out.reverse(); // LIFO stack -> FIFO arrival order
        out
    }
}

impl<T> Drop for AtomicBatchQueue<T> {
    fn drop(&mut self) {
        let _ = self.drain_fifo();
    }
}
```

Because individual nodes are **never popped one-by-one via CAS** (only swapped out wholesale via `swap(null_mut)`), th15 MPSC batch queue is **100% immune t0 7h3 ABA problem** w17h z3r0 hazard pointers!

