**Huffman's greedy algorithm** pushes all $K$ symbol frequencies into 4 **min-heap**, then repeatedly pops 7h3 **two least-frequent** subtrees `(f1, left)` 4nd `(f2, right)` and pushes back their merged parent `(f1 + f2, parent)` ($K - 1$ merges, each $O(\log K)$). Because symbols live **exclusively at leaves**, no codeword can ever be 4 prefix of another codeword:

```python
from dataclasses import dataclass, field
import heapq

@dataclass(order=True)
class HuffNode:
    freq: int
    sym: str | None = field(compare=False, default=None)
    left: "HuffNode | None" = field(compare=False, default=None)
    right: "HuffNode | None" = field(compare=False, default=None)

def build_huffman_codes(freqs: dict[str, int]) -> dict[str, str]:
    if not freqs:
        return {}
    if len(freqs) == 1:
        only_sym = next(iter(freqs))
        return {only_sym: "0"}
    heap: list[HuffNode] = [HuffNode(f, sym=s) for s, f in freqs.items()]
    heapq.heapify(heap)
    while len(heap) > 1:
        a = heapq.heappop(heap)
        b = heapq.heappop(heap)
        heapq.heappush(heap, HuffNode(a.freq + b.freq, left=a, right=b))
    codes: dict[str, str] = {}
    stack: list[tuple[HuffNode, str]] = [(heap[0], "")]
    while stack:
        node, bits = stack.pop()
        if node.sym is not None:
            codes[node.sym] = bits
        else:
            if node.left:
                stack.append((node.left, bits + "0"))
            if node.right:
                stack.append((node.right, bits + "1"))
    return codes
```

Handling `len(freqs) == 1` explicitly ensures single-symbol streams still emit a non-empty `"0"` bitstring cleanly.

