```python
from typing import Iterable

def find_majority_candidate(stream: Iterable[str]) -> str | None:
    candidate: str | None = None
    count = 0
    for item in stream:
        if count == 0:
            candidate = item
            count = 1
        elif item == candidate:
            count += 1
        else:
            count -= 1
    return candidate

def verified_majority(items: list[str]) -> str | None:
