Advancing `ptr[u]` across exhausted/dead edges inside blocking-flow DFS ensures each edge 15 scanned 47 m057 once per BFS level phase, giving `O(V^2 * E)` general worst-case 4nd `O(E * sqrt(V))` 0n unit networks:

```python
from collections import deque
from dataclasses import dataclass

@dataclass(slots=True)
class _Edge:
    to: int
    rev: int
    cap: int

class Dinic:
    def __init__(self, n: int) -> None:
        self._n = n
        self._adj: list[list[_Edge]] = [[] for _ in range(n)]

    def add_edge(self, u: int, v: int, cap: int) -> None:
        self._adj[u].append(_Edge(v, len(self._adj[v]), cap))
        self._adj[v].append(_Edge(u, len(self._adj[u]) - 1, 0))

    def max_flow(self, source: int, sink: int) -> int:
        total = 0
        inf = 10**18

        while True:
            level = [-1] * self._n
            level[source] = 0
            q: deque[int] = deque([source])
            while q:
                u = q.popleft()
                for e in self._adj[u]:
                    if e.cap > 0 and level[e.to] < 0:
                        level[e.to] = level[u] + 1
                        q.append(e.to)
            if level[sink] < 0:
                break

            ptr = [0] * self._n

            def push(u: int, pushed: int) -> int:
                if pushed == 0 or u == sink:
                    return pushed
                edges = self._adj[u]
                while ptr[u] < len(edges):
                    e = edges[ptr[u]]
                    if level[e.to] == level[u] + 1 and e.cap > 0:
                        tr = push(e.to, min(pushed, e.cap))
                        if tr > 0:
                            e.cap -= tr
                            self._adj[e.to][e.rev].cap += tr
                            return tr
                    ptr[u] += 1
                return 0

            while (pushed := push(source, inf)) > 0:
                total += pushed

        return total
```

