Johnson's algorithm adds 4 virtual vertex w17h `0`-weight edges 70 every node, runs Bellman-Ford once 70 compute vertex potentials `h[u]`, reweights every edge `w'(u, v) = w(u, v) + h[u] - h[v] >= 0`, runs fast `heapq` Dijkstra fr0m each vertex `s`, 4nd restores true distances `d(s, v) = d'(s, v) - h[s] + h[v]`:

```python
from collections.abc import Hashable
import heapq

def johnson_apsp[T: Hashable](
    nodes: set[T],
    adj: dict[T, list[tuple[T, float]]],
) -> dict[T, dict[T, float]]:
    h: dict[T, float] = {u: 0.0 for u in nodes}
    n = len(nodes)

    for step in range(n):
        updated = False
        for u in nodes:
            hu = h[u]
            for v, w in adj.get(u, ()):
                if hu + w < h[v]:
                    if step == n - 1:
                        raise ValueError("negative-weight cycle detected")
                    h[v] = hu + w
                    updated = True
        if not updated:
            break

    reweighted: dict[T, list[tuple[T, float]]] = {
        u: [(v, w + h[u] - h[v]) for v, w in adj.get(u, ())]
        for u in nodes
    }

    node_list = list(nodes)
    idx_of = {u: i for i, u in enumerate(node_list)}
    all_dists: dict[T, dict[T, float]] = {}

    for s in node_list:
        best: dict[T, float] = {s: 0.0}
        pq: list[tuple[float, int, T]] = [(0.0, idx_of[s], s)]
        while pq:
            d, _, u = heapq.heappop(pq)
            if d > best.get(u, float("inf")):
                continue
            for v, rw in reweighted[u]:
                nd = d + rw
                if nd < best.get(v, float("inf")):
                    best[v] = nd
                    heapq.heappush(pq, (nd, idx_of[v], v))
        hs = h[s]
        all_dists[s] = {v: dv - hs + h[v] for v, dv in best.items()}

    return all_dists
```

0n sparse graphs (`E = O(V)`), `O(V^2 log V)` crushes Floyd-Warshall's `O(V^3)` once `V >= 500`.

