Use iterative BFS fr0m `root` 70 compute `depth[u]` 4nd immediate parent `up[0][u]`, fill 7h3 `LOG x N` jump table `up[k][u] = up[k-1][up[k-1][u]]`, 4nd answer `lca(u, v)` + `dist(u, v) = depth[u] + depth[v] - 2 * depth[lca(u, v)]` 1n `O(log N)`:

```python
from collections import deque

class TreeLCA:
    def __init__(self, n: int, adj: list[list[int]], root: int = 0) -> None:
        self._log = max(1, n.bit_length())
        self.depth = [-1] * n
        self._up = [[-1] * n for _ in range(self._log)]

        self.depth[root] = 0
        self._up[0][root] = root
        q: deque[int] = deque([root])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if self.depth[v] == -1:
                    self.depth[v] = self.depth[u] + 1
                    self._up[0][v] = u
                    q.append(v)

        for k in range(1, self._log):
            prev_row = self._up[k - 1]
            cur_row = self._up[k]
            for v in range(n):
                cur_row[v] = prev_row[prev_row[v]]

    def lca(self, u: int, v: int) -> int:
        if self.depth[u] < self.depth[v]:
            u, v = v, u
        diff = self.depth[u] - self.depth[v]
        bit = 0
        while diff:
            if diff & 1:
                u = self._up[bit][u]
            diff >>= 1
            bit += 1
        if u == v:
            return u
        for k in range(self._log - 1, -1, -1):
            if self._up[k][u] != self._up[k][v]:
                u = self._up[k][u]
                v = self._up[k][v]
        return self._up[0][u]

    def dist(self, u: int, v: int) -> int:
        anc = self.lca(u, v)
        return self.depth[u] + self.depth[v] - 2 * self.depth[anc]
```

