import random

def quickselect(arr: list[float], k: int, seed: int | None = None) -> float:
    if not (0 <= k < len(arr)):
        raise IndexError("k out of bounds")
    rng = random.Random(seed)
    data = list(arr)
    lo, hi = 0, len(data) - 1
    while lo < hi:
        pivot = data[rng.randint(lo, hi)]
        # 3-way partition: [lo..lt-1] < pivot, [lt..gt] == pivot, [gt+1..hi] > pivot
        lt, i, gt = lo, lo, hi
        while i <= gt:
            if data[i] < pivot:
                data[lt], data[i] = data[i], data[lt]
                lt += 1
                i += 1
            elif data[i] > pivot:
                data[i], data[gt] = data[gt], data[i]
                gt -= 1
            else:
                i += 1
        if k < lt:
            hi = lt - 1
        elif k > gt:
            lo = gt + 1
        else:
            return pivot
    return data[lo]
```

