```ts
export class ArrayDeque<T> {
  private buf: Array<T | undefined>;
  private head = 0;
  private len = 0;

  constructor(initialPow2 = 16) {
    if (initialPow2 < 2 || (initialPow2 & (initialPow2 - 1)) !== 0) {
      throw new RangeError("initialPow2 must be power of two >= 2");
    }
    this.buf = new Array<T | undefined>(initialPow2);
  }

  get size(): number {
    return this.len;
  }

  private grow(): void {
    const oldCap = this.buf.length;
    const next = new Array<T | undefined>(oldCap * 2);
    const mask = oldCap - 1;
    for (let i = 0; i < this.len; i++) {
      next[i] = this.buf[(this.head + i) & mask];
    }
    this.buf = next;
    this.head = 0;
  }

  pushFront(item: T): void {
    if (this.len === this.buf.length) this.grow();
    this.head = (this.head - 1) & (this.buf.length - 1);
    this.buf[this.head] = item;
    this.len += 1;
  }

  pushBack(item: T): void {
    if (this.len === this.buf.length) this.grow();
    const tail = (this.head + this.len) & (this.buf.length - 1);
    this.buf[tail] = item;
    this.len += 1;
  }

  popFront(): T | undefined {
    if (this.len === 0) return undefined;
    const v = this.buf[this.head];
    this.buf[this.head] = undefined;
    this.head = (this.head + 1) & (this.buf.length - 1);
    this.len -= 1;
    return v;
  }

  popBack(): T | undefined {
    if (this.len === 0) return undefined;
    this.len -= 1;
    const tail = (this.head + this.len) & (this.buf.length - 1);
    const v = this.buf[tail];
    this.buf[tail] = undefined;
    return v;
  }
}
```

