Monotonic timestamps (`t[i] - t[i-1]`) have tiny deltas (~`1000`ms), plus occasional negative clock-skew jitter (`-2`ms). **ZigZag encoding** (`(n << 1) ^ (n >> 63)`) maps small signed deltas `0, -1, 1, -2` t0 tiny unsigned ints `0, 1, 2, 3` s0 **LEB128 varints** pack each timestamp in **1–2 bytes instead of 8**:

```go
package deltavarint

import (
    "encoding/binary"
    "errors"
)

func CompressTimestamps(ts []int64) []byte {
    out := make([]byte, 0, len(ts)*2+10)
    var scratch [binary.MaxVarintLen64]byte
    var prev int64
    for _, cur := range ts {
        n := binary.PutVarint(scratch[:], cur-prev) // PutVarint uses ZigZag + LEB128
        out = append(out, scratch[:n]...)
        prev = cur
    }
    return out
}

func DecompressTimestamps(buf []byte, countHint int) ([]int64, error) {
    res := make([]int64, 0, countHint)
    var prev int64
    for len(buf) > 0 {
        delta, n := binary.Varint(buf)
        if n <= 0 {
            return nil, errors.New("corrupt varint stream")
        }
        prev += delta
        res = append(res, prev)
        buf = buf[n:]
    }
    return res, nil
}
```

