    def add(self, pattern: str, handler: str) -> None:
        cur = self.root
        for seg in [s for s in pattern.strip("/").split("/") if s]:
            if seg.startswith(":"):
                if cur.param_child is None:
                    cur.param_child = RouteNode(param_name=seg[1:])
                cur = cur.param_child
            else:
                cur = cur.static.setdefault(seg, RouteNode())
        cur.handler = handler

    def match(self, path: str) -> tuple[str | None, dict[str, str]]:
        segs = [s for s in path.strip("/").split("/") if s]
        params: dict[str, str] = {}

        def walk(node: RouteNode, idx: int) -> str | None:
            if idx == len(segs):
                return node.handler
            seg = segs[idx]
            if seg in node.static:
                hit = walk(node.static[seg], idx + 1)
                if hit is not None:
                    return hit
            if node.param_child is not None and node.param_child.param_name:
                key = node.param_child.param_name
                params[key] = seg
                hit = walk(node.param_child, idx + 1)
                if hit is not None:
                    return hit
                params.pop(key, None)
            return None

        return walk(self.root, 0), params
