    base_rows: list[float],
    join_selectivity: dict[tuple[int, int], float],
) -> tuple[float, str]:
    n = len(table_names)
    full_mask = (1 << n) - 1
    dp_cost: dict[int, float] = {}
    dp_plan: dict[int, str] = {}
    dp_rows: dict[int, float] = {}

    for i in range(n):
        m = 1 << i
        dp_cost[m] = 0.0
        dp_plan[m] = table_names[i]
        dp_rows[m] = base_rows[i]

    for mask in range(1, full_mask + 1):
        if mask & (mask - 1) == 0:
