        best_cost = math.inf
        best_plan = ""
        best_rows = math.inf

        sub = (mask - 1) & mask
        while sub > 0:
            other = mask ^ sub
            if sub < other and sub in dp_cost and other in dp_cost:
                cross_sel = 1.0
                connected = False
                for i in range(n):
                    if not (sub & (1 << i)):
                        continue
                    for j in range(n):
                        if not (other & (1 << j)):
                            continue
                        pair = (min(i, j), max(i, j))
                        if pair in join_selectivity:
                            connected = True
                            cross_sel *= join_selectivity[pair]
