                        best_cost = step_cost
                        best_rows = out_rows
                        best_plan = f"({dp_plan[sub]} JOIN {dp_plan[other]})"
            sub = (sub - 1) & mask

        if best_cost < math.inf:
            dp_cost[mask] = best_cost
            dp_rows[mask] = best_rows
            dp_plan[mask] = best_plan

    return dp_cost[full_mask], dp_plan[full_mask]
