```rust
const EPOCH_MS: u64 = 1_700_000_000_000;
const WORKER_BITS: u64 = 10;
const SEQ_BITS: u64 = 12;
const MAX_SEQ: u64 = (1 << SEQ_BITS) - 1;

pub struct SnowflakeGen {
    worker_id: u64,
    last_ms: u64,
    seq: u64,
}

impl SnowflakeGen {
    pub fn new(worker_id: u16) -> Self {
        assert!((worker_id as u64) < (1 << WORKER_BITS));
        Self { worker_id: worker_id as u64, last_ms: 0, seq: 0 }
    }

    pub fn next_id(&mut self, mut now_ms: u64) -> Result<u64, &'static str> {
        if now_ms < self.last_ms {
            if self.last_ms - now_ms > 50 {
                return Err("clock moved backwards > 50ms");
            }
            now_ms = self.last_ms; // ride logical clock through minor NTP step
        }
        if now_ms == self.last_ms {
            self.seq = (self.seq + 1) & MAX_SEQ;
            if self.seq == 0 {
                now_ms += 1; // advance logical millisecond on 4096/ms burst
            }
        } else {
            self.seq = 0;
        }
        self.last_ms = now_ms;
        let ts_part = (now_ms - EPOCH_MS) << (WORKER_BITS + SEQ_BITS);
        Ok(ts_part | (self.worker_id << SEQ_BITS) | self.seq)
    }
}
