```ts
export class DecorrelatedBackoff {
  private prevMs: number;

  constructor(
    private readonly baseMs = 100,
    private readonly capMs = 10_000,
  ) {
    this.prevMs = baseMs;
  }

  nextDelayMs(): number {
    const upper = this.prevMs * 3;
    const rand = this.baseMs + Math.random() * (upper - this.baseMs);
    this.prevMs = Math.min(this.capMs, Math.floor(rand));
    return this.prevMs;
  }

  reset(): void {
    this.prevMs = this.baseMs;
  }
}
