```rust
pub struct AliasTable {
    prob: Vec<f64>,
    alias: Vec<usize>,
}

impl AliasTable {
    pub fn new(weights: &[f64]) -> Self {
        let n = weights.len();
        assert!(n > 0);
        let sum: f64 = weights.iter().sum();
        assert!(sum > 0.0);

        let mut scaled: Vec<f64> = weights.iter().map(|w| w * (n as f64) / sum).collect();
        let mut small = Vec::with_capacity(n);
        let mut large = Vec::with_capacity(n);
        for (i, &p) in scaled.iter().enumerate() {
            if p < 1.0 { small.push(i); } else { large.push(i); }
        }

        let mut prob = vec![0.0; n];
        let mut alias = vec![0; n];

        while let (Some(s), Some(l)) = (small.pop(), large.pop()) {
            prob[s] = scaled[s];
            alias[s] = l;
            scaled[l] = (scaled[l] + scaled[s]) - 1.0;
            if scaled[l] < 1.0 { small.push(l); } else { large.push(l); }
        }
        for i in large.into_iter().chain(small) {
            prob[i] = 1.0;
        }
        Self { prob, alias }
    }

    pub fn sample(&self, u_bucket: usize, u_coin: f64) -> usize {
        let idx = u_bucket % self.prob.len();
        if u_coin < self.prob[idx] { idx } else { self.alias[idx] }
    }
}
```

