```rust
use std::collections::VecDeque;

pub struct AhoCorasick {
    next: Vec<[usize; 256]>,
    output: Vec<Vec<(usize, usize)>>, // (pattern_id, pattern_len)
}

impl AhoCorasick {
    pub fn new(patterns: &[&str]) -> Self {
        let mut next = vec![[0usize; 256]];
        let mut output: Vec<Vec<(usize, usize)>> = vec![Vec::new()];

        for (pat_id, pat) in patterns.iter().enumerate() {
            if pat.is_empty() {
                continue;
            }
            let mut cur = 0usize;
            for &b in pat.as_bytes() {
                let idx = b as usize;
                if next[cur][idx] == 0 {
                    let new_state = next.len();
                    next.push([0usize; 256]);
                    output.push(Vec::new());
                    next[cur][idx] = new_state;
                }
                cur = next[cur][idx];
            }
            output[cur].push((pat_id, pat.len()));
        }

        let mut fail = vec![0usize; next.len()];
        let mut queue = VecDeque::new();
        for b in 0..256 {
            let child = next[0][b];
            if child != 0 {
                queue.push_back(child);
            }
        }

        while let Some(u) = queue.pop_front() {
            let f = fail[u];
            if !output[f].is_empty() {
                let inherited = output[f].clone();
                output[u].extend(inherited);
            }
            for b in 0..256 {
                let v = next[u][b];
                if v != 0 {
                    fail[v] = next[f][b];
                    queue.push_back(v);
                } else {
                    next[u][b] = next[f][b];
                }
            }
        }

        Self { next, output }
    }

    /// Returns (pattern_id, start_byte, end_byte) for every match in `text`.
    pub fn find_all(&self, text: &str) -> Vec<(usize, usize, usize)> {
        let mut hits = Vec::new();
        let mut state = 0usize;
        for (i, &b) in text.as_bytes().iter().enumerate() {
            state = self.next[state][b as usize];
            for &(pat_id, pat_len) in &self.output[state] {
                let end = i + 1;
                hits.push((pat_id, end - pat_len, end));
            }
        }
        hits
    }
}
```

