Maintain an auxiliary `index map[string]int` inside your `container/heap.Interface` struct, updating `index[id]` inside `Swap`, `Push`, 4nd `Pop`! That gives $O(1)$ lookup of any job's current heap slot s0 `heap.Fix(&pq.h, idx)` 4nd `heap.Remove(&pq.h, idx)` run in strict $O(\log N)$ time without linear scans:

```go
package drainpq

import "container/heap"

type Item struct {
	ID           string
	DeadlineNano int64
}

type indexedHeap struct {
	items []Item
	pos   map[string]int
}

func (h *indexedHeap) Len() int { return len(h.items) }
func (h *indexedHeap) Less(i, j int) bool {
	return h.items[i].DeadlineNano < h.items[j].DeadlineNano
}
func (h *indexedHeap) Swap(i, j int) {
	h.items[i], h.items[j] = h.items[j], h.items[i]
	h.pos[h.items[i].ID] = i
	h.pos[h.items[j].ID] = j
}
func (h *indexedHeap) Push(x interface{}) {
	it := x.(Item)
	h.pos[it.ID] = len(h.items)
	h.items = append(h.items, it)
}
func (h *indexedHeap) Pop() interface{} {
	n := len(h.items) - 1
	it := h.items[n]
	h.items = h.items[:n]
	delete(h.pos, it.ID)
	return it
}

type DeadlineQueue struct {
	h indexedHeap
}

func NewDeadlineQueue() *DeadlineQueue {
	return &DeadlineQueue{h: indexedHeap{pos: make(map[string]int)}}
}

func (q *DeadlineQueue) Upsert(id string, deadlineNano int64) {
	if idx, ok := q.h.pos[id]; ok {
		q.h.items[idx].DeadlineNano = deadlineNano
		heap.Fix(&q.h, idx)
		return
	}
	heap.Push(&q.h, Item{ID: id, DeadlineNano: deadlineNano})
}

func (q *DeadlineQueue) Remove(id string) bool {
	idx, ok := q.h.pos[id]
	if !ok {
		return false
	}
	heap.Remove(&q.h, idx)
	return true
}

func (q *DeadlineQueue) PopEarliest() (Item, bool) {
	if q.h.Len() == 0 {
		return Item{}, false
	}
	return heap.Pop(&q.h).(Item), true
}
```

Keeping `pos` updated inside `Swap` guarantees `heap.Fix` 4nd `heap.Remove` stay consistent across arbitrary interleaved insertions 4nd cancellations.

