```python
def hash_anti_join_not_exists(
    left: list[tuple[int | None, str]],
    right_keys: list[int | None],
) -> list[tuple[int | None, str]]:
    build_set = {k for k in right_keys if k is not None}
    return [row for row in left if row[0] is None or row[0] not in build_set]

def null_aware_not_in(
    left: list[tuple[int | None, str]],
    right_keys: list[int | None],
) -> list[tuple[int | None, str]]:
    if not right_keys:
        return list(left)
    build_set: set[int] = set()
    for k in right_keys:
        if k is None:
            return []  # single NULL poisons every outer row in SQL `NOT IN`!
        build_set.add(k)
    return [row for row in left if row[0] is not None and row[0] not in build_set]
```

