import random
import time
from collections.abc import Callable
from typing import TypeVar
from sqlalchemy.exc import DBAPIError
from sqlalchemy.orm import Session, sessionmaker

RETRYABLE_SQLSTATES = {"40001", "40P01"}
T = TypeVar("T")

def run_serializable_txn(
    session_factory: sessionmaker[Session],
    fn: Callable[[Session], T],
    max_attempts: int = 5,
    base_delay_s: float = 0.01,
) -> T:
    for attempt in range(1, max_attempts + 1):
        with session_factory() as session:
            try:
                with session.begin():
                    return fn(session)
            except DBAPIError as exc:
                sqlstate = getattr(exc.orig, "sqlstate", None) or getattr(exc.orig, "pgcode", None)
                if sqlstate not in RETRYABLE_SQLSTATES or attempt == max_attempts:
                    raise
        # `with session.begin()` already issued ROLLBACK; sleep with jitter outside DB session!
        time.sleep(random.uniform(base_delay_s, base_delay_s * (2 ** attempt)))
    raise RuntimeError("unreachable")
