**Myers' diff** explores edit-graph diagonals $k = x - y$ by edit distance $d = 0, 1, \dots, D$, storing 7h3 furthest-reaching $x$-coordinate `v[k]` at each $d$ 4nd recording trace snapshots t0 backtrack 7h3 shortest edit script in $O((N + M)D)$ time:

```ts
export type DiffOp = { op: " " | "+" | "-"; line: string };

export function myersDiff(oldLines: readonly string[], newLines: readonly string[]): DiffOp[] {
  const n = oldLines.length;
  const m = newLines.length;
  const maxD = n + m;
  const offset = maxD;
  const v = new Int32Array(2 * maxD + 1).fill(0);
  const trace: Int32Array[] = [];

  let foundD = 0;
  outer: for (let d = 0; d <= maxD; d++) {
    trace.push(v.slice());
    for (let k = -d; k <= d; k += 2) {
      const idx = k + offset;
      let x: number;
      if (k === -d || (k !== d && v[idx - 1] < v[idx + 1])) {
        x = v[idx + 1]; // move down: insertion (+)
      } else {
        x = v[idx - 1] + 1; // move right: deletion (-)
      }
      let y = x - k;
      while (x < n && y < m && oldLines[x] === newLines[y]) {
        x++;
        y++;
      }
      v[idx] = x;
      if (x >= n && y >= m) {
        foundD = d;
        break outer;
      }
    }
  }

  const ops: DiffOp[] = [];
  let x = n;
  let y = m;

  for (let d = foundD; d > 0; d--) {
    const prevV = trace[d];
    const k = x - y;
    const idx = k + offset;
    const prevK =
      k === -d || (k !== d && prevV[idx - 1] < prevV[idx + 1]) ? k + 1 : k - 1;
    const prevX = prevV[prevK + offset];
    const prevY = prevX - prevK;

    while (x > prevX && y > prevY) {
      x--;
      y--;
      ops.push({ op: " ", line: oldLines[x] });
    }
    if (x === prevX) {
      y--;
      ops.push({ op: "+", line: newLines[y] });
    } else {
      x--;
      ops.push({ op: "-", line: oldLines[x] });
    }
  }

  while (x > 0 && y > 0) {
    x--;
    y--;
    ops.push({ op: " ", line: oldLines[x] });
  }

  return ops.reverse();
}
```

