**Hopcroft-Karp** alternates a multi-source BFS (which builds shortest augmenting-path layers in $O(E)$) w17h vertex-disjoint DFS augmentations along those layers—completing in at most $O(\sqrt{V})$ phases ($O(E \sqrt{V})$ total time vs $O(V \cdot E)$ f0r naive Kuhn DFS!):

```python
from collections import deque
from typing import Sequence


def match_jobs_to_runners(
    n_jobs: int,
    n_runners: int,
    compat: Sequence[Sequence[int]],
) -> list[tuple[int, int]]:
    pair_u = [-1] * n_jobs
    pair_v = [-1] * n_runners
    dist = [0] * n_jobs
    INF = 10**9

    def bfs() -> bool:
        q: deque[int] = deque()
        found_augmenting = False
        for u in range(n_jobs):
            if pair_u[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = INF

        while q:
            u = q.popleft()
            for v in compat[u]:
                nxt_u = pair_v[v]
                if nxt_u == -1:
                    found_augmenting = True
                elif dist[nxt_u] == INF:
                    dist[nxt_u] = dist[u] + 1
                    q.append(nxt_u)
        return found_augmenting

    def dfs(u: int) -> bool:
        for v in compat[u]:
            nxt_u = pair_v[v]
            if nxt_u == -1 or (dist[nxt_u] == dist[u] + 1 and dfs(nxt_u)):
                pair_u[u] = v
                pair_v[v] = u
                return True
        # Prune dead-end node for the remainder of this phase!
        dist[u] = INF
        return False

    while bfs():
        for u in range(n_jobs):
            if pair_u[u] == -1:
                dfs(u)

    return [(u, pair_u[u]) for u in range(n_jobs) if pair_u[u] != -1]
```

