```ts
export class StreamingSecretScrubber {
  private readonly secrets: string[];
  private readonly holdbackLen: number;
  private tail = "";

  constructor(rawSecrets: readonly string[]) {
    // Sort longest-first so a prefix secret never partially masks a longer secret!
    this.secrets = [...new Set(rawSecrets.filter((s) => s.length >= 4))].sort(
      (a, b) => b.length - a.length,
    );
    this.holdbackLen =
      this.secrets.length > 0 ? this.secrets[0].length - 1 : 0;
  }

  private redactComplete(buf: string): string {
    let out = buf;
    for (const secret of this.secrets) {
      if (out.includes(secret)) {
        out = out.split(secret).join("[REDACTED]");
      }
    }
    return out;
  }

  push(chunk: string): string {
    if (this.holdbackLen === 0 || chunk.length === 0) {
      return chunk;
    }
    const combined = this.redactComplete(this.tail + chunk);
    if (combined.length <= this.holdbackLen) {
      this.tail = combined;
      return "";
    }
    const safeCutoff = combined.length - this.holdbackLen;
    const emit = combined.slice(0, safeCutoff);
    this.tail = combined.slice(safeCutoff);
    return emit;
  }

  flush(): string {
    const finalOut = this.redactComplete(this.tail);
    this.tail = "";
    return finalOut;
  }
}
```

