#include <utility>

class Arena {
    std::byte* buf_;
    size_t cap_;
    size_t offset_{0};

public:
    explicit Arena(size_t cap)
        : buf_(static_cast<std::byte*>(::operator new(cap, std::align_val_t{64}))),
          cap_(cap) {}

    ~Arena() { ::operator delete(buf_, std::align_val_t{64}); }
    Arena(const Arena&) = delete;
    Arena& operator=(const Arena&) = delete;

    void* allocate(size_t bytes, size_t align = alignof(std::max_align_t)) noexcept {
        uintptr_t base = reinterpret_cast<uintptr_t>(buf_) + offset_;
        uintptr_t aligned = (base + (align - 1)) & ~(align - 1);
        size_t next_offset = (aligned - reinterpret_cast<uintptr_t>(buf_)) + bytes;
        if (next_offset > cap_) return nullptr;
        offset_ = next_offset;
        return reinterpret_cast<void*>(aligned);
    }

    template <typename T, typename... Args>
    T* make(Args&&... args) {
        void* mem = allocate(sizeof(T), alignof(T));
        if (!mem) throw std::bad_alloc{};
        return std::construct_at(static_cast<T*>(mem), std::forward<Args>(args)...);
    }

    void reset() noexcept { offset_ = 0; }
};
```

