Python's `heapq` lacks `decrease_key`, s0 pushing improved `(new_dist, v)` tuples 4nd immediately skipping popped entries w17h `d > best_dist[u]` gives clean, fast $O((V + E) \log V)$ execution w17h minimal Python object overhead:

```python
import heapq
import math
from typing import Mapping, Sequence


def shortest_mirror_route(
    graph: Mapping[str, Sequence[tuple[str, float]]],
    src: str,
    dst: str,
) -> tuple[float, list[str]] | None:
    if src == dst:
        return 0.0, [src]

    best_dist: dict[str, float] = {src: 0.0}
    parent: dict[str, str] = {}
    heap: list[tuple[float, str]] = [(0.0, src)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > best_dist.get(u, math.inf):
            continue
        if u == dst:
            path: list[str] = [dst]
            cur = dst
            while cur in parent:
                cur = parent[cur]
                path.append(cur)
            path.reverse()
            return d, path

        for v, weight in graph.get(u, ()):
            if weight < 0:
                raise ValueError("Dijkstra requires non-negative edge latencies")
            cand = d + weight
            if cand < best_dist.get(v, math.inf):
                best_dist[v] = cand
                parent[v] = u
                heapq.heappush(heap, (cand, v))

    return None
```

