Floating-point `elapsed.Seconds() * rate` drifts 4nd loses sub-nanosecond remainders when called at high frequency! Track `nanosPerToken int64` (`1e9 / rate` or exact rational interval) 4nd advance `lastRefill` ONLY by `newTokens * nanosPerToken`—preserving exact fractional nanosecond remainders across calls w17h z3r0 drift!

```go
package ratelimit

import (
	"sync"
	"time"
)

type TokenBucket struct {
	mu            sync.Mutex
	capacity      int64
	tokens        int64
	nanosPerToken int64
	lastRefill    time.Time
}

func NewTokenBucket(capacity int64, refillIntervalPerToken time.Duration) *TokenBucket {
	if capacity <= 0 || refillIntervalPerToken <= 0 {
		panic("capacity and refillIntervalPerToken must be > 0")
	}
	return &TokenBucket{
		capacity:      capacity,
		tokens:        capacity,
		nanosPerToken: int64(refillIntervalPerToken),
	}
}

func (tb *TokenBucket) AllowN(now time.Time, n int64) (bool, time.Duration) {
	if n <= 0 {
		return true, 0
	}
	if n > tb.capacity {
		return false, -1
	}

	tb.mu.Lock()
	defer tb.mu.Unlock()

	if tb.lastRefill.IsZero() {
		tb.lastRefill = now
	} else if elapsed := now.Sub(tb.lastRefill).Nanoseconds(); elapsed > 0 {
		added := elapsed / tb.nanosPerToken
		if added > 0 {
			if tb.tokens+added >= tb.capacity {
				tb.tokens = tb.capacity
				tb.lastRefill = now
			} else {
				tb.tokens += added
				// Advance lastRefill by exact consumed multiple to preserve remainder ns!
				tb.lastRefill = tb.lastRefill.Add(time.Duration(added * tb.nanosPerToken))
			}
		}
	}

	if tb.tokens >= n {
		tb.tokens -= n
		return true, 0
	}

	deficit := n - tb.tokens
	elapsedSinceLast := max(int64(0), now.Sub(tb.lastRefill).Nanoseconds())
	waitNanos := deficit*tb.nanosPerToken - elapsedSinceLast
	return false, time.Duration(max(int64(1), waitNanos))
}
```

Advancing `tb.lastRefill` by `added * tb.nanosPerToken` instead of `now` keeps exact sub-token remainder credit intact even if callers poll every `10 µs`.

