```python
import errno
import socket
from typing import Iterator

class EdgeTriggeredLineReader:
    def __init__(self, max_frame_bytes: int = 1_048_576) -> None:
        self._buf = bytearray()
        self._max_frame = max_frame_bytes
        self.eof = False

    def drain_and_iter_lines(self, sock: socket.socket) -> Iterator[bytes]:
        # Step 1: Must drain kernel recv buffer completely until EAGAIN/EWOULDBLOCK
        while True:
            try:
                chunk = sock.recv(65536)
            except BlockingIOError:
                break
            except InterruptedError:
                continue
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    break
                raise

            if not chunk:
                self.eof = True
                break

            self._buf.extend(chunk)
            if len(self._buf) > self._max_frame * 2 and b"\n" not in chunk:
                if self._buf.find(b"\n") == -1 and len(self._buf) > self._max_frame:
                    raise ValueError("frame exceeds max_frame_bytes")

        # Step 2: Scan frames linearly with cursor offset, compact once at end
        start = 0
        while True:
            nl = self._buf.find(b"\n", start)
            if nl == -1:
                break
            if nl - start > self._max_frame:
                del self._buf[:]
                raise ValueError("frame exceeds max_frame_bytes")
            yield bytes(self._buf[start:nl])
            start = nl + 1

        if start:
            del self._buf[:start]
        if len(self._buf) > self._max_frame:
            del self._buf[:]
            raise ValueError("unterminated frame exceeds max_frame_bytes")
```

