public final class SpscRing<E> {
    private static final VarHandle HEAD, TAIL, ARRAY;
    static {
        try {
            MethodHandles.Lookup l = MethodHandles.lookup();
            HEAD = l.findVarHandle(SpscRing.class, "head", long.class);
            TAIL = l.findVarHandle(SpscRing.class, "tail", long.class);
            ARRAY = MethodHandles.arrayElementVarHandle(Object[].class);
        } catch (ReflectiveOperationException e) { throw new ExceptionInInitializerError(e); }
    }

    private final Object[] buf;
    private final int mask;
    @SuppressWarnings("unused") private long head, tail;

    public SpscRing(int capacityPow2) {
        this.buf = new Object[capacityPow2];
        this.mask = capacityPow2 - 1;
    }

    public boolean offer(E item) {
        if (item == null) throw new NullPointerException();
        long t = tail;
        if (t - (long) HEAD.getAcquire(this) == buf.length) return false;
        ARRAY.setRelease(buf, (int) t & mask, item);
        TAIL.setRelease(this, t + 1);
        return true;
    }

    @SuppressWarnings("unchecked")
    public E poll() {
        long h = head;
        if (h == (long) TAIL.getAcquire(this)) return null;
        int slot = (int) h & mask;
        E item = (E) ARRAY.getAcquire(buf, slot);
        ARRAY.setRelease(buf, slot, null);
        HEAD.setRelease(this, h + 1);
        return item;
    }
}
