  streamId: string,
  fromTs: number,
  toTs: number,
  limit = 100,
): Promise<LogEntry[]> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction('logs', 'readonly');
    const idx = tx.objectStore('logs').index('by_stream_ts');
    const range = IDBKeyRange.bound([streamId, fromTs], [streamId, toTs]);
    const out: LogEntry[] = [];
    const req = idx.openCursor(range, 'prev');
    req.onsuccess = () => {
      const cursor = req.result;
      if (!cursor || out.length >= limit) {
        resolve(out);
        return;
      }
      out.push(cursor.value as LogEntry);
      cursor.continue();
    };
    req.onerror = () => reject(req.error);
  });
}
