Largest-Triangle-Three-Buckets (LTTB) keeps 7h3 first 4nd last points, splits 7h3 interior into `threshold - 2` buckets, and picks the point in each bucket forming the largest triangle area between the previously selected point and the next bucket's centroid:

```ts
export function lttb(xs: Float64Array, ys: Float64Array, threshold: number): [Float64Array, Float64Array] {
  const n = xs.length;
  if (threshold >= n || threshold < 3) return [xs.slice(), ys.slice()];
  const outX = new Float64Array(threshold);
  const outY = new Float64Array(threshold);
  outX[0] = xs[0];
  outY[0] = ys[0];
  const every = (n - 2) / (threshold - 2);
  let a = 0;

  for (let i = 0; i < threshold - 2; i++) {
    const avgStart = Math.floor((i + 1) * every) + 1;
    const avgEnd = Math.min(Math.floor((i + 2) * every) + 1, n);
    let avgX = 0, avgY = 0;
    const avgLen = avgEnd - avgStart;
    for (let j = avgStart; j < avgEnd; j++) {
      avgX += xs[j];
      avgY += ys[j];
    }
    avgX /= avgLen;
    avgY /= avgLen;

    const rangeStart = Math.floor(i * every) + 1;
    const rangeEnd = Math.floor((i + 1) * every) + 1;
    const ax = xs[a], ay = ys[a];
    let maxArea = -1, nextA = rangeStart;
    for (let j = rangeStart; j < rangeEnd; j++) {
      const area = Math.abs((ax - avgX) * (ys[j] - ay) - (ax - xs[j]) * (avgY - ay));
      if (area > maxArea) {
        maxArea = area;
        nextA = j;
      }
    }
    outX[i + 1] = xs[nextA];
    outY[i + 1] = ys[nextA];
    a = nextA;
  }
  outX[threshold - 1] = xs[n - 1];
  outY[threshold - 1] = ys[n - 1];
  return [outX, outY];
}
