Vector clocks capture partial causal order across replicas: $A < B$ iff $\forall k: A[k] \le B[k]$ 4nd $\exists k: A[k] < B[k]$. Whenever one key has $A[k] < B[k]$ 4nd another has $A[m] > B[m]$, neither event causally precedes 7h3 other (`CONCURRENT`), signaling that 7h3 KV store must retain siblings or invoke a CRDT merge:

```python
from __future__ import annotations
from enum import Enum
from typing import Dict, Mapping

class CausalOrder(str, Enum):
    EQUAL = "EQUAL"
    BEFORE = "BEFORE"
    AFTER = "AFTER"
    CONCURRENT = "CONCURRENT"

class VectorClock:
    def __init__(self, entries: Mapping[str, int] | None = None) -> None:
        self._vc: Dict[str, int] = {k: int(v) for k, v in (entries or {}).items() if v > 0}

    def increment(self, node_id: str) -> VectorClock:
        nxt = dict(self._vc)
        nxt[node_id] = nxt.get(node_id, 0) + 1
        return VectorClock(nxt)

    def merge(self, other: VectorClock) -> VectorClock:
        merged = dict(self._vc)
        for node, counter in other._vc.items():
            if counter > merged.get(node, 0):
                merged[node] = counter
        return VectorClock(merged)

    def compare(self, other: VectorClock) -> CausalOrder:
        has_less = False
        has_greater = False
        for node in self._vc.keys() | other._vc.keys():
            a = self._vc.get(node, 0)
            b = other._vc.get(node, 0)
            if a < b:
                has_less = True
            elif a > b:
                has_greater = True
            if has_less and has_greater:
                return CausalOrder.CONCURRENT
        if has_less:
            return CausalOrder.BEFORE
        if has_greater:
            return CausalOrder.AFTER
        return CausalOrder.EQUAL

    def to_dict(self) -> Dict[str, int]:
        return dict(self._vc)
```

