```java
import java.util.Iterator;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicBoolean;

public final class HashedWheelTimer {
    public static final class Handle {
        final Runnable task;
        long rounds;
        final AtomicBoolean cancelled = new AtomicBoolean(false);
        Handle(Runnable task, long rounds) { this.task = task; this.rounds = rounds; }
        public void cancel() { cancelled.set(true); }
    }

    private final ConcurrentLinkedQueue<Handle>[] wheel;
    private final int mask;
    private long currentTick = 0;

    @SuppressWarnings("unchecked")
    public HashedWheelTimer(int ticksPerWheelPow2) {
        this.mask = ticksPerWheelPow2 - 1;
        this.wheel = new ConcurrentLinkedQueue[ticksPerWheelPow2];
        for (int i = 0; i < ticksPerWheelPow2; i++) wheel[i] = new ConcurrentLinkedQueue<>();
    }

    public Handle schedule(long delayTicks, Runnable task) {
        long target = currentTick + Math.max(1, delayTicks);
        long rounds = (delayTicks - 1) / wheel.length;
        Handle h = new Handle(task, rounds);
        wheel[(int) (target & mask)].add(h);
        return h;
    }

    public void advanceTick() {
        currentTick++;
        ConcurrentLinkedQueue<Handle> bucket = wheel[(int) (currentTick & mask)];
        for (Iterator<Handle> it = bucket.iterator(); it.hasNext(); ) {
            Handle h = it.next();
            if (h.cancelled.get()) { it.remove(); continue; }
            if (h.rounds <= 0) { it.remove(); h.task.run(); } else { h.rounds--; }
        }
    }
}
```

