import java.io.IOException;
import java.lang.foreign.Arena;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.ValueLayout;
import java.nio.channels.FileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public final class MmapIndexSearch implements AutoCloseable {
    private static final long REC_BYTES = 16L;
    private final Arena arena = Arena.ofShared();
    private final MemorySegment seg;
    private final long count;

    public MmapIndexSearch(Path idxPath) throws IOException {
        try (FileChannel ch = FileChannel.open(idxPath, StandardOpenOption.READ)) {
            this.seg = ch.map(FileChannel.MapMode.READ_ONLY, 0L, ch.size(), arena);
            this.count = seg.byteSize() / REC_BYTES;
        }
    }

    public long findOffset(long targetTs) {
        long lo = 0, hi = count - 1;
        while (lo <= hi) {
            long mid = (lo + hi) >>> 1;
            long base = mid * REC_BYTES;
            long ts = seg.get(ValueLayout.JAVA_LONG_UNALIGNED, base);
            if (ts < targetTs) lo = mid + 1;
            else if (ts > targetTs) hi = mid - 1;
            else return seg.get(ValueLayout.JAVA_LONG_UNALIGNED, base + 8L);
        }
        return -1L;
    }

    @Override public void close() { arena.close(); }
}
```

