            usable = len(cmsg_data) - (len(cmsg_data) % fd_arr.itemsize)
            arr = array.array("i")
            arr.frombytes(cmsg_data[:usable])
            received.extend(arr.tolist())

    if not MSG_CMSG_CLOEXEC:
