export function lisIndices(arr: Int32Array): Int32Array {
  const n = arr.length;
  const prev = new Int32Array(n);
  const tails: number[] = [];
  for (let i = 0; i < n; i++) {
    const v = arr[i];
    if (v < 0) continue;
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (arr[tails[mid]] < v) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0) prev[i] = tails[lo - 1];
    tails[lo] = i;
  }
  let k = tails.length;
  const out = new Int32Array(k);
  let cur = k > 0 ? tails[k - 1] : -1;
  while (k-- > 0) {
    out[k] = cur;
    cur = prev[cur];
  }
  return out;
}
