Prometheus cumulative h1570gr4m5 assume uniform d3n517y inside each `(prev_le, curr_le]` buck37—4nd if the target rank lands inside the final `+Inf` bucket (which has n0 finite width), Prometheus returns the lower bound of `+Inf` (the highest finite `le` boundary):

```python
import math

def prom_histogram_quantile(
    phi: float, buckets: list[tuple[float, float]]
) -> float:
    if math.isnan(phi):
        return float("nan")
    if phi < 0:
        return float("-inf")
    if phi > 1:
        return float("inf")
    ordered = sorted(buckets, key=lambda b: b[0])
    if len(ordered) < 2 or ordered[-1][0] != float("inf"):
        return float("nan")
    total = ordered[-1][1]
    if total <= 0:
        return float("nan")
    rank = phi * total
    for idx, (le, count) in enumerate(ordered):
        if count >= rank:
            if math.isinf(le):
                return ordered[idx - 1][0]
            prev_le = 0.0 if idx == 0 else ordered[idx - 1][0]
            prev_cnt = 0.0 if idx == 0 else ordered[idx - 1][1]
            if prev_le < 0 and idx == 0:
                return le
            bucket_cnt = count - prev_cnt
            if bucket_cnt <= 0:
                return prev_le
            return prev_le + (le - prev_le) * ((rank - prev_cnt) / bucket_cnt)
    return ordered[-2][0]
```

