void transpose_tiled(const float* __restrict src, float* __restrict dst, size_t n) noexcept {
    constexpr size_t B = 32; // Two 32x32 float tiles = 8 KiB << 32 KiB L1d
    for (size_t ii = 0; ii < n; ii += B) {
        for (size_t jj = 0; jj < n; jj += B) {
