```python
from dataclasses import dataclass

NEG_INF = -(10**18)


@dataclass(slots=True)
class Node:
    total: int = 0
    pref: int = NEG_INF
    suff: int = NEG_INF
    best: int = NEG_INF

    @staticmethod
    def leaf(val: int) -> "Node":
        return Node(val, val, val, val)


def merge(a: Node, b: Node) -> Node:
    if a.best == NEG_INF:
        return b
    if b.best == NEG_INF:
        return a
    return Node(
        total=a.total + b.total,
        pref=max(a.pref, a.total + b.pref),
        suff=max(b.suff, b.total + a.suff),
        best=max(a.best, b.best, a.suff + b.pref),
    )


class MaxSubarraySegTree:
    def __init__(self, values: list[int]) -> None:
        self.n = len(values)
        self.tree = [Node() for _ in range(2 * self.n)]
        for i, v in enumerate(values):
            self.tree[self.n + i] = Node.leaf(v)
        for i in range(self.n - 1, 0, -1):
            self.tree[i] = merge(self.tree[2 * i], self.tree[2 * i + 1])

    def update(self, idx: int, val: int) -> None:
        pos = self.n + idx
        self.tree[pos] = Node.leaf(val)
        pos >>= 1
        while pos >= 1:
            self.tree[pos] = merge(self.tree[2 * pos], self.tree[2 * pos + 1])
            pos >>= 1

    def query(self, l: int, r: int) -> int:
        res_left = Node()
        res_right = Node()
        l += self.n
        r += self.n
        while l < r:
            if l & 1:
                res_left = merge(res_left, self.tree[l])
                l += 1
            if r & 1:
                r -= 1
                res_right = merge(self.tree[r], res_right)
            l >>= 1
            r >>= 1
        return merge(res_left, res_right).best
```

