```go
package radix

type Node[V any] struct {
	prefix   string
	hasVal   bool
	val      V
	children []*Node[V] // sorted or keyed by children[i].prefix[0]
}

type Tree[V any] struct {
	root *Node[V]
}

func New[V any]() *Tree[V] {
	return &Tree[V]{root: &Node[V]{}}
}

func lcpLen(a, b string) int {
	n := min(len(a), len(b))
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			return i
		}
	}
	return n
}

func (n *Node[V]) findChild(firstByte byte) (int, *Node[V]) {
	for i, ch := range n.children {
		if ch.prefix[0] == firstByte {
			return i, ch
		}
	}
	return -1, nil
}

func (t *Tree[V]) Insert(key string, val V) {
	cur := t.root
	rem := key
	for len(rem) > 0 {
		idx, child := cur.findChild(rem[0])
		if child == nil {
			cur.children = append(cur.children, &Node[V]{
				prefix: rem,
				hasVal: true,
				val:    val,
			})
			return
		}
		common := lcpLen(rem, child.prefix)
		if common < len(child.prefix) {
			// Split existing child edge at `common`
			split := &Node[V]{
				prefix:   child.prefix[:common],
				children: []*Node[V]{child},
			}
			child.prefix = child.prefix[common:]
			cur.children[idx] = split
			child = split
		}
		rem = rem[common:]
		cur = child
	}
	cur.hasVal = true
	cur.val = val
}

func (t *Tree[V]) LongestPrefix(query string) (string, V, bool) {
	var bestKey string
	var bestVal V
	found := false
	if t.root.hasVal {
		bestVal, found = t.root.val, true
	}

	cur := t.root
	consumed := 0
	for consumed < len(query) {
		_, child := cur.findChild(query[consumed])
		if child == nil {
			break
		}
		rem := query[consumed:]
		if len(rem) < len(child.prefix) || rem[:len(child.prefix)] != child.prefix {
			break
		}
		consumed += len(child.prefix)
		cur = child
		if cur.hasVal {
			bestKey = query[:consumed]
			bestVal = cur.val
			found = true
		}
	}
	return bestKey, bestVal, found
}
```

