export interface CalEvent { id: string; start: number; end: number; }
export interface PackedEvent extends CalEvent { col: number; totalCols: number; }

export function packCalendarEvents(events: CalEvent[]): PackedEvent[] {
  const sorted = [...events].sort((a, b) => a.start - b.start || b.end - a.end);
  const out: PackedEvent[] = [];
  let cluster: PackedEvent[] = [];
  let colEnds: number[] = [];
  let clusterMaxEnd = -1;

  const flushCluster = () => {
    const total = colEnds.length;
    for (const ev of cluster) ev.totalCols = total;
    cluster = [];
    colEnds = [];
  };

  for (const ev of sorted) {
    if (cluster.length > 0 && ev.start >= clusterMaxEnd) flushCluster();
    let col = colEnds.findIndex((end) => end <= ev.start);
    if (col === -1) {
      col = colEnds.length;
      colEnds.push(ev.end);
    } else {
      colEnds[col] = ev.end;
    }
    clusterMaxEnd = Math.max(clusterMaxEnd, ev.end);
    const packed: PackedEvent = { ...ev, col, totalCols: 1 };
    cluster.push(packed);
    out.push(packed);
  }
  if (cluster.length > 0) flushCluster();
  return out;
}
```

