```kotlin
fun computeExecutionWaves(
    tasks: Set<String>,
    deps: Map<String, Set<String>> // task -> prerequisites
): List<List<String>> {
    val inDegree = HashMap<String, Int>(tasks.size)
    val dependents = HashMap<String, MutableList<String>>(tasks.size)
    for (t in tasks) inDegree[t] = 0

    for ((task, prereqs) in deps) {
        for (pre in prereqs) {
            require(pre in tasks && task in tasks) { "Unknown task edge $pre -> $task" }
            dependents.getOrPut(pre) { mutableListOf() }.add(task)
            inDegree[task] = inDegree.getValue(task) + 1
        }
    }

    var frontier = tasks.filter { inDegree[it] == 0 }.sorted()
    val waves = mutableListOf<List<String>>()
    var scheduled = 0

    while (frontier.isNotEmpty()) {
        waves.add(frontier)
        scheduled += frontier.size
        val next = mutableListOf<String>()
        for (done in frontier) {
            for (dep in dependents[done].orEmpty()) {
                val rem = inDegree.getValue(dep) - 1
                inDegree[dep] = rem
                if (rem == 0) next.add(dep)
            }
        }
        next.sort()
        frontier = next
    }

    check(scheduled == tasks.size) { "Cycle detected in task graph" }
    return waves
}
```

