```ts
export function topKScored<T>(items: readonly T[], scoreFn: (item: T) => number, k: number): T[] {
  const heap: { item: T; score: number }[] = [];
  const siftDown = (idx: number) => {
    const n = heap.length;
    while (true) {
      let smallest = idx;
      const l = idx * 2 + 1, r = l + 1;
      if (l < n && heap[l].score < heap[smallest].score) smallest = l;
      if (r < n && heap[r].score < heap[smallest].score) smallest = r;
      if (smallest === idx) break;
      [heap[idx], heap[smallest]] = [heap[smallest], heap[idx]];
      idx = smallest;
    }
  };
  for (const item of items) {
    const score = scoreFn(item);
    if (score <= 0) continue;
    if (heap.length < k) {
      heap.push({ item, score });
      let cur = heap.length - 1;
      while (cur > 0) {
        const p = (cur - 1) >> 1;
        if (heap[p].score <= heap[cur].score) break;
        [heap[p], heap[cur]] = [heap[cur], heap[p]];
        cur = p;
      }
    } else if (score > heap[0].score) {
      heap[0] = { item, score };
      siftDown(0);
    }
  }
  return heap.sort((a, b) => b.score - a.score).map((e) => e.item);
}
```

