use std::os::fd::AsRawFd;

pub fn recv_seqpacket(fd: &impl AsRawFd, buf: &mut [u8]) -> std::io::Result<usize> {
    let mut iov = libc::iovec {
        iov_base: buf.as_mut_ptr().cast(),
        iov_len: buf.len(),
