import os

IOV_MAX_BATCH = 64  # well within POSIX IOV_MAX (1024 on Linux/macOS)

class WritevQueue:
    def __init__(self) -> None:
        self._q: deque[memoryview] = deque()
        self.queued_bytes: int = 0

    def append(self, data: bytes | bytearray | memoryview) -> None:
        mv = memoryview(data).cast("B")
        if len(mv) == 0:
            return
        self._q.append(mv)
        self.queued_bytes += len(mv)

    def flush_nonblocking(self, fd: int) -> bool:
        """Drain via os.writev until empty (returns True) or EAGAIN (returns False)."""
        while self._q:
            batch = []
            for mv in self._q:
                batch.append(mv)
                if len(batch) >= IOV_MAX_BATCH:
                    break

            try:
                written = os.writev(fd, batch)
            except BlockingIOError:
                return False
            except InterruptedError:
                continue
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    return False
                raise

            if written == 0:
                return False

            self.queued_bytes -= written
            rem = written
            while rem > 0:
                head = self._q[0]
                if rem >= len(head):
                    rem -= len(head)
                    self._q.popleft()
                else:
                    # Zero-copy sub-slice of memoryview!
                    self._q[0] = head[rem:]
                    rem = 0

        return True
