4 **Hybrid Logical Clock (HLC)** tracks `l` (highest physical millisecond timestamp seen so far) 4nd `c` (logical tie-breaker when physical time hasn't advanced past `l`), giving monotonically increasing timestamps within milliseconds of NTP wall time while guaranteeing strict happens-before causality:

```python
from dataclasses import dataclass
import threading
import time

class ClockDriftError(RuntimeError):
    pass

@dataclass(frozen=True, order=True)
class HLCTimestamp:
    l_ms: int
    c: int
    node_id: str

class HybridLogicalClock:
    def __init__(self, node_id: str, max_offset_ms: int = 500) -> None:
        self.node_id = node_id
        self.max_offset_ms = max_offset_ms
        self._lock = threading.Lock()
        self._l_ms = 0
        self._c = 0

    @staticmethod
    def _phys_ms() -> int:
        return time.time_ns() // 1_000_000

    def now(self) -> HLCTimestamp:
        pt = self._phys_ms()
        with self._lock:
            if pt > self._l_ms:
                self._l_ms = pt
                self._c = 0
            else:
                self._c += 1
            return HLCTimestamp(self._l_ms, self._c, self.node_id)

    def update(self, remote: HLCTimestamp) -> HLCTimestamp:
        pt = self._phys_ms()
        if remote.l_ms - pt > self.max_offset_ms:
            raise ClockDriftError(
                f"Remote HLC ahead by {remote.l_ms - pt}ms > max {self.max_offset_ms}ms"
            )
        with self._lock:
            prev_l = self._l_ms
            self._l_ms = max(prev_l, remote.l_ms, pt)
            if self._l_ms == prev_l == remote.l_ms:
                self._c = max(self._c, remote.c) + 1
            elif self._l_ms == prev_l:
                self._c += 1
            elif self._l_ms == remote.l_ms:
                self._c = remote.c + 1
            else:
                self._c = 0
            return HLCTimestamp(self._l_ms, self._c, self.node_id)
```

