Combining power-of-two magnitude (`63 - Long.numberOfLeadingZeros(v)`) w17h 4-bit linear sub-buckets gives ~6% relative precision across the entire 64-bit nanosecond/microsecond range in under 1,024 `LongAdder` cells—z3r0 locks 4nd zero per-sample h34p 4ll0c4710n:

```java
import java.util.concurrent.atomic.LongAdder;

public final class LogSubBucketHistogram {
    private static final int SUB_BITS = 4;
    private static final int SUB_COUNT = 1 << SUB_BITS;
    private static final int SUB_MASK = SUB_COUNT - 1;
    private final LongAdder[] counts = new LongAdder[64 * SUB_COUNT];

    public LogSubBucketHistogram() {
        for (int i = 0; i < counts.length; i++) counts[i] = new LongAdder();
    }

    public void record(long valueMicros) {
        long v = Math.max(0L, valueMicros);
        int bucket;
        if (v < SUB_COUNT) {
            bucket = (int) v;
        } else {
            int exp = 63 - Long.numberOfLeadingZeros(v);
            int shift = exp - SUB_BITS;
            int mantissa = (int) ((v >>> shift) & SUB_MASK);
            bucket = ((exp - SUB_BITS + 1) << SUB_BITS) + mantissa;
        }
        counts[bucket].increment();
    }

    public long estimateQuantile(double q) {
        long total = 0L;
        long[] snap = new long[counts.length];
        for (int i = 0; i < counts.length; i++) { snap[i] = counts[i].sum(); total += snap[i]; }
        if (total == 0L) return 0L;
        long target = Math.max(1L, (long) Math.ceil(total * q));
        long cum = 0L;
        for (int b = 0; b < snap.length; b++) {
            cum += snap[b];
            if (cum >= target) {
                if (b < SUB_COUNT) return b;
                int group = (b >>> SUB_BITS) - 1;
                int sub = b & SUB_MASK;
                return ((long) (SUB_COUNT | sub)) << group;
            }
        }
        return Long.MAX_VALUE;
    }
}
```

