class FlatAsciiTrie(maxStates: Int = 4096) {
    private val stride = 128
    private val next = IntArray(maxStates * stride) { -1 }
    private val terminal = BooleanArray(maxStates)
    private var stateCount = 1

    fun insert(word: String) {
        var st = 0
        for (ch in word) {
            val code = ch.code
            require(code in 0 until stride) { "Non-ASCII char" }
            val slot = st * stride + code
            var nxt = next[slot]
            if (nxt == -1) {
                nxt = stateCount++
                next[slot] = nxt
            }
            st = nxt
        }
        terminal[st] = true
    }

    fun longestPrefixLen(text: CharSequence, startIdx: Int): Int {
        var st = 0
        var best = -1
        for (i in startIdx until text.length) {
            val code = text[i].code
            if (code !in 0 until stride) break
            st = next[st * stride + code]
            if (st == -1) break
            if (terminal[st]) best = i - startIdx + 1
