```rust
#[derive(Clone, Copy, Default)]
struct TrieNode {
    child: [u32; 2],
    count: u32,
}

pub struct XorTrie {
    nodes: Vec<TrieNode>,
}

impl XorTrie {
    pub fn with_capacity(expected_keys: usize) -> Self {
        let mut nodes = Vec::with_capacity(expected_keys.saturating_mul(32) + 1);
        nodes.push(TrieNode::default()); // index 0 = root (0 is never a valid child index)
        Self { nodes }
    }

    pub fn insert(&mut self, x: u64) {
        let mut cur = 0usize;
        self.nodes[cur].count += 1;
        for shift in (0..64).rev() {
            let bit = ((x >> shift) & 1) as usize;
            let mut next = self.nodes[cur].child[bit] as usize;
            if next == 0 {
                next = self.nodes.len();
                self.nodes.push(TrieNode::default());
                self.nodes[cur].child[bit] = next as u32;
            }
            cur = next;
            self.nodes[cur].count += 1;
        }
    }

    pub fn remove(&mut self, x: u64) -> bool {
        // Verify presence first so unmatched remove() never corrupts counts
        let mut cur = 0usize;
        for shift in (0..64).rev() {
            let bit = ((x >> shift) & 1) as usize;
            let next = self.nodes[cur].child[bit] as usize;
            if next == 0 || self.nodes[next].count == 0 {
                return false;
            }
            cur = next;
        }
        cur = 0;
        self.nodes[cur].count -= 1;
        for shift in (0..64).rev() {
            let bit = ((x >> shift) & 1) as usize;
            cur = self.nodes[cur].child[bit] as usize;
            self.nodes[cur].count -= 1;
        }
        true
    }

    pub fn max_xor(&self, query: u64) -> Option<u64> {
        if self.nodes[0].count == 0 {
            return None;
        }
        let mut cur = 0usize;
        let mut best = 0u64;
        for shift in (0..64).rev() {
            let want = (((query >> shift) & 1) ^ 1) as usize;
            let want_idx = self.nodes[cur].child[want] as usize;
            if want_idx != 0 && self.nodes[want_idx].count > 0 {
                best |= 1u64 << shift;
                cur = want_idx;
            } else {
                cur = self.nodes[cur].child[want ^ 1] as usize;
            }
        }
        Some(best)
    }
}
