#include <bit>
#include <cstddef>
#include <cstdint>
#include <cstring>

const char* find_cr_swar(const char* buf, size_t len) noexcept {
    constexpr uint64_t kOnes = 0x0101010101010101ULL;
    constexpr uint64_t kHigh = 0x8080808080808080ULL;
    constexpr uint64_t kCrMask = kOnes * static_cast<uint8_t>('');

    size_t i = 0;
    for (; i + 8 <= len; i += 8) {
        uint64_t word;
        std::memcpy(&word, buf + i, 8);
        uint64_t x = word ^ kCrMask;
        uint64_t hits = (x - kOnes) & ~x & kHigh;
        if (hits != 0) {
            return buf + i + (std::countr_zero(hits) >> 3);
