#include <cstddef>

class BumpArena {
    std::byte* base_;
    size_t cap_;
    size_t offset_{0};

public:
    BumpArena(std::byte* base, size_t cap) noexcept : base_(base), cap_(cap) {}

    size_t save() const noexcept { return offset_; }
    void rewind(size_t mark) noexcept { offset_ = mark; }

    void* alloc(size_t n, size_t align = 8) noexcept {
        size_t aligned = (offset_ + align - 1) & ~(align - 1);
        if (aligned + n > cap_) return nullptr;
        offset_ = aligned + n;
        return base_ + aligned;
    }
};

struct ArenaScope {
    BumpArena& arena;
    size_t mark;
    explicit ArenaScope(BumpArena& a) noexcept : arena(a), mark(a.save()) {}
    ~ArenaScope() { arena.rewind(mark); }
    ArenaScope(const ArenaScope&) = delete;
};
