```java
public final class CountMinSketch {
    private final int depth;
    private final int widthMask;
    private final int widthShift;
    private final int[] table;

    public CountMinSketch(int depth, int widthPow2) {
        this.depth = depth;
        this.widthMask = widthPow2 - 1;
        this.widthShift = Integer.numberOfTrailingZeros(widthPow2);
        this.table = new int[depth << widthShift];
    }

    public void add(long key, int delta) {
        long h = mix64(key);
        int h1 = (int) h;
        int h2 = (int) (h >>> 32) | 1;
        for (int row = 0; row < depth; row++) {
            int col = (h1 + row * h2) & widthMask;
            table[(row << widthShift) + col] += delta;
        }
    }

    public int estimate(long key) {
        long h = mix64(key);
        int h1 = (int) h;
        int h2 = (int) (h >>> 32) | 1;
        int min = Integer.MAX_VALUE;
        for (int row = 0; row < depth; row++) {
            int col = (h1 + row * h2) & widthMask;
            min = Math.min(min, table[(row << widthShift) + col]);
        }
        return min;
    }

    private static long mix64(long z) {
        z = (z ^ (z >>> 30)) * 0xbf58476d1ce4e5b9L;
        z = (z ^ (z >>> 27)) * 0x94d049bb133111ebL;
        return z ^ (z >>> 31);
    }
}
```

