```kotlin
class PrimitiveSlidingMax(private val windowSize: Int) {
    private val cap = Integer.highestOneBit((windowSize + 1).coerceAtLeast(2) - 1) shl 1
    private val mask = cap - 1
    private val idxRing = IntArray(cap)
    private val valRing = DoubleArray(cap)
    private var head = 0
    private var tail = 0
    private var step = 0

    fun pushAndMax(value: Double): Double {
        val curIdx = step++
        while (head != tail && idxRing[head and mask] <= curIdx - windowSize) {
            head++
        }
        while (head != tail && valRing[(tail - 1) and mask] <= value) {
            tail--
        }
        val slot = tail and mask
        idxRing[slot] = curIdx
        valRing[slot] = value
        tail++
        return valRing[head and mask]
    }
}
