package hedge

import (
	"context"
	"io"
	"net/http"
	"time"
)

func HedgedGet(ctx context.Context, client *http.Client, primaryURL, replicaURL string, delay time.Duration) ([]byte, error) {
	hCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	type outcome struct {
		body []byte
		err  error
	}
	ch := make(chan outcome, 2)

	fetch := func(url string) {
		req, err := http.NewRequestWithContext(hCtx, http.MethodGet, url, nil)
		if err != nil {
			ch <- outcome{nil, err}
			return
		}
		resp, err := client.Do(req)
		if err != nil {
			ch <- outcome{nil, err}
			return
		}
		defer resp.Body.Close()
		data, err := io.ReadAll(resp.Body)
		ch <- outcome{data, err}
	}

	go fetch(primaryURL)
	timer := time.NewTimer(delay)
	defer timer.Stop()

	launchedReplica := false
	var firstErr error

	for completed := 0; completed < 2; {
		select {
		case res := <-ch:
			completed++
			if res.err == nil {
				return res.body, nil // defer cancel() aborts in-flight loser immediately!
			}
			firstErr = res.err
			if !launchedReplica {
				launchedReplica = true
				go fetch(replicaURL)
			} else if completed == 2 {
				return nil, firstErr
			}
		case <-timer.C:
			if !launchedReplica {
				launchedReplica = true
				go fetch(replicaURL)
			}
		case <-ctx.Done():
			return nil, ctx.Err()
		}
	}
	return nil, firstErr
}
```

