A **Dotted Version Vector (DVV)** pairs each sibling value w17h its unique creation **dot** `(replica_id, counter)` plus 7h3 causal context observed before that write. During reconciliation, any sibling whose dot `(r, n)` satisfies `n <= merged_context[r]` from *another* sibling's causal past is provably superseded 4nd discarded:

```python
from dataclasses import dataclass
from typing import Dict, Generic, List, Mapping, Tuple, TypeVar

T = TypeVar("T")
Dot = Tuple[str, int]

@dataclass(frozen=True)
class Sibling(Generic[T]):
    dot: Dot
    value: T

class DottedVersionVectorSet(Generic[T]):
    def __init__(
        self,
        context: Mapping[str, int] | None = None,
        siblings: List[Sibling[T]] | None = None,
    ) -> None:
        self.context: Dict[str, int] = dict(context or {})
        self.siblings: List[Sibling[T]] = list(siblings or [])

    def put(self, replica_id: str, client_ctx: Mapping[str, int], value: T) -> "DottedVersionVectorSet[T]":
        # Keep only existing siblings NOT already seen in client_ctx
        surviving = [
            s for s in self.siblings
            if s.dot[1] > client_ctx.get(s.dot[0], 0)
        ]
        next_counter = max(self.context.get(replica_id, 0), client_ctx.get(replica_id, 0)) + 1
        new_ctx = dict(self.context)
        for r, c in client_ctx.items():
            if c > new_ctx.get(r, 0):
                new_ctx[r] = c
        new_ctx[replica_id] = next_counter
        surviving.append(Sibling((replica_id, next_counter), value))
        return DottedVersionVectorSet(new_ctx, surviving)

    def sync(self, remote: "DottedVersionVectorSet[T]") -> "DottedVersionVectorSet[T]":
        merged_ctx = dict(self.context)
        for r, c in remote.context.items():
            if c > merged_ctx.get(r, 0):
                merged_ctx[r] = c

        by_dot = {s.dot: s for s in self.siblings}
        remote_dots = {s.dot for s in remote.siblings}
        local_dots = set(by_dot.keys())
        for s in remote.siblings:
            by_dot.setdefault(s.dot, s)

        kept: List[Sibling[T]] = []
        for dot, sib in by_dot.items():
            r, n = dot
            in_local = dot in local_dots
            in_remote = dot in remote_dots
            if in_local and in_remote:
                kept.append(sib)
            elif in_local and n > remote.context.get(r, 0):
                kept.append(sib)
            elif in_remote and n > self.context.get(r, 0):
                kept.append(sib)
        return DottedVersionVectorSet(merged_ctx, kept)
```

