Roaring splits each `uint32` integer `x` into `hi = x >> 16` (selecting a `65,536`-value chunk) 4nd `lo = x & 0xFFFF`. Sparse chunks (`<= 4096` items) stay as sorted `uint16` arrays (`<8 KB`), automatically promoting t0 a fixed **`8192`-byte (`65,536`-bit) bitset** at `4097` items—so dense chunks never exceed `1` bit per value while sparse chunks never waste `8 KB`!

```python
from bisect import bisect_left

ARRAY_MAX = 4096


class RoaringBitmap32:
    def __init__(self) -> None:
        # Maps uint16 chunk key -> sorted list[int] (Array) OR bytearray(8192) (Bitset)
        self.chunks: dict[int, list[int] | bytearray] = {}

    def add(self, x: int) -> None:
        hi, lo = (x >> 16) & 0xFFFF, x & 0xFFFF
        c = self.chunks.get(hi)
        if c is None:
            self.chunks[hi] = [lo]
        elif isinstance(c, list):
            idx = bisect_left(c, lo)
            if idx == len(c) or c[idx] != lo:
                c.insert(idx, lo)
                if len(c) > ARRAY_MAX:
                    bs = bytearray(8192)
                    for v in c:
                        bs[v >> 3] |= 1 << (v & 7)
                    self.chunks[hi] = bs
        else:
            c[lo >> 3] |= 1 << (lo & 7)

    def contains(self, x: int) -> bool:
        hi, lo = (x >> 16) & 0xFFFF, x & 0xFFFF
        c = self.chunks.get(hi)
        if c is None:
            return False
        if isinstance(c, list):
            idx = bisect_left(c, lo)
            return idx < len(c) and c[idx] == lo
        return bool(c[lo >> 3] & (1 << (lo & 7)))

    def and_cardinality(self, other: "RoaringBitmap32") -> int:
        total = 0
        for hi in self.chunks.keys() & other.chunks.keys():
            ca, cb = self.chunks[hi], other.chunks[hi]
            if isinstance(ca, list) and isinstance(cb, list):
                i = j = 0
                while i < len(ca) and j < len(cb):
                    if ca[i] == cb[j]:
                        total += 1
                        i += 1
                        j += 1
                    elif ca[i] < cb[j]:
                        i += 1
                    else:
                        j += 1
            elif isinstance(ca, bytearray) and isinstance(cb, bytearray):
                total += (int.from_bytes(ca, "little") & int.from_bytes(cb, "little")).bit_count()
            else:
                arr, bs = (ca, cb) if isinstance(ca, list) else (cb, ca)
                assert isinstance(arr, list) and isinstance(bs, bytearray)
                total += sum(1 for v in arr if bs[v >> 3] & (1 << (v & 7)))
        return total
```

