#include <atomic>
#include <cstddef>
#include <vector>

template <typename T>
class MpmcRing {
    struct alignas(64) Cell {
        std::atomic<size_t> seq;
        T data;
    };

    const size_t mask_;
    std::vector<Cell> buf_;
    alignas(64) std::atomic<size_t> enq_{0};
    alignas(64) std::atomic<size_t> deq_{0};

public:
    explicit MpmcRing(size_t pow2_size) : mask_(pow2_size - 1), buf_(pow2_size) {
        for (size_t i = 0; i < pow2_size; ++i) {
            buf_[i].seq.store(i, std::memory_order_relaxed);
