```cpp
#include <array>
#include <cstdint>
#include <span>
#include <utility>

void radix_sort_u64(std::span<uint64_t> data, std::span<uint64_t> scratch) noexcept {
    const size_t n = data.size();
    uint64_t* src = data.data();
    uint64_t* dst = scratch.data();

    for (unsigned shift = 0; shift < 64; shift += 8) {
        std::array<size_t, 256> count{};
        for (size_t i = 0; i < n; ++i) {
            ++count[(src[i] >> shift) & 0xFF];
        }
        // Skip pass early if all keys share identical byte at this shift!
        bool trivial = false;
        size_t offset = 0;
        for (size_t b = 0; b < 256; ++b) {
            if (count[b] == n) { trivial = true; break; }
            size_t c = count[b];
            count[b] = offset;
            offset += c;
        }
        if (trivial) continue;
        for (size_t i = 0; i < n; ++i) {
            dst[count[(src[i] >> shift) & 0xFF]++] = src[i];
        }
        std::swap(src, dst);
    }
    if (src != data.data()) {
        std::copy(src, src + n, data.data());
    }
}
