        if len(self._seen) < self.k:
            return 1.0
        return (-self._neg_heap[0]) / float(UINT64_MAX)

    def estimate(self) -> float:
        if len(self._seen) < self.k:
            return float(len(self._seen))
        return (self.k - 1) / self.theta

    def intersection_estimate(self, other: "ThetaSketch") -> float:
        theta_min = min(self.theta, other.theta)
        if theta_min == 1.0:
            return float(len(self._seen & other._seen))
