```python
import bisect
import hashlib
import math
from typing import Dict, List, Optional

class BoundedLoadHashRing:
    def __init__(self, vnodes: int = 128, capacity_factor: float = 1.25) -> None:
        if capacity_factor <= 1.0:
            raise ValueError("capacity_factor c must be > 1.0")
        self.vnodes = vnodes
        self.c = capacity_factor
        self._ring_hashes: List[int] = []
        self._ring_nodes: List[str] = []
        self._loads: Dict[str, int] = {}
        self._total_load = 0

    @staticmethod
    def _hash64(key: str) -> int:
        digest = hashlib.sha256(key.encode("utf-8")).digest()
        return int.from_bytes(digest[:8], "big")

    def add_node(self, node_id: str) -> None:
        if node_id in self._loads:
            return
        self._loads[node_id] = 0
        for v in range(self.vnodes):
            h = self._hash64(f"{node_id}#v{v}")
            idx = bisect.bisect_left(self._ring_hashes, h)
            self._ring_hashes.insert(idx, h)
            self._ring_nodes.insert(idx, node_id)

    def max_node_capacity(self) -> int:
        n = len(self._loads)
        if n == 0:
            return 0
        return math.ceil(self.c * (self._total_load + 1) / n)

    def acquire(self, key: str) -> Optional[str]:
        if not self._ring_hashes:
            return None
        cap = self.max_node_capacity()
        idx = bisect.bisect_left(self._ring_hashes, self._hash64(key))
        ring_len = len(self._ring_hashes)
        for step in range(ring_len):
            candidate = self._ring_nodes[(idx + step) % ring_len]
            if self._loads[candidate] < cap:
                self._loads[candidate] += 1
                self._total_load += 1
                return candidate
        return None

    def release(self, node_id: str) -> None:
        if self._loads.get(node_id, 0) > 0:
            self._loads[node_id] -= 1
            self._total_load -= 1
```

