HDR_FMT = ">I"
HDR_LEN = 4

class FrameTooLargeError(ValueError):
    pass

class LengthPrefixedDecoder:
    def __init__(self, max_payload_bytes: int = 4 * 1024 * 1024) -> None:
        self._buf = bytearray()
        self._max_payload = max_payload_bytes

    def feed(self, chunk: bytes | bytearray | memoryview) -> Iterator[bytes]:
        if not chunk:
            return
        self._buf.extend(chunk)
        offset = 0
        total = len(self._buf)

        while total - offset >= HDR_LEN:
            (payload_len,) = struct.unpack_from(HDR_FMT, self._buf, offset)
            if payload_len > self._max_payload:
                self._buf.clear()
                raise FrameTooLargeError(
                    f"frame length {payload_len} exceeds cap {self._max_payload}"
