            frame_end = offset + HDR_LEN + payload_len
            if total < frame_end:
                break  # wait for remaining payload bytes on next EPOLLIN
            yield bytes(self._buf[offset + HDR_LEN : frame_end])
            offset = frame_end

        if offset > 0:
            del self._buf[:offset]

    @staticmethod
    def encode(payload: bytes) -> bytes:
        return struct.pack(HDR_FMT, len(payload)) + payload
