class FastReservoirSampler<T>(private val k: Int) {
    private val reservoir = ArrayList<T>(k)
    private var seen = 0L
    private var w = exp(ln(ThreadLocalRandom.current().nextDouble()) / k)
    private var nextTarget = k.toLong() + skipCount()

    private fun skipCount(): Long {
