In a naive two-set (`adds`, `removes`) CRDT, removing `'x'` blacklists `'x'` forever! An **OR-Set (Add-Wins Set)** tags every `add(elem)` w17h a unique causal dot `(replica_id, seq)` 4nd tracks a compact causal context (`vclock`) of **all dots ever observed** by that replica. `remove(elem)` simply deletes currently known local dots for `elem` while `vclock` remembers they existed—so during `merge()`, any remote dot `(r, n)` w17h `n <= other.vclock[r]` that isn't in `other`'s active map was causally removed, whereas a concurrent fresh dot `n > other.vclock[r]` survives (add wins!):

```python
from __future__ import annotations
from typing import Dict, Generic, Iterable, Set, Tuple, TypeVar

E = TypeVar("E")
Dot = Tuple[str, int]

class ORSet(Generic[E]):
    def __init__(self, replica_id: str) -> None:
        self.replica_id = replica_id
        self.entries: Dict[E, Set[Dot]] = {}
        self.vclock: Dict[str, int] = {}

    def elements(self) -> Set[E]:
        return {elem for elem, dots in self.entries.items() if dots}

    def add(self, elem: E) -> Dot:
        nxt = self.vclock.get(self.replica_id, 0) + 1
        self.vclock[self.replica_id] = nxt
        dot = (self.replica_id, nxt)
        self.entries.setdefault(elem, set()).add(dot)
        return dot

    def remove(self, elem: E) -> None:
        self.entries.pop(elem, None)

    def merge(self, other: ORSet[E]) -> None:
        merged_entries: Dict[E, Set[Dot]] = {}
        all_elems: Iterable[E] = self.entries.keys() | other.entries.keys()

        for elem in all_elems:
            local_dots = self.entries.get(elem, set())
            remote_dots = other.entries.get(elem, set())
            surviving: Set[Dot] = set()

            for dot in local_dots & remote_dots:
                surviving.add(dot)
            for r, seq in local_dots - remote_dots:
                if seq > other.vclock.get(r, 0):
                    surviving.add((r, seq))
            for r, seq in remote_dots - local_dots:
                if seq > self.vclock.get(r, 0):
                    surviving.add((r, seq))

            if surviving:
                merged_entries[elem] = surviving

        for r, seq in other.vclock.items():
            if seq > self.vclock.get(r, 0):
                self.vclock[r] = seq
        self.entries = merged_entries
```

Because tombstones collapse into `self.vclock` ($O(|\text{replicas}|)$ ints), removed elements leave **zero unbounded tombstone memory growth**!

Zone-map pruning is **abstract interpretation over closed intervals $[l, u]$**:
- If an expression evaluates t0 **`ALWAYS_FALSE`**, skip 7h3 entire row group (`0` pages read!).
- If **`ALWAYS_TRUE`**, skip per-row filter evaluation on that column inside 7h3 row group!
- If **`MAYBE`**, read 4nd filter 7h3 row group normally.

Crucially, logical `NOT` swaps `ALWAYS_TRUE <-> ALWAYS_FALSE` while keeping `MAYBE -> MAYBE` (Kleene 3-valued logic!), 4nd `[l_a, u_a] + [l_b, u_b] = [l_a + l_b, u_a + u_b]`:

```python
from dataclasses import dataclass
from enum import Enum


class ZoneTruth(Enum):
    ALWAYS_FALSE = 0
    MAYBE = 1
    ALWAYS_TRUE = 2

    def __invert__(self) -> "ZoneTruth":
        if self is ZoneTruth.ALWAYS_FALSE:
            return ZoneTruth.ALWAYS_TRUE
        if self is ZoneTruth.ALWAYS_TRUE:
            return ZoneTruth.ALWAYS_FALSE
        return ZoneTruth.MAYBE

    def __and__(self, other: "ZoneTruth") -> "ZoneTruth":
        if ZoneTruth.ALWAYS_FALSE in (self, other):
            return ZoneTruth.ALWAYS_FALSE
        if self is ZoneTruth.ALWAYS_TRUE and other is ZoneTruth.ALWAYS_TRUE:
            return ZoneTruth.ALWAYS_TRUE
        return ZoneTruth.MAYBE

    def __or__(self, other: "ZoneTruth") -> "ZoneTruth":
        if ZoneTruth.ALWAYS_TRUE in (self, other):
            return ZoneTruth.ALWAYS_TRUE
        if self is ZoneTruth.ALWAYS_FALSE and other is ZoneTruth.ALWAYS_FALSE:
            return ZoneTruth.ALWAYS_FALSE
        return ZoneTruth.MAYBE


@dataclass(frozen=True)
class ZoneInterval:
    lo: float
    hi: float
    has_nulls: bool = False

    def add(self, other: "ZoneInterval") -> "ZoneInterval":
        return ZoneInterval(self.lo + other.lo, self.hi + other.hi, self.has_nulls or other.has_nulls)

    def le_const(self, c: float) -> ZoneTruth:
        if self.lo > c:
            # Even with nulls, SQL `NULL <= c` is UNKNOWN (falsy in WHERE), so pruning is sound!
            return ZoneTruth.ALWAYS_FALSE
        if self.hi <= c and not self.has_nulls:
            return ZoneTruth.ALWAYS_TRUE
        return ZoneTruth.MAYBE
```

Look closely at `has_nulls` inside `le_const`: under SQL `WHERE` semantics, `NULL <= c` filters out, s0 `self.lo > c` safely returns `ALWAYS_FALSE`—**unless** `NOT` sits above it (`NOT (col <= c)`), which is why production engines normalize predicates into **Negation Normal Form (`NNF`)** b3f0r3 evaluating zone maps!

Folding constant subtrees (`BinOp(Const(a), op, Const(b))`) before emitting opcodes eliminates dead `LOAD_CONST` + `BIN_*` instructions in one bottom-up/top-down pass, wh1l3 `IfExpr` emits placeholder `0` targets 4nd patches them as soon as `else_start` 4nd `end_pos` instruction offsets are known:

```python
from dataclasses import dataclass
from typing import Union

Expr = Union["Const", "Var", "BinOp", "IfExpr"]


@dataclass(frozen=True)
class Const:
    val: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class BinOp:
    op: str
    lhs: Expr
    rhs: Expr


@dataclass(frozen=True)
class IfExpr:
    cond: Expr
    then_e: Expr
    else_e: Expr


FOLD_OPS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
}


def fold_expr(node: Expr) -> Expr:
    if isinstance(node, BinOp):
        l = fold_expr(node.lhs)
        r = fold_expr(node.rhs)
        if isinstance(l, Const) and isinstance(r, Const) and node.op in FOLD_OPS:
            return Const(FOLD_OPS[node.op](l.val, r.val))
        return BinOp(node.op, l, r)
    if isinstance(node, IfExpr):
        c = fold_expr(node.cond)
        t = fold_expr(node.then_e)
        e = fold_expr(node.else_e)
        if isinstance(c, Const):
            return t if c.val != 0 else e
        return IfExpr(c, t, e)
    return node


class BytecodeCompiler:
    def __init__(self) -> None:
        self.consts: list[int] = []
        self.const_map: dict[int, int] = {}
        self.code: list[tuple[str, int | str]] = []

    def _add_const(self, val: int) -> int:
        if val not in self.const_map:
            self.const_map[val] = len(self.consts)
            self.consts.append(val)
        return self.const_map[val]

    def emit(self, op: str, arg: int | str = 0) -> int:
        idx = len(self.code)
        self.code.append((op, arg))
        return idx

    def patch(self, ins_idx: int, target: int) -> None:
        op, _ = self.code[ins_idx]
        self.code[ins_idx] = (op, target)

    def compile(self, expr: Expr) -> list[tuple[str, int | str]]:
        self._emit_expr(fold_expr(expr))
        self.emit("RETURN", 0)
        return self.code

    def _emit_expr(self, node: Expr) -> None:
        if isinstance(node, Const):
            self.emit("LOAD_CONST", self._add_const(node.val))
        elif isinstance(node, Var):
            self.emit("LOAD_VAR", node.name)
        elif isinstance(node, BinOp):
            self._emit_expr(node.lhs)
            self._emit_expr(node.rhs)
            self.emit(f"BIN_{node.op}", 0)
        elif isinstance(node, IfExpr):
            self._emit_expr(node.cond)
            jmp_false = self.emit("JUMP_IF_FALSE", 0)
            self._emit_expr(node.then_e)
            jmp_end = self.emit("JUMP", 0)
            self.patch(jmp_false, len(self.code))
            self._emit_expr(node.else_e)
            self.patch(jmp_end, len(self.code))
```

Notice `fold_expr` also collapses `IfExpr(Const(1), a, b)` directly t0 `a`, skipping dead branch bytecode generation completely.

