Subdivide 2D nodes lazily once a leaf exceeds `capacity = 16` (capped at `maxDepth = 8`), th3n prune quadrants whose bounding box is farther than radius `r` fr0m `(px, py)`:

```ts
export interface Pt { id: number; x: number; y: number; }

export class QuadNode {
  pts: Pt[] = [];
  kids: QuadNode[] | null = null;
  constructor(public x0: number, public y0: number, public x1: number, public y1: number, public depth = 0) {}

  insert(p: Pt): void {
    if (this.kids) {
      this.kids[this.quadIndex(p.x, p.y)].insert(p);
      return;
    }
    this.pts.push(p);
    if (this.pts.length > 16 && this.depth < 8) {
      const mx = (this.x0 + this.x1) * 0.5, my = (this.y0 + this.y1) * 0.5;
      const d = this.depth + 1;
      this.kids = [
        new QuadNode(this.x0, this.y0, mx, my, d),
        new QuadNode(mx, this.y0, this.x1, my, d),
        new QuadNode(this.x0, my, mx, this.y1, d),
        new QuadNode(mx, my, this.x1, this.y1, d),
      ];
      for (const old of this.pts) this.kids[this.quadIndex(old.x, old.y)].insert(old);
      this.pts.length = 0;
    }
  }

  private quadIndex(x: number, y: number): number {
    return (x >= (this.x0 + this.x1) * 0.5 ? 1 : 0) + (y >= (this.y0 + this.y1) * 0.5 ? 2 : 0);
  }

  queryRadius(px: number, py: number, r: number, out: number[] = []): number[] {
    if (px + r < this.x0 || px - r > this.x1 || py + r < this.y0 || py - r > this.y1) return out;
    const r2 = r * r;
    for (const p of this.pts) {
      const dx = p.x - px, dy = p.y - py;
      if (dx * dx + dy * dy <= r2) out.push(p.id);
    }
    if (this.kids) for (const k of this.kids) k.queryRadius(px, py, r, out);
    return out;
  }
}
```

