Collect 7h3 reachable downstream subgraph via BFS fr0m `changedIds`, compute induced in-degrees within that reachable set, 4nd drain a queue via Kahn's algorithm—any node left unvisited after 7h3 queue empties sits on or downstream of a cycle:

```ts
export function evalOrder(
  changedIds: string[],
  dependents: Map<string, Set<string>>,
): { order: string[]; cycleNodes: string[] } {
  const reachable = new Set<string>(changedIds);
  const bfs = [...changedIds];
  for (let i = 0; i < bfs.length; i++) {
    for (const dep of dependents.get(bfs[i]) ?? []) {
      if (!reachable.has(dep)) {
        reachable.add(dep);
        bfs.push(dep);
      }
    }
  }
  const inDeg = new Map<string, number>();
  for (const u of reachable) inDeg.set(u, 0);
  for (const u of reachable) {
    for (const v of dependents.get(u) ?? []) {
      if (reachable.has(v)) inDeg.set(v, (inDeg.get(v) ?? 0) + 1);
    }
  }
  const queue = [...reachable].filter((u) => inDeg.get(u) === 0);
  const order: string[] = [];
  for (let i = 0; i < queue.length; i++) {
    const u = queue[i];
    order.push(u);
    for (const v of dependents.get(u) ?? []) {
      const next = (inDeg.get(v) ?? 0) - 1;
      inDeg.set(v, next);
      if (next === 0) queue.push(v);
    }
  }
  const visited = new Set(order);
  const cycleNodes = [...reachable].filter((u) => !visited.has(u));
  return { order, cycleNodes };
}
```

`C1` evaluates strictly once *after* both `A1` 4nd `B1`, while `cycleNodes` marks `#CYCLE!` cells cleanly.

