class LongFenwickTree(private val size: Int) {
    private val tree = LongArray(size + 1)

    fun add(zeroBasedIdx: Int, delta: Long) {
        require(zeroBasedIdx in 0 until size)
        var i = zeroBasedIdx + 1
        while (i <= size) {
            tree[i] += delta
            i += i and -i
        }
    }

    fun prefixSum(zeroBasedInclusive: Int): Long {
        if (zeroBasedInclusive < 0) return 0L
        var i = (zeroBasedInclusive + 1).coerceAtMost(size)
        var sum = 0L
        while (i > 0) {
            sum += tree[i]
            i -= i and -i
        }
        return sum
    }

    fun rangeSum(leftInclusive: Int, rightInclusive: Int): Long =
        if (leftInclusive > rightInclusive) 0L
        else prefixSum(rightInclusive) - prefixSum(leftInclusive - 1)
}
