```rust
use std::collections::VecDeque;
use std::io::{self, Read, Write};

pub struct EdgeConn<S> {
    pub stream: S,
    pub read_ready: bool,
    pub write_ready: bool,
    pub peer_closed: bool,
    out_buf: VecDeque<u8>,
}

impl<S: Read + Write> EdgeConn<S> {
    pub fn new(stream: S) -> Self {
        Self {
            stream,
            read_ready: false,
            write_ready: true, // fresh connected socket starts writable before first WouldBlock!
            peer_closed: false,
            out_buf: VecDeque::new(),
        }
    }

    pub fn on_epoll_events(&mut self, is_readable: bool, is_writable: bool) {
        if is_readable {
            self.read_ready = true;
        }
        if is_writable {
            self.write_ready = true;
        }
    }

    pub fn drain_reads(&mut self, mut on_chunk: impl FnMut(&[u8])) -> io::Result<()> {
        let mut tmp = [0u8; 16384];
        while self.read_ready && !self.peer_closed {
            match self.stream.read(&mut tmp) {
                Ok(0) => {
                    self.peer_closed = true;
                    self.read_ready = false;
                }
                Ok(n) => on_chunk(&tmp[..n]),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => {
                    self.read_ready = false;
                }
                Err(e) => return Err(e),
            }
        }
        Ok(())
    }

    pub fn queue_and_flush(&mut self, data: &[u8]) -> io::Result<bool> {
        self.out_buf.extend(data);
        while self.write_ready && !self.out_buf.is_empty() {
            let (front, _) = self.out_buf.as_slices();
            match self.stream.write(front) {
                Ok(0) => return Err(io::Error::new(io::ErrorKind::WriteZero, "zero write")),
                Ok(n) => {
                    self.out_buf.drain(..n);
                }
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => {
                    self.write_ready = false;
                }
                Err(e) => return Err(e),
            }
        }
        Ok(self.out_buf.is_empty())
    }
}
```

