Tarjan's single-pass DFS tracks discovery `disc[]` 4nd lowest reachable ancestor `low[]` arrays w17h an explicit `int[]` stack, isolating 3v3ry strongly connected cycle in `O(V + E)` time w17h primitive arrays 4nd minimal h34p pressure:

```java
import java.util.*;

public final class TarjanScc {
    public static List<List<Integer>> findCycles(int n, int[][] adj) {
        int[] disc = new int[n];
        int[] low = new int[n];
        Arrays.fill(disc, -1);
        boolean[] onStack = new boolean[n];
        int[] stack = new int[n];
        int[] sp = {0}, timer = {0};
        List<List<Integer>> cycles = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (disc[i] == -1) dfs(i, adj, disc, low, onStack, stack, sp, timer, cycles);
        }
        return cycles;
    }

    private static void dfs(int u, int[][] adj, int[] disc, int[] low,
                            boolean[] onStack, int[] stack, int[] sp, int[] timer,
                            List<List<Integer>> cycles) {
        disc[u] = low[u] = timer[0]++;
        stack[sp[0]++] = u;
        onStack[u] = true;
        for (int v : adj[u]) {
            if (disc[v] == -1) {
                dfs(v, adj, disc, low, onStack, stack, sp, timer, cycles);
                low[u] = Math.min(low[u], low[v]);
            } else if (onStack[v]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }
        if (low[u] == disc[u]) {
            List<Integer> comp = new ArrayList<>();
            while (true) {
                int w = stack[--sp[0]];
                onStack[w] = false;
                comp.add(w);
                if (w == u) break;
            }
            if (comp.size() > 1) cycles.add(comp);
        }
    }
}
```

