Tarjan's DFS pops a strongly connected component `C` off 7h3 tarjan stack **only after every outgoing edge fr0m `C` t0 downstream SCCs has already finished 4nd popped**! That means Tarjan emits SCCs in **exact reverse topological order**—simply reversing 7h3 `sccs` vector at 7h3 end gives a valid forward topological sort of 7h3 condensed DAG in one $O(V + E)$ pass w17h zero extra Kahn sorting:

```rust
pub struct TarjanCondensation {
    pub sccs_topo: Vec<Vec<usize>>, // forward topological order of SCCs
    pub comp_of: Vec<usize>,        // vertex -> topological SCC id (0..num_sccs)
}

pub fn condense_scc_topo(num_nodes: usize, adj: &[Vec<usize>]) -> TarjanCondensation {
    struct State {
        timer: u32,
        disc: Vec<u32>,
        low: Vec<u32>,
        on_stack: Vec<bool>,
        stack: Vec<usize>,
        sccs_rev: Vec<Vec<usize>>,
    }

    fn dfs(u: usize, adj: &[Vec<usize>], st: &mut State) {
        st.timer += 1;
        st.disc[u] = st.timer;
        st.low[u] = st.timer;
        st.stack.push(u);
        st.on_stack[u] = true;

        for &v in &adj[u] {
            if st.disc[v] == 0 {
                dfs(v, adj, st);
                st.low[u] = st.low[u].min(st.low[v]);
            } else if st.on_stack[v] {
                st.low[u] = st.low[u].min(st.disc[v]);
            }
        }

        if st.low[u] == st.disc[u] {
            let mut comp = Vec::new();
            while let Some(w) = st.stack.pop() {
                st.on_stack[w] = false;
                comp.push(w);
                if w == u {
                    break;
                }
            }
            st.sccs_rev.push(comp);
        }
    }

    let mut st = State {
        timer: 0,
        disc: vec![0; num_nodes],
        low: vec![0; num_nodes],
        on_stack: vec![false; num_nodes],
        stack: Vec::with_capacity(num_nodes),
        sccs_rev: Vec::new(),
    };

    for u in 0..num_nodes {
        if st.disc[u] == 0 {
            dfs(u, adj, &mut st);
        }
    }

    st.sccs_rev.reverse();
    let mut comp_of = vec![0; num_nodes];
    for (cid, comp) in st.sccs_rev.iter().enumerate() {
        for &v in comp {
            comp_of[v] = cid;
        }
    }

    TarjanCondensation {
        sccs_topo: st.sccs_rev,
        comp_of,
    }
}
```

For any cross-component edge `u -> v` (`comp_of[u] != comp_of[v]`), `comp_of[u] < comp_of[v]` now holds unconditionally.

