A standard Bloom Filter hashes `k = 4` positions across the *entire* 64 MiB bit-vector, forcing up t0 **4 independent DRAM cacheline loads** per trace ID! A **Cacheline-Blocked (Split-Block) Bloom Filter** uses the upper hash bits t0 pick a **single 64-byte (512-bit) `alignas(64)` block**, then sets/tests all `k = 8` bits strictly *inside that one 64-byte cacheline*—guaranteed `<= 1` LLC miss per check!

```cpp
#include <array>
#include <cstdint>
#include <vector>

class BlockedBloom64 {
    struct alignas(64) Block {
        std::array<uint64_t, 8> words{}; // 64 bytes = 512 bits (1 full cacheline)
    };
    size_t mask_;
    std::vector<Block> blocks_;

public:
    explicit BlockedBloom64(size_t pow2_blocks) : mask_(pow2_blocks - 1), blocks_(pow2_blocks) {}

    void insert(uint64_t hash64) noexcept {
        Block& b = blocks_[(hash64 >> 32) & mask_];
        uint32_t h = static_cast<uint32_t>(hash64);
        for (int i = 0; i < 8; ++i) {
            uint32_t bit = (h * (0x9E3779B1u + static_cast<uint32_t>(i) * 0x85EBCA77u)) >> 26; // 0..63
            b.words[i] |= (1ULL << bit);
        }
    }

    bool possibly_contains(uint64_t hash64) const noexcept {
        const Block& b = blocks_[(hash64 >> 32) & mask_];
        uint32_t h = static_cast<uint32_t>(hash64);
        uint64_t ok = 1;
        for (int i = 0; i < 8; ++i) {
            uint32_t bit = (h * (0x9E3779B1u + static_cast<uint32_t>(i) * 0x85EBCA77u)) >> 26;
            ok &= (b.words[i] >> bit);
        }
        return ok != 0;
    }
};
```

