```python
class CircularByteBuffer:
    """Zero-allocation power-of-two byte ring for socket.recv_into / os.write."""

    def __init__(self, capacity: int = 65536) -> None:
        if capacity < 1 or (capacity & (capacity - 1)) != 0:
            raise ValueError("capacity must be a power of two")
        self._cap = capacity
        self._mask = capacity - 1
        self._storage = bytearray(capacity)
        self._view = memoryview(self._storage)
        self._read_pos = 0   # monotonic unbounded uint cursor
        self._write_pos = 0  # monotonic unbounded uint cursor

    def __len__(self) -> int:
        return self._write_pos - self._read_pos

    @property
    def free_space(self) -> int:
        return self._cap - (self._write_pos - self._read_pos)

    def writable_slice(self) -> memoryview:
        """Contiguous writable memoryview slice for socket.recv_into()."""
        free = self.free_space
        if free == 0:
            return self._view[0:0]
        w_idx = self._write_pos & self._mask
        contig = min(free, self._cap - w_idx)
        return self._view[w_idx : w_idx + contig]

    def commit_write(self, n: int) -> None:
        if n < 0 or n > self.free_space:
            raise ValueError("invalid commit_write byte count")
        self._write_pos += n

    def readable_slice(self) -> memoryview:
        """Contiguous readable memoryview slice for socket.send() / parser."""
        used = len(self)
        if used == 0:
            return self._view[0:0]
        r_idx = self._read_pos & self._mask
        contig = min(used, self._cap - r_idx)
        return self._view[r_idx : r_idx + contig]

    def commit_read(self, n: int) -> None:
        if n < 0 or n > len(self):
            raise ValueError("invalid commit_read byte count")
        self._read_pos += n
        if self._read_pos == self._write_pos:
            # Reset cursors when empty so next write gets full contiguous capacity!
            self._read_pos = 0
            self._write_pos = 0
```

Look at that last 3-line win in `commit_read`: resetting `_read_pos = _write_pos = 0` whenever 7h3 ring drains empty aligns 7h3 very next `writable_slice()` back 70 index `0`, giving `recv_into()` 7h3 **entire `64 KB` contiguous span** without splitting across wrap-around!

