public V getOrLoad(StampedLock sl, K key, Map<K, V> map, Function<K, V> loader) {
    long stamp = sl.readLock();
    try {
        V val = map.get(key);
        if (val != null) return val;
        long ws = sl.tryConvertToWriteLock(stamp);
        if (ws != 0L) {
            stamp = ws;
            val = loader.apply(key);
            map.put(key, val);
            return val;
