public final class CompactUnionFind {
    private final int[] data; // < 0 means root with size = -data[x]; >= 0 means parent index

    public CompactUnionFind(int n) {
        this.data = new int[n];
        Arrays.fill(this.data, -1);
    }

    public int find(int x) {
        while (data[x] >= 0) {
            int p = data[x];
            if (data[p] >= 0) data[x] = data[p]; // path halving
            x = p;
        }
        return x;
    }

