class ByteHorspoolMatcher(private val pattern: ByteArray) {
    private val skip = IntArray(256) { pattern.size }

    init {
        require(pattern.isNotEmpty())
        for (i in 0 until pattern.lastIndex) {
            skip[pattern[i].toInt() and 0xFF] = pattern.lastIndex - i
