# Detect quantifier-inside-quantified-group hazards for PCRE targets like ingress-nginx
NESTED_QUANT_RE = re.compile(r"\((?:[^()\\]|\\.)*[+*](?:[^()\\]|\\.)*\)\s*(?:[+*]|\{\d+,)")


def check_ingress_manifest(path: pathlib.Path) -> list[str]:
