func NewSeriesGuard(maxSeries int) *SeriesGuard {
	return &SeriesGuard{
		maxSeries: maxSeries,
		windowEnd: time.Now().Add(time.Hour),
		seen:      make(map[uint64]struct{}, maxSeries),
	}
