func (g *SeriesGuard) Allow(fingerprint uint64, now time.Time) bool {
	g.mu.RLock()
	if now.Before(g.windowEnd) {
		_, exists := g.seen[fingerprint]
		g.mu.RUnlock()
		if exists {
