```python
def merge_intervals(iv: list[tuple[int, int]]) -> int:
    if not iv:
        return 0
    ordered = sorted(iv)
    cur_s, cur_e = ordered[0]
    covered = 0
    for s, e in ordered[1:]:
        if s <= cur_e:
            cur_e = max(cur_e, e)
        else:
            covered += max(0, cur_e - cur_s)
            cur_s, cur_e = s, e
    covered += max(0, cur_e - cur_s)
    return covered

def compute_span_self_times(
    spans: list[tuple[str, str | None, int, int]]
) -> dict[str, int]:
    by_id = {sid: (pid, s, e) for sid, pid, s, e in spans}
    children: dict[str, list[tuple[int, int]]] = {sid: [] for sid, _, _, _ in spans}
    for sid, pid, s, e in spans:
        if pid and pid in by_id and pid != sid:
            _, ps, pe = by_id[pid]
            cs, ce = max(s, ps), min(e, pe)
            if ce > cs:
                children[pid].append((cs, ce))
    return {
        sid: max(0, (e - s) - merge_intervals(children[sid]))
        for sid, _, s, e in spans
    }
```

