```java
public final class DaryLongMinHeap {
    private int[] nodes;
    private long[] prios;
    private int size;

    public DaryLongMinHeap(int cap) {
        this.nodes = new int[cap];
        this.prios = new long[cap];
    }

    public boolean isEmpty() { return size == 0; }

    public void push(int node, long prio) {
        int i = size++;
        while (i > 0) {
            int parent = (i - 1) >>> 2;
            if (prios[parent] <= prio) break;
            nodes[i] = nodes[parent];
            prios[i] = prios[parent];
            i = parent;
        }
        nodes[i] = node;
        prios[i] = prio;
    }

    public int popMinNode(long[] outPrio) {
        int minNode = nodes[0];
        outPrio[0] = prios[0];
        int n = --size;
        if (n > 0) {
            int lastNode = nodes[n];
            long lastPrio = prios[n];
            int i = 0;
            while (true) {
                int c0 = (i << 2) + 1;
                if (c0 >= n) break;
                int best = c0;
                long bestP = prios[c0];
                int limit = Math.min(c0 + 4, n);
                for (int c = c0 + 1; c < limit; c++) {
                    if (prios[c] < bestP) { best = c; bestP = prios[c]; }
                }
                if (lastPrio <= bestP) break;
                nodes[i] = nodes[best];
                prios[i] = bestP;
                i = best;
            }
            nodes[i] = lastNode;
            prios[i] = lastPrio;
        }
        return minNode;
    }
}
