class RendezvousPlacement(nodes: List<String>) {
    private val nodeIds = nodes.toTypedArray()
    private val nodeSeeds = LongArray(nodes.size) { mix64(nodes[it].hashCode().toLong()) }

    fun selectReplicas(blobKey: Long, replicas: Int): List<String> {
        val k = replicas.coerceIn(0, nodeIds.size)
        if (k == 0) return emptyList()
        val topIdx = IntArray(k) { -1 }
        val topScore = LongArray(k) { Long.MIN_VALUE }

        for (i in nodeIds.indices) {
            val score = mix64(blobKey xor nodeSeeds[i])
            if (score > topScore[k - 1]) {
                var pos = k - 1
                while (pos > 0 && score > topScore[pos - 1]) {
                    topScore[pos] = topScore[pos - 1]
                    topIdx[pos] = topIdx[pos - 1]
                    pos--
                }
                topScore[pos] = score
                topIdx[pos] = i
            }
        }
        return List(k) { nodeIds[topIdx[it]] }
    }

    private fun mix64(z0: Long): Long {
        var z = (z0 + -0x61c8864680b583ebL)
        z = (z xor (z ushr 30)) * -0x40a7b892e31b1a47L
        z = (z xor (z ushr 27)) * -0x6b2fb644ecceee15L
        return z xor (z ushr 31)
    }
}
```

