import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
)

func checkFile(path string) int {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return 1
	}
	violations := 0
	ast.Inspect(f, func(n ast.Node) bool {
