#include <cstddef>
#include <cstdint>

struct alignas(64) EpochArena {
    std::byte* buf;
    size_t cap;
    std::atomic<size_t> offset{0};
    std::atomic<uint32_t> active_refs{0};

    void* alloc(size_t n) noexcept {
