from __future__ import annotations
from typing import Dict

class PNCounter:
    def __init__(self, node_id: str) -> None:
        self.node_id = node_id
        self.p: Dict[str, int] = {}
        self.n: Dict[str, int] = {}

    def increment(self, amount: int = 1) -> Dict[str, Dict[str, int]]:
        if amount < 0:
            raise ValueError("amount must be >= 0; use decrement()")
        nxt = self.p.get(self.node_id, 0) + amount
        self.p[self.node_id] = nxt
        # Return minimal delta state for bandwidth-efficient delta-CRDT shipping:
        return {"p": {self.node_id: nxt}, "n": {}}

    def decrement(self, amount: int = 1) -> Dict[str, Dict[str, int]]:
        if amount < 0:
            raise ValueError("amount must be >= 0")
        nxt = self.n.get(self.node_id, 0) + amount
        self.n[self.node_id] = nxt
        return {"p": {}, "n": {self.node_id: nxt}}

    def value(self) -> int:
        return sum(self.p.values()) - sum(self.n.values())

    def merge_state(self, remote_p: Dict[str, int], remote_n: Dict[str, int]) -> None:
        for node, val in remote_p.items():
            if val > self.p.get(node, 0):
                self.p[node] = val
        for node, val in remote_n.items():
            if val > self.n.get(node, 0):
                self.n[node] = val

    def merge(self, other: PNCounter) -> None:
        self.merge_state(other.p, other.n)
```

