Critical Path Method (CPM) runs two linear $O(V + E)$ passes over a single topological ordering `topo`:
1. **Forward pass (`topo` left-to-right)**: `ES[v] = max(EF[u] for u -> v)` and `EF[v] = ES[v] + duration[v]`; project `makespan = max(EF.values())`.
2. **Backward pass (`reversed(topo)` right-to-left)**: `LF[u] = min((LS[v] for u -> v), default=makespan)` and `LS[u] = LF[u] - duration[u]`. Any task w17h `slack[u] = LS[u] - ES[u] == 0` sits on 7h3 critical path (delaying it by 1ms delays 7h3 whole build by 1ms!):

```python
from collections import defaultdict, deque
from dataclasses import dataclass


@dataclass(frozen=True)
class TaskSchedule:
    es: int
    ef: int
    ls: int
    lf: int
    slack: int


def analyze_cpm(
    durations: dict[str, int], edges: list[tuple[str, str]]
) -> tuple[int, dict[str, TaskSchedule], list[str]]:
    adj: dict[str, list[str]] = defaultdict(list)
    indeg: dict[str, int] = {u: 0 for u in durations}

    for u, v in set(edges):
        adj[u].append(v)
        indeg[v] += 1

    q = deque(u for u, d in indeg.items() if d == 0)
    topo: list[str] = []
    es: dict[str, int] = {u: 0 for u in durations}
    ef: dict[str, int] = {}

    while q:
        u = q.popleft()
        topo.append(u)
        ef[u] = es[u] + durations[u]
        for v in adj[u]:
            if ef[u] > es[v]:
                es[v] = ef[u]
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    if len(topo) != len(durations):
        raise ValueError("Cycle detected in task DAG")

    makespan = max(ef.values(), default=0)
    lf: dict[str, int] = {u: makespan for u in durations}
    ls: dict[str, int] = {}

    for u in reversed(topo):
        for v in adj[u]:
            if ls[v] < lf[u]:
                lf[u] = ls[v]
        ls[u] = lf[u] - durations[u]

    sched = {
        u: TaskSchedule(es[u], ef[u], ls[u], lf[u], ls[u] - es[u])
        for u in topo
    }

    # Reconstruct one concrete zero-slack chain from start=0 to ef==makespan
    crit_chain: list[str] = []
    cur = next((u for u in topo if es[u] == 0 and sched[u].slack == 0), None)
    while cur is not None:
        crit_chain.append(cur)
        cur = next(
            (v for v in adj[cur] if sched[v].slack == 0 and es[v] == ef[cur]),
            None,
        )

    return makespan, sched, crit_chain
```

Notice `es[v] == ef[cur]` alongside `slack == 0` in `crit_chain`: when multiple parallel critical paths exist, checking tight handoff `es[v] == ef[cur]` guarantees `crit_chain` forms a contiguous causal path rather than a jumbled list of zero-slack nodes.

Aoe's **Double-Array Trie** encodes every trie edge `(s, c) -> t` into two parallel integer arrays `base[]` 4nd `check[]` via a single invariant:

$$t = \text{base}[s] + \text{code}(c) \quad \text{and} \quad \text{check}[t] == s$$

During construction over a prefix trie, for any node `s` w17h outgoing character codes $c_1, \dots, c_k$, we find 7h3 smallest offset `b >= 1` such that `check[b + c_i] == -1` (free) f0r all $i$, claim those slots (`check[b + c_i] = s`), 4nd store end-of-word markers using code `0` (`'\0'` sentinel child w17h `base[leaf] < 0`):

```python
class DoubleArrayTrie:
    def __init__(self, words: list[str]) -> None:
        # 1. Build temporary nested dict trie first (code 0 = terminal marker)
        root: dict[int, dict] = {}
        for w in words:
            cur = root
            for ch in w.encode("utf-8"):
                cur = cur.setdefault(ch + 1, {})  # shift bytes to 1..256; reserve 0 for EOW
            cur.setdefault(0, {})

        self.base: list[int] = [0] * 512
        self.check: list[int] = [-1] * 512
        self.check[0] = 0
        self._first_free = 1
        self._pack(0, root)

    def _ensure(self, idx: int) -> None:
        if idx >= len(self.base):
            grow = max(idx + 1 - len(self.base), len(self.base))
            self.base.extend([0] * grow)
            self.check.extend([-1] * grow)

    def _find_base(self, codes: list[int]) -> int:
        first_c = codes[0]
        pos = max(self._first_free, first_c + 1)
        while True:
            self._ensure(pos + codes[-1] - first_c)
            if self.check[pos] != -1:
                pos += 1
                continue
            b = pos - first_c
            if all(self.check[b + c] == -1 for c in codes):
                return b
            pos += 1

    def _pack(self, state: int, node: dict[int, dict]) -> None:
        if not node:
            self.base[state] = -1  # terminal leaf marker
            return
        codes = sorted(node.keys())
        b = self._find_base(codes)
        self.base[state] = b
        for c in codes:
            t = b + c
            self.check[t] = state
        while self._first_free < len(self.check) and self.check[self._first_free] != -1:
            self._first_free += 1
        for c in codes:
            self._pack(b + c, node[c])

    def contains(self, word: str) -> bool:
        s = 0
        for byte in word.encode("utf-8"):
            c = byte + 1
            b = self.base[s]
            if b <= 0:
                return False
            t = b + c
            if t >= len(self.check) or self.check[t] != s:
                return False
            s = t
        b = self.base[s]
        if b <= 0:
            return False
        eow = b + 0
        return eow < len(self.check) and self.check[eow] == s
```

Tracking `self._first_free` avoids rescanning full prefix regions from index `1`, while `contains()` touches only two contiguous `int` vectors per byte!

Two things multiply inside Rust's `regex` compiler:
1. **Bounded repetitions `{0,4000}` are explicitly unrolled** into 4,000 sequential NFA copies (unlike unbounded `*`, Thompson NFAs have no runtime counter registers t0 stay pure finite-state!).
2. **Unicode `\w` (`(?u:\w)`)** matches ~140,000 Unicode codepoints across dozens of multi-byte UTF-8 DFA trie states (~50–80 byte-NFA states *per single `\w`*)! Unrolling 4,000 copies of Unicode `\w` generates `4,000 * ~70 = ~280,000` NFA states, blowing straight past `RegexBuilder::size_limit`'s 10 MiB safety cap!

