use regex::Regex;

pub fn build_tag_matcher(tag: &str) -> Result<Regex, regex::Error> {
    let pat = format!(r"^(?-u:\w)*:{}$", regex::escape(tag));
    Regex::new(&pat)
}

pub fn matches_bounded(re: &Regex, line: &str) -> bool {
    let Some((prefix, _)) = line.split_once(':') else {
        return false;
    };
    // Enforce <= 4000 chars in O(1)/O(N) without unrolling 4,000 NFA copies!
    prefix.chars().take(4001).count() <= 4000 && re.is_match(line)
}
```

