export class SlidingMinMax {
  private minIdx: number[] = [];
  private maxIdx: number[] = [];
  private ring: Float64Array;
  private step = 0;

  constructor(private readonly windowSize: number) {
    this.ring = new Float64Array(windowSize);
  }

  push(val: number): [number, number] {
    const i = this.step++;
    const w = this.windowSize;
    this.ring[i % w] = val;

    if (this.minIdx.length && this.minIdx[0] <= i - w) this.minIdx.shift();
    if (this.maxIdx.length && this.maxIdx[0] <= i - w) this.maxIdx.shift();

    while (this.minIdx.length && this.ring[this.minIdx.at(-1)! % w] >= val) this.minIdx.pop();
    while (this.maxIdx.length && this.ring[this.maxIdx.at(-1)! % w] <= val) this.maxIdx.pop();

    this.minIdx.push(i);
    this.maxIdx.push(i);
    return [this.ring[this.minIdx[0] % w], this.ring[this.maxIdx[0] % w]];
  }
}
```

