Use a Fenwick tree (Binary Indexed Tree) over a `Float64Array` (`1`-indexed): point height deltas (`add(idx, newH - oldH)`) update `O(log n)` tree nodes, `prefixSum(idx)` computes cumulative pixel offset in `O(log n)`, 4nd binary lifting (`lowerBound`) finds the visible row for `scrollTop` in a single `O(log n)` pass:

```ts
export class HeightFenwick {
  private tree: Float64Array;
  constructor(private readonly n: number) {
    this.tree = new Float64Array(n + 1);
  }
  add(index0: number, delta: number): void {
    for (let i = index0 + 1; i <= this.n; i += i & -i) this.tree[i] += delta;
  }
  prefixSum(count: number): number {
    let s = 0;
    for (let i = count; i > 0; i -= i & -i) s += this.tree[i];
    return s;
  }
  findRowAtOffset(scrollTop: number): number {
    let pos = 0, acc = 0;
    for (let bit = 1 << Math.floor(Math.log2(this.n)); bit > 0; bit >>= 1) {
      const next = pos + bit;
      if (next <= this.n && acc + this.tree[next] <= scrollTop) {
        pos = next;
        acc += this.tree[pos];
      }
    }
    return Math.min(pos, this.n - 1);
  }
}
```

