Downscaling an exponential histogram by `delta = scale - target_scale` bits merges `2^delta` adjacent buckets via arithmetic right-shift (`idx >> delta`), letting y0u aggregate multi-pod latency sketches w17h exact bucket alignment 4nd zero floating-point precision loss:

```python
def downscale_buckets(
    offset: int, counts: list[int], scale_diff: int
) -> tuple[int, list[int]]:
    if scale_diff <= 0 or not counts:
        return offset, list(counts)
    new_start = offset >> scale_diff
    new_end = (offset + len(counts) - 1) >> scale_diff
    merged = [0] * (new_end - new_start + 1)
    for i, c in enumerate(counts):
        target_idx = ((offset + i) >> scale_diff) - new_start
        merged[target_idx] += c
    return new_start, merged

def merge_exp_histograms(
    h1: tuple[int, int, list[int]],
    h2: tuple[int, int, list[int]],
) -> tuple[int, int, list[int]]:
    s1, off1, cnt1 = h1
    s2, off2, cnt2 = h2
    target = min(s1, s2)
    o1, c1 = downscale_buckets(off1, cnt1, s1 - target)
    o2, c2 = downscale_buckets(off2, cnt2, s2 - target)
    if not c1:
        return target, o2, c2
    if not c2:
        return target, o1, c1
    lo = min(o1, o2)
    hi = max(o1 + len(c1) - 1, o2 + len(c2) - 1)
    out = [0] * (hi - lo + 1)
    for i, v in enumerate(c1):
        out[o1 + i - lo] += v
    for i, v in enumerate(c2):
        out[o2 + i - lo] += v
    return target, lo, out
```

