from collections import OrderedDict

class BoundedTailSampler:
    def __init__(self, max_traces: int = 10000, threshold_ms: float = 500.0) -> None:
        self.max_traces = max_traces
        self.threshold_ms = threshold_ms
        self.buffer: OrderedDict[str, tuple[bool, list[dict]]] = OrderedDict()

    def ingest_span(self, trace_id: str, span: dict) -> tuple[str, list[dict]] | None:
        keep = bool(span.get("error")) or float(span.get("duration_ms", 0.0)) >= self.threshold_ms
        evicted = None
        if trace_id in self.buffer:
            prev_keep, spans = self.buffer[trace_id]
            spans.append(span)
            self.buffer[trace_id] = (prev_keep or keep, spans)
        else:
            if len(self.buffer) >= self.max_traces:
                old_tid, (old_keep, old_spans) = self.buffer.popitem(last=False)
                if old_keep:
                    evicted = (old_tid, old_spans)
            self.buffer[trace_id] = (keep, [span])
        return evicted
