**FSST** is magic f0r columnar string vectors because **every individual string decompresses independently** in SIMD registers (`1-byte code -> 8-byte uint64 symbol lookup`) without decompressing surrounding rows! Code `255` (`0xFF`) escapes a single literal byte; codes `0..254` index up t0 `255` frequent `1..8`-byte symbols:

```python
ESCAPE = 0xFF


class FSSTCodec:
    def __init__(self, symbols: list[bytes]) -> None:
        if len(symbols) > 255 or any(not (1 <= len(s) <= 8) for s in symbols):
            raise ValueError("FSST supports up to 255 symbols of 1..8 bytes each")
        self.symbols = list(symbols)
        # Index symbols by first byte, ordered longest-first for greedy matching:
        self.by_first: list[list[tuple[bytes, int]]] = [[] for _ in range(256)]
        for code, sym in enumerate(self.symbols):
            self.by_first[sym[0]].append((sym, code))
        for bucket in self.by_first:
            bucket.sort(key=lambda pair: len(pair[0]), reverse=True)

    def encode(self, raw: bytes) -> bytes:
        out = bytearray()
        pos = 0
        n = len(raw)
        while pos < n:
            b0 = raw[pos]
            matched = False
            for sym, code in self.by_first[b0]:
                slen = len(sym)
                if pos + slen <= n and raw[pos : pos + slen] == sym:
                    out.append(code)
                    pos += slen
                    matched = True
                    break
            if not matched:
                out.append(ESCAPE)
                out.append(b0)
                pos += 1
        return bytes(out)

    def decode(self, compressed: bytes) -> bytes:
        out = bytearray()
        pos = 0
        n = len(compressed)
        syms = self.symbols
        while pos < n:
            code = compressed[pos]
            if code == ESCAPE:
                out.append(compressed[pos + 1])
                pos += 2
            else:
                out.extend(syms[code])
                pos += 1
        return bytes(out)
```

