#include <cstddef>
#include <span>
#include <sys/mman.h>
#include <unistd.h>

std::byte* create_mirrored_ring(size_t cap_page_aligned) noexcept {
    int fd = ::memfd_create("mirror_ring", MFD_CLOEXEC);
    if (fd < 0 || ::ftruncate(fd, static_cast<off_t>(cap_page_aligned)) != 0) {
        if (fd >= 0) ::close(fd);
        return nullptr;
    }

    // Reserve 2 * cap contiguous virtual address range first
    void* addr = ::mmap(nullptr, 2 * cap_page_aligned, PROT_NONE,
                        MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (addr == MAP_FAILED) { ::close(fd); return nullptr; }

    auto* base = static_cast<std::byte*>(addr);
    // Map [0, cap) and [cap, 2*cap) to the SAME physical pages of `fd`!
    ::mmap(base, cap_page_aligned, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_FIXED, fd, 0);
    ::mmap(base + cap_page_aligned, cap_page_aligned, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_FIXED, fd, 0);
    ::close(fd);
    return base;
}
