public final class FlatIntervalStabber {
    private final long[] starts;
    private final long[] prefixMaxEnd;

    public FlatIntervalStabber(long[][] intervals) {
        long[][] copy = intervals.clone();
        Arrays.sort(copy, (a, b) -> Long.compare(a[0], b[0]));
        int n = copy.length;
        this.starts = new long[n];
        this.prefixMaxEnd = new long[n];
        long runMax = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            starts[i] = copy[i][0];
            runMax = Math.max(runMax, copy[i][1]);
            prefixMaxEnd[i] = runMax;
        }
    }

    public boolean overlapsPoint(long t) {
        int lo = 0, hi = starts.length - 1, rightmost = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (starts[mid] <= t) { rightmost = mid; lo = mid + 1; }
