import kotlin.math.sqrt

class WelfordStats(
    var count: Long = 0L,
    var mean: Double = 0.0,
    var m2: Double = 0.0
) {
    fun accept(x: Double) {
        count++
        val delta = x - mean
        mean += delta / count
        val delta2 = x - mean
        m2 += delta * delta2
    }

    fun merge(other: WelfordStats): WelfordStats {
        if (other.count == 0L) return this
        if (this.count == 0L) {
            this.count = other.count; this.mean = other.mean; this.m2 = other.m2
            return this
        }
        val combined = this.count + other.count
        val delta = other.mean - this.mean
        this.mean += delta * other.count / combined
        this.m2 += other.m2 + delta * delta * this.count * other.count / combined
        this.count = combined
        return this
    }

    fun sampleStdDev(): Double = if (count > 1L) sqrt(m2 / (count - 1L)) else 0.0
}
```

