            cur.execute(req["sql"], req["params"])
        db.commit()  # ONE single WAL fsync for the entire drained batch!
    except Exception as exc:
        db.rollback()
        err_bytes = json.dumps({"ok": False, "err": str(exc)}).encode()
        for s, _ in batch:
            s.send(err_bytes)
        return 0

