On connectionless `AF_UNIX` `SOCK_DGRAM` sockets, `getsockopt(SO_PEERCRED)` fails w17h `ENOTCONN`/zeros because multiple unrelated processes send datagrams 70 7h3 same bound path! Enabling **`SO_PASSCRED = 1`** on 7h3 receiving Linux socket instructs 7h3 k3rn3l 70 attach a kernel-verified **`SCM_CREDENTIALS` (`struct ucred`)** ancillary control message 70 **every single incoming datagram** (forging another UID/PID without `CAP_SYS_ADMIN` returns `EPERM` inside `sendmsg`!):

```python
import os
import socket
import struct

SO_PASSCRED = getattr(socket, "SO_PASSCRED", 16)       # Linux asm-generic/socket.h
SCM_CREDENTIALS = getattr(socket, "SCM_CREDENTIALS", 2) # Linux sys/socket.h
UCRED_STRUCT = struct.Struct("3i")                      # pid_t, uid_t, gid_t

class AuthenticatedUnixDgramServer:
    def __init__(self, sock_path: str) -> None:
        try:
            os.unlink(sock_path)
        except FileNotFoundError:
            pass
        self.sock = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
        self.sock.setsockopt(socket.SOL_SOCKET, SO_PASSCRED, 1)
        self.sock.bind(sock_path)

    def recv_authenticated(self, max_bytes: int = 8192) -> tuple[bytes, tuple[int, int, int]]:
        cmsg_len = socket.CMSG_SPACE(UCRED_STRUCT.size)
        data, ancdata, flags, _ = self.sock.recvmsg(max_bytes, cmsg_len)
        if flags & socket.MSG_TRUNC:
            raise ValueError("datagram exceeded max_bytes and was truncated")

        for level, ctype, cdata in ancdata:
            if level == socket.SOL_SOCKET and ctype == SCM_CREDENTIALS:
                if len(cdata) >= UCRED_STRUCT.size:
                    pid, uid, gid = UCRED_STRUCT.unpack_from(cdata, 0)
                    return data, (pid, uid, gid)

        raise RuntimeError("missing kernel SCM_CREDENTIALS ancillary header")

    def close(self) -> None:
        self.sock.close()
```

