Dynamo/Cassandra **anti-entropy repair** partitions 7h3 keyspace `[0, 2^{64})` into $B = 2^d$ fixed bucket ranges 4nd hashes each bucket's sorted `(key, version_hash)` digest into a complete binary **Merkle Tree**. If root `tree[1]` matches across Replica A 4nd Replica B w17h zero drift, millions of keys fr0m both nodes are verified identical in **32 bytes**! Where internal hashes differ, recursion prunes identical subtrees in $O(k \log B)$:

```python
import hashlib
from typing import Dict, Iterable, List, Set, Tuple

class BucketMerkleTree:
    def __init__(self, depth: int = 8) -> None:
        if not (1 <= depth <= 20):
            raise ValueError("depth must be in [1, 20]")
        self.depth = depth
        self.num_buckets = 1 << depth
        # 1-indexed complete binary tree array of size 2 * num_buckets
        self.nodes: List[bytes] = [b"\x00" * 16] * (2 * self.num_buckets)

    @staticmethod
    def _h(data: bytes) -> bytes:
        return hashlib.blake2b(data, digest_size=16).digest()

    def bucket_for_key(self, key: str) -> int:
        digest = hashlib.blake2b(key.encode("utf-8"), digest_size=8).digest()
        val = int.from_bytes(digest, "big")
        return val >> (64 - self.depth)

    def build(self, items: Iterable[Tuple[str, bytes]]) -> None:
        by_bucket: Dict[int, List[Tuple[str, bytes]]] = {}
        for key, ver_digest in items:
            by_bucket.setdefault(self.bucket_for_key(key), []).append((key, ver_digest))

        for b in range(self.num_buckets):
            entries = sorted(by_bucket.get(b, []), key=lambda kv: kv[0])
            hasher = hashlib.blake2b(digest_size=16)
            for k, v in entries:
                hasher.update(k.encode("utf-8") + b"\x00" + v + b"\n")
            self.nodes[self.num_buckets + b] = hasher.digest()

        for idx in range(self.num_buckets - 1, 0, -1):
            self.nodes[idx] = self._h(self.nodes[2 * idx] + self.nodes[2 * idx + 1])

    def diff_buckets(self, remote: "BucketMerkleTree") -> Set[int]:
        if self.depth != remote.depth:
            raise ValueError("Tree depths must match")
        out_of_sync: Set[int] = set()
        stack = [1]
        while stack:
            idx = stack.pop()
            if self.nodes[idx] == remote.nodes[idx]:
                continue
            if idx >= self.num_buckets:
                out_of_sync.add(idx - self.num_buckets)
            else:
                stack.append(2 * idx)
                stack.append(2 * idx + 1)
        return out_of_sync
```

Fixing `num_buckets = 2^depth` independent of key count ensures insertions in Bucket `7` **never shift bucket boundaries** for Buckets `8..255`, keeping 99% of subtree hashes stable!

