export class ReservoirSampler {
  readonly buf: Float32Array;
  private seen = 0;

  constructor(private readonly k: number) {
    this.buf = new Float32Array(k);
  }

  observe(value: number): void {
    const i = this.seen++;
    if (i < this.k) {
      this.buf[i] = value;
      return;
    }
    const j = Math.floor(Math.random() * (i + 1));
    if (j < this.k) {
