type Piece = { src: 'orig' | 'add'; start: number; len: number };

export class PieceTable {
  private addBuf = '';
  private pieces: Piece[];

  constructor(private readonly origBuf: string) {
    this.pieces = origBuf.length ? [{ src: 'orig', start: 0, len: origBuf.length }] : [];
  }

  insert(offset: number, text: number | string): void {
    const str = String(text);
    if (!str) return;
    const addStart = this.addBuf.length;
    this.addBuf += str;
    const inserted: Piece = { src: 'add', start: addStart, len: str.length };

    let pos = 0;
    for (let i = 0; i < this.pieces.length; i++) {
      const p = this.pieces[i];
      if (offset <= pos + p.len) {
        const rel = offset - pos;
        const next: Piece[] = [];
        if (rel > 0) next.push({ src: p.src, start: p.start, len: rel });
        next.push(inserted);
        if (rel < p.len) next.push({ src: p.src, start: p.start + rel, len: p.len - rel });
        this.pieces.splice(i, 1, ...next);
        return;
      }
      pos += p.len;
    }
    this.pieces.push(inserted);
  }
}
