import re
from dataclasses import dataclass

@dataclass(frozen=True)
class LabelMatcher:
    name: str
    op: str
    value: str

    def __post_init__(self) -> None:
        if self.op not in ("=", "!=", "=~", "!~"):
            raise ValueError(f"unsupported op: {self.op}")
        object.__setattr__(
            self,
            "_rx",
            re.compile(f"^(?:{self.value})$") if "~" in self.op else None,
