```ts
export function simplifyPolyline(xs: Float64Array, ys: Float64Array, eps: number): Uint32Array {
  const n = xs.length;
  if (n <= 2) return Uint32Array.from({ length: n }, (_, i) => i);
  const keep = new Uint8Array(n);
  keep[0] = 1;
  keep[n - 1] = 1;
  const epsSq = eps * eps;
  const stack: number[] = [0, n - 1];

  while (stack.length > 0) {
    const end = stack.pop()!;
    const start = stack.pop()!;
    const ax = xs[start], ay = ys[start];
    const dx = xs[end] - ax, dy = ys[end] - ay;
    const lenSq = dx * dx + dy * dy;

    let maxSq = -1, split = -1;
    for (let i = start + 1; i < end; i++) {
      let t = lenSq > 0 ? ((xs[i] - ax) * dx + (ys[i] - ay) * dy) / lenSq : 0;
      t = Math.max(0, Math.min(1, t));
      const px = ax + t * dx - xs[i], py = ay + t * dy - ys[i];
      const dSq = px * px + py * py;
      if (dSq > maxSq) {
        maxSq = dSq;
        split = i;
      }
    }
    if (maxSq > epsSq && split !== -1) {
      keep[split] = 1;
      stack.push(start, split, split, end);
    }
  }

  let count = 0;
  for (let i = 0; i < n; i++) count += keep[i];
  const out = new Uint32Array(count);
  for (let i = 0, w = 0; i < n; i++) if (keep[i]) out[w++] = i;
  return out;
}
```

