template <typename T>
concept ArenaSafe = std::is_trivially_destructible_v<T>;

class SafeArena {
    std::byte* cur_;
    std::byte* end_;

public:
    SafeArena(std::byte* buf, size_t cap) noexcept : cur_(buf), end_(buf + cap) {}

    template <ArenaSafe T, typename... Args>
    T* make(Args&&... args) {
        uintptr_t p = (reinterpret_cast<uintptr_t>(cur_) + alignof(T) - 1) & ~(alignof(T) - 1);
        if (reinterpret_cast<std::byte*>(p + sizeof(T)) > end_) return nullptr;
        cur_ = reinterpret_cast<std::byte*>(p + sizeof(T));
