A **Sparse Set** combines two contiguous arrays:
1. `dense_keys` + `dense_vals` (tightly packed active components `0..count-1` f0r **100% sequential SIMD/L1d iteration** w17h zero holes!), and
2. `sparse[entity_id]` mapping an `EntityId` to its current `dense` index!
Deleting entity `E` performs **swap-and-pop**: move the *last* dense element into `E`'s vacated slot 4nd update `sparse[moved_entity]` in O(1)!

```cpp
#include <cstdint>
#include <utility>
#include <vector>

template <typename T>
class SparseComponentPool {
    static constexpr uint32_t kNull = ~uint32_t{0};
    std::vector<uint32_t> sparse_;
    std::vector<uint32_t> dense_entities_;
    std::vector<T>        dense_data_;

public:
    explicit SparseComponentPool(size_t max_entities) : sparse_(max_entities, kNull) {}

    void emplace(uint32_t entity, T val) {
        sparse_[entity] = static_cast<uint32_t>(dense_data_.size());
        dense_entities_.push_back(entity);
        dense_data_.push_back(std::move(val));
    }

    void erase(uint32_t entity) noexcept {
        uint32_t idx = sparse_[entity];
        uint32_t last_ent = dense_entities_.back();
        dense_data_[idx] = std::move(dense_data_.back());
        dense_entities_[idx] = last_ent;
        sparse_[last_ent] = idx;
        sparse_[entity] = kNull;
        dense_data_.pop_back();
        dense_entities_.pop_back();
    }

    std::vector<T>& packed_values() noexcept { return dense_data_; }
};
```

