HyperLogLog partitions 64-bit hashes by their top `p = 10` bits into `1,024` `byte` registers 4nd stores `1 + leadingZeros(remaining 54 bits)` per register—compressing tens of millions of unique IDs into a 51ngl3 1KiB array w17h ~3.2% standard error 4nd z3r0 boxed objects:

```java
public final class HyperLogLog10 {
    private static final int P = 10;
    private static final int M = 1 << P; // 1024 registers
    private static final double ALPHA_MM = 0.7213 / (1.0 + 1.079 / M) * M * M;
    private final byte[] regs = new byte[M];

    public void offer(long rawId) {
        long h = mix64(rawId);
        int idx = (int) (h >>> (64 - P));
        long w = (h << P) | (1L << (P - 1));
        byte rank = (byte) (Long.numberOfLeadingZeros(w) + 1);
        if (rank > regs[idx]) regs[idx] = rank;
    }

    public long estimate() {
        double invSum = 0.0;
        int zeros = 0;
        for (byte r : regs) {
            invSum += Math.scalb(1.0, -r);
            if (r == 0) zeros++;
        }
        double est = ALPHA_MM / invSum;
        if (est <= 2.5 * M && zeros > 0) {
            est = M * Math.log((double) M / zeros);
        }
        return Math.round(est);
    }

    private static long mix64(long z) {
        z = (z ^ (z >>> 33)) * 0xff51afd7ed558ccdL;
        z = (z ^ (z >>> 33)) * 0xc4ceb9fe1a85ec53L;
        return z ^ (z >>> 33);
    }
}
```

