```kotlin
import java.util.concurrent.atomic.AtomicLongArray

class RollingWindowCounter(private val windowSeconds: Int = 60) {
    private val stamps = AtomicLongArray(windowSeconds)
    private val counts = AtomicLongArray(windowSeconds)

    fun increment(nowEpochSec: Long) {
        val idx = (nowEpochSec % windowSeconds).toInt()
        while (true) {
            val prevStamp = stamps.get(idx)
            if (prevStamp == nowEpochSec) {
                counts.incrementAndGet(idx)
                return
            } else if (prevStamp < nowEpochSec) {
                if (stamps.compareAndSet(idx, prevStamp, nowEpochSec)) {
                    counts.set(idx, 1L)
                    return
                }
            } else {
                return // clock skew older than slot
            }
        }
    }

    fun sumTrailing(nowEpochSec: Long): Long {
        val cutoff = nowEpochSec - windowSeconds
        var total = 0L
        for (i in 0 until windowSeconds) {
            val c = counts.get(i)
            val s = stamps.get(i)
            if (s > cutoff && s <= nowEpochSec) total += c
        }
        return total
    }
}
```

