```python
import heapq

class DeadmanDetector:
    def __init__(self, stale_after_sec: float = 60.0) -> None:
        self.stale_after = stale_after_sec
        self.latest: dict[str, float] = {}
        self.heap: list[tuple[float, str]] = []

    def heartbeat(self, target_id: str, now_sec: float) -> None:
        if now_sec >= self.latest.get(target_id, -1.0):
            self.latest[target_id] = now_sec
            heapq.heappush(self.heap, (now_sec, target_id))

    def pop_stale(self, now_sec: float) -> list[str]:
        cutoff = now_sec - self.stale_after
        dead: list[str] = []
        while self.heap and self.heap[0][0] <= cutoff:
            ts, tid = heapq.heappop(self.heap)
            if self.latest.get(tid) == ts:
                del self.latest[tid]
                dead.append(tid)
        return dead
```

