```python
class DynamicMaxSegTree:
    def __init__(self, universe_end: int = 10**12) -> None:
        self.u_end = universe_end
        # Parallel slot arrays: node 0 = root covering [0, u_end)
        self.left: list[int] = [-1]
        self.right: list[int] = [-1]
        self.mx: list[int] = [0]
        self.lazy: list[int] = [0]

    def _new_node(self) -> int:
        idx = len(self.mx)
        self.left.append(-1)
        self.right.append(-1)
        self.mx.append(0)
        self.lazy.append(0)
        return idx

    def _push(self, v: int) -> None:
        if self.left[v] == -1:
            self.left[v] = self._new_node()
        if self.right[v] == -1:
            self.right[v] = self._new_node()
        tag = self.lazy[v]
        if tag != 0:
            lc, rc = self.left[v], self.right[v]
            self.mx[lc] += tag
            self.lazy[lc] += tag
            self.mx[rc] += tag
            self.lazy[rc] += tag
            self.lazy[v] = 0

    def range_add(self, ql: int, qr: int, delta: int) -> None:
        if ql < qr:
            self._add(0, 0, self.u_end, ql, qr, delta)

    def _add(self, v: int, tl: int, tr: int, ql: int, qr: int, delta: int) -> None:
        if qr <= tl or tr <= ql:
            return
        if ql <= tl and tr <= qr:
            self.mx[v] += delta
            self.lazy[v] += delta
            return
        self._push(v)
        mid = (tl + tr) >> 1
        self._add(self.left[v], tl, mid, ql, qr, delta)
        self._add(self.right[v], mid, tr, ql, qr, delta)
        self.mx[v] = max(self.mx[self.left[v]], self.mx[self.right[v]])

    def range_max(self, ql: int, qr: int) -> int:
        if ql >= qr:
            return 0
        return self._query(0, 0, self.u_end, ql, qr)

    def _query(self, v: int, tl: int, tr: int, ql: int, qr: int) -> int:
        if v == -1 or qr <= tl or tr <= ql:
            return -(10**18)
        if ql <= tl and tr <= qr:
            return self.mx[v]
        if self.lazy[v] == 0 and self.left[v] == -1 and self.right[v] == -1:
            return self.mx[v]
        self._push(v)
        mid = (tl + tr) >> 1
        return max(
            self._query(self.left[v], tl, mid, ql, qr),
            self._query(self.right[v], mid, tr, ql, qr),
        )
```

