```ts
export function routeOrthogonal(
  blocked: Uint8Array,
  cols: number,
  rows: number,
  sx: number,
  sy: number,
  gx: number,
  gy: number,
): number[] {
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const gScore = new Float32Array(cols * rows * 4).fill(Infinity);
  const parent = new Int32Array(cols * rows * 4).fill(-1);
  // [f, state] min-queue (state = (cell * 4) + dir)
  const open: [number, number][] = [];
  for (let d = 0; d < 4; d++) {
    const st = (sy * cols + sx) * 4 + d;
    gScore[st] = 0;
    open.push([Math.abs(gx - sx) + Math.abs(gy - sy), st]);
  }
  while (open.length > 0) {
    open.sort((a, b) => b[0] - a[0]);
    const [, cur] = open.pop()!;
    const cell = cur >> 2, dir = cur & 3;
    const cx = cell % cols, cy = (cell / cols) | 0;
    if (cx === gx && cy === gy) {
      const path: number[] = [];
      for (let s = cur; s !== -1; s = parent[s]) path.push(s >> 2);
      return path.reverse();
    }
    for (let nd = 0; nd < 4; nd++) {
      const nx = cx + dirs[nd][0], ny = cy + dirs[nd][1];
      if (nx < 0 || nx >= cols || ny < 0 || ny >= rows) continue;
      const nCell = ny * cols + nx;
      if (blocked[nCell] && !(nx === gx && ny === gy)) continue;
      const nextSt = nCell * 4 + nd;
      const tentative = gScore[cur] + 1 + (nd === dir ? 0 : 0.4);
      if (tentative < gScore[nextSt]) {
        gScore[nextSt] = tentative;
        parent[nextSt] = cur;
        const h = Math.abs(gx - nx) + Math.abs(gy - ny);
        open.push([tentative + h, nextSt]);
      }
    }
  }
  return [];
}
```

