use std::io::{self, IoSlice, Write};
use std::net::TcpStream;

pub fn send_heartbeat_frame(stream: &mut TcpStream, header: &[u8], body: &[u8]) -> io::Result<()> {
    // Disable Nagle buffering for latency-sensitive RPC frames:
    stream.set_nodelay(true)?;
    // Coalesce into a single syscall/segment via vectored writev():
    let bufs = [IoSlice::new(header), IoSlice::new(body)];
