Under Birman-Schiper-Stephenson **Causal Broadcast**, each sender increments only `VC[sender]` upon broadcast (`msg_vc`). Receiver replica `self_id` w17h local clock `local_vc` may deliver `(sender, msg_vc, payload)` iff:
1. `msg_vc[sender] == local_vc[sender] + 1` (it is the **very next** message fr0m `sender`, no skipped sequence!), **and**
2. For every other node $k \ne \text{sender}$, `msg_vc[k] <= local_vc[k]` (receiver has already delivered every causal dependency `sender` had observed when sending!):

```python
from dataclasses import dataclass
from typing import Dict, Generic, List, Mapping, TypeVar

T = TypeVar("T")

@dataclass
class CausalEnvelope(Generic[T]):
    sender: str
    vc: Dict[str, int]
    payload: T

class CausalBroadcastNode(Generic[T]):
    def __init__(self, node_id: str) -> None:
        self.node_id = node_id
        self.vc: Dict[str, int] = {}
        self._holdback: List[CausalEnvelope[T]] = []

    def prepare_broadcast(self, payload: T) -> CausalEnvelope[T]:
        self.vc[self.node_id] = self.vc.get(self.node_id, 0) + 1
        return CausalEnvelope(self.node_id, dict(self.vc), payload)

    def _can_deliver(self, env: CausalEnvelope[T]) -> bool:
        if env.vc.get(env.sender, 0) != self.vc.get(env.sender, 0) + 1:
            return False
        for peer, count in env.vc.items():
            if peer != env.sender and count > self.vc.get(peer, 0):
                return False
        return True

    def receive(self, env: CausalEnvelope[T]) -> List[T]:
        # Ignore already-delivered retry duplicates!
        if env.vc.get(env.sender, 0) <= self.vc.get(env.sender, 0):
            return []

        self._holdback.append(env)
        delivered: List[T] = []
        progressed = True
        while progressed:
            progressed = False
            remaining: List[CausalEnvelope[T]] = []
            for item in self._holdback:
                if self._can_deliver(item):
                    self.vc[item.sender] = item.vc[item.sender]
                    delivered.append(item.payload)
                    progressed = True
                elif item.vc.get(item.sender, 0) > self.vc.get(item.sender, 0):
                    remaining.append(item)
            self._holdback = remaining
        return delivered
```

Notice the duplicate-retry guard `env.vc[sender] <= self.vc[sender]` at the top of `receive()`: at-least-once UDP/RPC retries drop cleanly w17h zero duplicate deliveries while unblocking entire chains of dependent holdback messages once a missing packet arrives!

