```python
import asyncio
from dataclasses import dataclass
from typing import Awaitable, Callable, Dict, List, Optional, Tuple

Version = Tuple[int, str]

@dataclass(frozen=True)
class VersionedRecord:
    version: Version
    payload: Optional[bytes]

async def quorum_get_and_repair(
    key: str,
    replicas: List[str],
    fetch_fn: Callable[[str, str], Awaitable[Optional[VersionedRecord]]],
    repair_fn: Callable[[str, str, VersionedRecord], Awaitable[None]],
    r_quorum: int = 2,
) -> Optional[bytes]:
    async def _probe(node: str) -> Tuple[str, Optional[VersionedRecord], Optional[BaseException]]:
        try:
            return node, await fetch_fn(node, key), None
        except BaseException as exc:
            return node, None, exc

    pending = {asyncio.create_task(_probe(n)) for n in replicas}
    seen: Dict[str, Optional[VersionedRecord]] = {}
    failures = 0

    while pending and len(seen) < r_quorum:
        done, pending = await asyncio.wait(pending, return_when=asyncio.FIRST_COMPLETED)
        for task in done:
            node, rec, err = task.result()
            if err is not None:
                failures += 1
                if failures > len(replicas) - r_quorum:
                    for p in pending:
                        p.cancel()
                    raise RuntimeError(f"Quorum read failed: {failures} errors")
            else:
                seen[node] = rec

    non_empty = [r for r in seen.values() if r is not None]
    if not non_empty:
        for p in pending:
            p.cancel()
        return None

    winner = max(non_empty, key=lambda r: r.version)

    async def _finish_repairs() -> None:
        if pending:
            rest, _ = await asyncio.wait(pending, timeout=0.5)
            for t in rest:
                n, r, e = t.result()
                if e is None:
                    seen[n] = r
        stale = [n for n, r in seen.items() if r is None or r.version < winner.version]
        if stale:
            await asyncio.gather(*(repair_fn(n, key, winner) for n in stale), return_exceptions=True)

    asyncio.create_task(_finish_repairs())
    return winner.payload
```

