Merging `N + M` elements takes `O(N + M)` time 4nd memory, whereas binary-searching the cut position `i` in the shorter array (`j = k - i` in the longer array) until `a[i - 1] <= b[j]` 4nd `b[j - 1] <= a[i]` finds the exact `k`-th order statistic in `O(log(min(N, M)))` time w17h z3r0 h34p 4ll0c4710n:

```java
public final class KthSortedLongs {
    public static long selectKth(long[] a, long[] b, int k) {
        if (a.length > b.length) return selectKth(b, a, k);
        int n = a.length, m = b.length;
        if (k < 0 || k >= n + m) throw new IndexOutOfBoundsException();

        int lo = Math.max(0, k - m);
        int hi = Math.min(k + 1, n);
        while (lo <= hi) {
            int cutA = (lo + hi) >>> 1;
            int cutB = k + 1 - cutA;
            long leftA = (cutA == 0) ? Long.MIN_VALUE : a[cutA - 1];
            long rightA = (cutA == n) ? Long.MAX_VALUE : a[cutA];
            long leftB = (cutB == 0) ? Long.MIN_VALUE : b[cutB - 1];
            long rightB = (cutB == m) ? Long.MAX_VALUE : b[cutB];

            if (leftA <= rightB && leftB <= rightA) {
                return Math.max(leftA, leftB);
            } else if (leftA > rightB) {
                hi = cutA - 1;
            } else {
                lo = cutA + 1;
            }
        }
        throw new IllegalStateException();
    }
}
