```python
import ssl
import socket

class EdgeTriggeredTlsSession:
    def __init__(self, ctx: ssl.SSLContext, server_side: bool = True, server_hostname: str | None = None) -> None:
        self._in_bio = ssl.MemoryBIO()
        self._out_bio = ssl.MemoryBIO()
        self._ssl = ctx.wrap_bio(
            self._in_bio,
            self._out_bio,
            server_side=server_side,
            server_hostname=server_hostname,
        )
        self._handshake_done = False
        self._tx_pending = bytearray()

    def _pump_handshake(self) -> None:
        if self._handshake_done:
            return
        try:
            self._ssl.do_handshake()
            self._handshake_done = True
        except (ssl.SSLWantReadError, ssl.SSLWantWriteError):
            pass

    def _pull_outbound_ciphertext(self) -> None:
        chunk = self._out_bio.read()
        if chunk:
            self._tx_pending.extend(chunk)

    def on_socket_readable(self, sock: socket.socket) -> tuple[bytes, bool]:
        """Drain kernel socket + SSLObject completely; return (plaintext, peer_eof)."""
        eof = False
        while True:
            try:
                cipher = sock.recv(65536)
            except BlockingIOError:
                break
            if not cipher:
                self._in_bio.write_eof()
                eof = True
                break
            self._in_bio.write(cipher)

        self._pump_handshake()
        plaintext = bytearray()
        if self._handshake_done:
            while True:
                try:
                    pt = self._ssl.read(65536)
                    if not pt:
                        eof = True
                        break
                    plaintext.extend(pt)
                except (ssl.SSLWantReadError, ssl.SSLWantWriteError):
                    break

        self._pull_outbound_ciphertext()
        self.flush_ciphertext(sock)
        return bytes(plaintext), eof

    def send_plaintext(self, sock: socket.socket, data: bytes) -> bool:
        mv = memoryview(data)
        offset = 0
        while offset < len(mv):
            try:
                offset += self._ssl.write(mv[offset:])
            except (ssl.SSLWantReadError, ssl.SSLWantWriteError):
                break
        self._pull_outbound_ciphertext()
        return self.flush_ciphertext(sock) and offset == len(mv)

    def flush_ciphertext(self, sock: socket.socket) -> bool:
        while self._tx_pending:
            try:
                n = sock.send(self._tx_pending)
            except BlockingIOError:
                return False
            del self._tx_pending[:n]
        return True
```

