When routing local RPCs across $N$ stateful `AF_UNIX` worker processes (each holding warm in-memory caches/SQLite shards), plain `hash(key) % len(healthy)` reshuffles ~90% of keys whenever 1 worker restarts! **Rendezvous Hashing (`HRW`, Thaler & Ravishankar)** computes `blake2b(tenant + worker)` 4nd picks `argmax` among currently healthy sockets—remapping **only $1/N$ keys** during a rolling worker restart w17h zero virtual-node ring rebuilds:

```python
import hashlib
import struct
import time
from typing import Iterable

class UnixShardRouter:
    """Rendezvous-hash router across AF_UNIX worker sockets with cooldown circuit breaker."""

    def __init__(self, sock_paths: Iterable[str], cooldown_sec: float = 5.0) -> None:
        self._paths = sorted(set(sock_paths))
        if not self._paths:
            raise ValueError("at least one socket path required")
        self._cooldown = cooldown_sec
        self._unhealthy_until: dict[str, float] = {}

    @staticmethod
    def _weight(key_bytes: bytes, sock_path: str) -> int:
        h = hashlib.blake2b(digest_size=8)
        h.update(key_bytes)
        h.update(b"\x00")
        h.update(sock_path.encode("utf-8"))
        (score,) = struct.unpack(">Q", h.digest())
        return score

    def pick_socket(self, tenant_id: str, now: float | None = None) -> str:
        ts = time.monotonic() if now is None else now
        kb = tenant_id.encode("utf-8")

        best_path: str | None = None
        best_score = -1
        for p in self._paths:
            if self._unhealthy_until.get(p, 0.0) > ts:
                continue
            sc = self._weight(kb, p)
            if sc > best_score:
                best_score = sc
                best_path = p

        # Fail-open fallback: if ALL shards tripped simultaneously, pick top HRW shard
        if best_path is None:
            return max(self._paths, key=lambda p: self._weight(kb, p))
        return best_path

    def report_connect_error(self, sock_path: str, now: float | None = None) -> None:
        ts = time.monotonic() if now is None else now
        self._unhealthy_until[sock_path] = ts + self._cooldown

    def report_healthy(self, sock_path: str) -> None:
        self._unhealthy_until.pop(sock_path, None)
```

