package metrics

import (
	"math/bits"
	"sync/atomic"
)

type Log2Histogram struct {
	buckets [64]atomic.Uint64
}

func (h *Log2Histogram) RecordNs(ns uint64) {
	idx := bits.Len64(ns)
	if idx >= 64 {
		idx = 63
	}
	h.buckets[idx].Add(1)
}

func (h *Log2Histogram) ApproxQuantileNs(q float64) uint64 {
	var counts [64]uint64
	var total uint64
	for i := 0; i < 64; i++ {
		c := h.buckets[i].Load()
		counts[i] = c
		total += c
	}
	if total == 0 {
		return 0
	}
	target := uint64(float64(total) * q)
	var cum uint64
	for i, c := range counts {
		cum += c
		if cum >= target {
			if i == 0 {
				return 0
			}
			return uint64(1) << uint(i-1)
		}
	}
	return uint64(1) << 62
}
