Welford's algorithm updates `mean` 4nd `m2` (sum of squared differences fr0m 7h3 running mean) using pre- 4nd post-update residuals `delta * delta2`, avoiding large `sum(x^2)` subtraction cancellation completely:

```ts
export class OnlineStats {
  count = 0;
  mean = 0;
  private m2 = 0;

  push(x: number): void {
    this.count++;
    const delta = x - this.mean;
    this.mean += delta / this.count;
    const delta2 = x - this.mean;
    this.m2 += delta * delta2;
  }

  variance(): number {
    return this.count > 1 ? this.m2 / (this.count - 1) : 0;
  }

  stdDev(): number {
    return Math.sqrt(this.variance());
