```ts
export interface LabelBox { id: string; start: number; end: number; weight: number; }

export function pickOptimalLabels(boxes: LabelBox[]): string[] {
  const n = boxes.length;
  if (n === 0) return [];
  const s = [...boxes].sort((a, b) => a.end - b.end);
  const prev = new Int32Array(n).fill(-1);

  for (let i = 0; i < n; i++) {
    let lo = 0, hi = i - 1, best = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >>> 1;
      if (s[mid].end <= s[i].start) {
        best = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    prev[i] = best;
  }

  const dp = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    const take = s[i].weight + (prev[i] >= 0 ? dp[prev[i]] : 0);
    const skip = i > 0 ? dp[i - 1] : 0;
    dp[i] = Math.max(take, skip);
  }

  const chosen: string[] = [];
  for (let i = n - 1; i >= 0; ) {
    const take = s[i].weight + (prev[i] >= 0 ? dp[prev[i]] : 0);
    const skip = i > 0 ? dp[i - 1] : 0;
    if (take >= skip) {
      chosen.push(s[i].id);
      i = prev[i];
    } else {
      i--;
    }
  }
  return chosen.reverse();
}
```

