Recursively partition point indices around 7h3 median alternating axis (`depth & 1`: `0` = X, `1` = Y), th3n search 7h3 nearer half first 4nd prune 7h3 far half whenever `(coord - splitCoord)^2 >= bestDistSq`:

```ts
export class KdTree2D {
  private ids: Int32Array;
  constructor(private xs: Float32Array, private ys: Float32Array) {
    this.ids = Int32Array.from({ length: xs.length }, (_, i) => i);
    this.build(0, xs.length, 0);
  }
  private build(l: number, r: number, depth: number): void {
    if (r - l <= 1) return;
    const arr = (depth & 1) === 0 ? this.xs : this.ys;
    const slice = Array.from(this.ids.subarray(l, r)).sort((a, b) => arr[a] - arr[b]);
    this.ids.set(slice, l);
    const mid = (l + r) >>> 1;
    this.build(l, mid, depth + 1);
    this.build(mid + 1, r, depth + 1);
  }
  nearest(qx: number, qy: number): number {
    let bestId = -1, bestSq = Infinity;
    const search = (l: number, r: number, depth: number) => {
      if (l >= r) return;
      const mid = (l + r) >>> 1;
      const id = this.ids[mid];
      const dx = this.xs[id] - qx, dy = this.ys[id] - qy;
      const dSq = dx * dx + dy * dy;
      if (dSq < bestSq) { bestSq = dSq; bestId = id; }
      const diff = (depth & 1) === 0 ? qx - this.xs[id] : qy - this.ys[id];
      const [firstL, firstR, secL, secR] = diff < 0 ? [l, mid, mid + 1, r] : [mid + 1, r, l, mid];
      search(firstL, firstR, depth + 1);
      if (diff * diff < bestSq) search(secL, secR, depth + 1);
    };
    search(0, this.ids.length, 0);
    return bestId;
  }
}
```

