```ts
export function createBatchCoalescer<T>(
  onFlush: (batch: T[]) => void,
  debounceMs = 300,
  maxWaitMs = 1500,
) {
  let queue: T[] = [];
  let idleTimer: number | null = null;
  let maxTimer: number | null = null;

  const flush = () => {
    if (idleTimer !== null) { clearTimeout(idleTimer); idleTimer = null; }
    if (maxTimer !== null) { clearTimeout(maxTimer); maxTimer = null; }
    if (queue.length === 0) return;
    const items = queue;
    queue = [];
    onFlush(items);
  };

  return {
    push(item: T) {
      queue.push(item);
      if (idleTimer !== null) clearTimeout(idleTimer);
      idleTimer = window.setTimeout(flush, debounceMs);
      if (maxTimer === null) {
        maxTimer = window.setTimeout(flush, maxWaitMs);
      }
    },
    flush,
  };
}
```

