import java.util.Arrays;

public final class UnsignedRadixSort {
    public static void sortNonNegative(long[] a) {
        int n = a.length;
        if (n <= 1) return;
        long[] aux = new long[n];
        int[] count = new int[256];
        long[] src = a, dst = aux;

        for (int shift = 0; shift < 64; shift += 8) {
            Arrays.fill(count, 0);
            boolean anyNonZero = false;
            for (int i = 0; i < n; i++) {
                int b = (int) ((src[i] >>> shift) & 0xFFL);
                count[b]++;
                if ((src[i] >>> shift) != 0L) anyNonZero = true;
            }
            if (!anyNonZero) break;
            int sum = 0;
            for (int r = 0; r < 256; r++) {
                int c = count[r];
                count[r] = sum;
                sum += c;
            }
            for (int i = 0; i < n; i++) {
                long v = src[i];
                int b = (int) ((v >>> shift) & 0xFFL);
                dst[count[b]++] = v;
