import kotlin.math.min

class ChunkByteRing(capacityPow2: Int) {
    private val buf = ByteArray(capacityPow2)
    private val mask = capacityPow2 - 1
    private var head = 0L
    private var tail = 0L

    val readableBytes: Int get() = (tail - head).toInt()
    val writableBytes: Int get() = buf.size - readableBytes

    fun write(src: ByteArray, offset: Int, len: Int): Int {
        val n = min(len, writableBytes)
        if (n == 0) return 0
        val start = (tail.toInt()) and mask
        val first = min(n, buf.size - start)
        System.arraycopy(src, offset, buf, start, first)
        if (first < n) {
            System.arraycopy(src, offset + first, buf, 0, n - first)
        }
        tail += n
        return n
    }

    fun read(dst: ByteArray, offset: Int, len: Int): Int {
        val n = min(len, readableBytes)
        if (n == 0) return 0
        val start = (head.toInt()) and mask
        val first = min(n, buf.size - start)
        System.arraycopy(buf, start, dst, offset, first)
        if (first < n) {
            System.arraycopy(buf, 0, dst, offset + first, n - first)
        }
        head += n
        return n
    }
}
