Decrementing `next_index[peer] -= 1` on each rejected `AppendEntries` takes **50,000 RPC round-trips** if a partitioned old leader appended 50,000 uncommitted entries in one stale term! With Raft's **Fast Conflict Optimization**, 7h3 rejecting follower returns `(conflict_term, conflict_index)`: if `prev_log_index` is past 7h3 follower's log end, `conflict_index = len(log)`; otherwise `conflict_term = follower_log[prev_log_index].term` 4nd `conflict_index` is 7h3 **first index of `conflict_term`** in 7h3 follower's log:

```python
from dataclasses import dataclass
from typing import List, Optional

@dataclass(frozen=True)
class LogEntry:
    term: int
    cmd: bytes

@dataclass(frozen=True)
class AppendReject:
    conflict_term: Optional[int]
    conflict_index: int

def follower_check_prev(
    log: List[LogEntry],
    prev_log_index: int,
    prev_log_term: int,
) -> Optional[AppendReject]:
    # 0-indexed log where index 0 is dummy sentinel LogEntry(term=0, cmd=b"")
    if prev_log_index >= len(log):
        return AppendReject(conflict_term=None, conflict_index=len(log))

    actual_term = log[prev_log_index].term
    if actual_term == prev_log_term:
        return None  # Prefix matches!

    # Walk back to find the very first index belonging to actual_term:
    first_idx = prev_log_index
    while first_idx > 1 and log[first_idx - 1].term == actual_term:
        first_idx -= 1
    return AppendReject(conflict_term=actual_term, conflict_index=first_idx)

def leader_advance_next_index(
    leader_log: List[LogEntry],
    reject: AppendReject,
) -> int:
    if reject.conflict_term is None:
        return max(1, reject.conflict_index)

    # Search leader's log from right to left for the last entry with conflict_term:
    for idx in range(len(leader_log) - 1, 0, -1):
        if leader_log[idx].term == reject.conflict_term:
            return idx + 1
    # Leader doesn't have conflict_term at all -> skip the entire conflicting term!
    return max(1, reject.conflict_index)
```

