import math
import random
import time
from typing import List

class PeakEWMABackend:
    def __init__(self, address: str, tau_s: float = 10.0) -> None:
        self.address = address
        self.tau_s = tau_s
        self.ewma_ms = 1.0
        self.in_flight = 0
        self._last_mono = time.monotonic()

    def record_rtt(self, rtt_ms: float, failed: bool = False) -> None:
        now = time.monotonic()
        dt = max(0.0, now - self._last_mono)
        self._last_mono = now
        effective_ms = rtt_ms * 5.0 if failed else max(0.1, rtt_ms)
        # Peak-EWMA: jump immediately on latency spike, decay exponentially when faster
        if effective_ms > self.ewma_ms:
            self.ewma_ms = effective_ms
        else:
            w = 1.0 - math.exp(-dt / self.tau_s)
            self.ewma_ms = (1.0 - w) * self.ewma_ms + w * effective_ms

    def load_cost(self) -> float:
        return self.ewma_ms * (self.in_flight + 1)

class PeakEWMAP2C:
    def __init__(self, backends: List[PeakEWMABackend]) -> None:
        if not backends:
            raise ValueError("backends must be non-empty")
        self.backends = backends
        self._rng = random.SystemRandom()

    def pick(self) -> PeakEWMABackend:
        if len(self.backends) == 1:
            return self.backends[0]
        a, b = self._rng.sample(self.backends, 2)
        return a if a.load_cost() <= b.load_cost() else b
