#include <algorithm>
#include <array>
#include <cstdint>

struct Top16Tracker {
    struct Entry { uint32_t vol; uint32_t sym_id; };
    alignas(64) std::array<Entry, 16> heap_{}; // Min-heap by vol: heap_[0] is 16th largest!

    void observe(uint32_t sym_id, uint32_t new_vol) noexcept {
        // Fast path (~99.8% of ticks): 1 comparison against L1d-pinned heap_[0].vol!
        if (new_vol <= heap_[0].vol) return;

        // Check if sym_id is already inside the 16-element L1-resident array
        for (auto& e : heap_) {
            if (e.sym_id == sym_id) {
                e.vol = new_vol;
                std::make_heap(heap_.begin(), heap_.end(),
                               [](const Entry& a, const Entry& b) { return a.vol > b.vol; });
                return;
            }
        }
        // Replace minimum element and sift down inside 2 cachelines
        std::pop_heap(heap_.begin(), heap_.end(),
                      [](const Entry& a, const Entry& b) { return a.vol > b.vol; });
        heap_.back() = {new_vol, sym_id};
        std::push_heap(heap_.begin(), heap_.end(),
                       [](const Entry& a, const Entry& b) { return a.vol > b.vol; });
    }
};
```

