```cpp
#include <bit>
#include <cstdint>
#include <emmintrin.h>

struct alignas(16) CtrlGroup16 {
    static constexpr int8_t kEmpty = -128; // 0x80
    int8_t ctrl[16];

    // Returns 16-bit mask of slots matching 7-bit h2 fingerprint (0..127)
    uint32_t match_h2(int8_t h2) const noexcept {
        __m128i grp = _mm_load_si128(reinterpret_cast<const __m128i*>(ctrl));
        __m128i needle = _mm_set1_epi8(h2);
        return static_cast<uint32_t>(_mm_movemask_epi8(_mm_cmpeq_epi8(grp, needle)));
