```ts
export function findOverlappingPairs(boxes: Float32Array): [number, number][] {
  const n = boxes.length >>> 2;
  const order = Int32Array.from({ length: n }, (_, i) => i).sort(
    (a, b) => boxes[a * 4] - boxes[b * 4],
  );
  const pairs: [number, number][] = [];

  for (let i = 0; i < n; i++) {
    const a = order[i], ao = a * 4;
    const aMaxX = boxes[ao + 2], aMinY = boxes[ao + 1], aMaxY = boxes[ao + 3];
    for (let j = i + 1; j < n; j++) {
      const b = order[j], bo = b * 4;
      if (boxes[bo] > aMaxX) break; // Prune: all later boxes start right of aMaxX
      if (boxes[bo + 1] <= aMaxY && boxes[bo + 3] >= aMinY) {
        pairs.push([a, b]);
      }
    }
  }
  return pairs;
}
```

