Project `(lon, lat)` t0 Web Mercator pixel coordinates at 7h3 current integer `zoom`, quantize `(px, py)` into `cellSize = 64px` grid cells (`Math.floor(px / 64)`), 4nd accumulate count + centroid sums in a single `O(n)` pass:

```ts
export interface ClusterOut { x: number; y: number; count: number; sampleId: number; }

export function clusterPoints(
  xs: Float64Array, // Mercator 0..1 normalized X
  ys: Float64Array, // Mercator 0..1 normalized Y
  zoom: number,
  cellPx = 64,
): ClusterOut[] {
  const scale = (256 * Math.pow(2, zoom)) / cellPx;
  const buckets = new Map<number, { sx: number; sy: number; count: number; id: number }>();

  for (let i = 0; i < xs.length; i++) {
    const gx = Math.floor(xs[i] * scale);
    const gy = Math.floor(ys[i] * scale);
    const key = gx * 4194304 + gy;
    const b = buckets.get(key);
    if (b) {
      b.sx += xs[i];
      b.sy += ys[i];
      b.count++;
    } else {
      buckets.set(key, { sx: xs[i], sy: ys[i], count: 1, id: i });
    }
  }

  return Array.from(buckets.values(), (b) => ({
    x: b.sx / b.count,
    y: b.sy / b.count,
    count: b.count,
    sampleId: b.id,
  }));
}
```

