const REQUIRED_SEALS: libc::c_int =
    libc::F_SEAL_SHRINK | libc::F_SEAL_GROW | libc::F_SEAL_WRITE;

pub fn verify_immutable_memfd(fd: RawFd) -> io::Result<()> {
