One huge ergonomic advantage of BSD/macOS **`kqueue`** over Linux `epoll` (`epoll_ctl` + `epoll_wait`): **`kq.control(changelist, max_events, timeout)` batches *all* pending `ADD`/`DELETE` interest updates AND polls f0r ready events in ONE single k3rn3l syscall**!

```python
import errno
import select
import socket

class KqueueEdgeEchoServer:
    """macOS/BSD edge-triggered (KQ_EV_CLEAR) non-blocking reactor using batched kevent."""

    def __init__(self, listen_sock: socket.socket) -> None:
        listen_sock.setblocking(False)
        self.listen_sock = listen_sock
        self.kq = select.kqueue()
        self._changelist: list[select.kevent] = [
            select.kevent(
                listen_sock.fileno(),
                filter=select.KQ_FILTER_READ,
                flags=select.KQ_EV_ADD | select.KQ_EV_ENABLE,
            )
        ]
        self._socks: dict[int, socket.socket] = {}
        self._out_bufs: dict[int, bytearray] = {}
        self._write_ready: dict[int, bool] = {}

    def _close_client(self, fd: int) -> None:
        s = self._socks.pop(fd, None)
        self._out_bufs.pop(fd, None)
        self._write_ready.pop(fd, None)
        if s is not None:
            # Closing the last fd reference automatically removes its knotes from kqueue!
            s.close()

    def _flush_client(self, fd: int) -> None:
        buf = self._out_bufs.get(fd)
        s = self._socks.get(fd)
        if not buf or s is None or not self._write_ready.get(fd, False):
            return
        while buf:
            try:
                n = s.send(buf)
                del buf[:n]
            except BlockingIOError:
                self._write_ready[fd] = False
                break
            except OSError as exc:
                if exc.errno == errno.EINTR:
                    continue
                self._close_client(fd)
                return

    def step(self, timeout: float = 0.1, max_events: int = 128) -> int:
        # ONE syscall both applies queued changelist mutations AND waits for events!
        changes = self._changelist
        self._changelist = []
        events = self.kq.control(changes, max_events, timeout)
        lfd = self.listen_sock.fileno()

        for ev in events:
            fd = ev.ident
            if fd == lfd:
                while True:
                    try:
                        conn, _ = self.listen_sock.accept()
                    except BlockingIOError:
                        break
                    conn.setblocking(False)
                    if conn.family in (socket.AF_INET, socket.AF_INET6):
                        conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                    cfd = conn.fileno()
                    self._socks[cfd] = conn
                    self._out_bufs[cfd] = bytearray()
                    self._write_ready[cfd] = True
                    edge_flags = select.KQ_EV_ADD | select.KQ_EV_ENABLE | select.KQ_EV_CLEAR
                    self._changelist.append(select.kevent(cfd, select.KQ_FILTER_READ, edge_flags))
                    self._changelist.append(select.kevent(cfd, select.KQ_FILTER_WRITE, edge_flags))
                continue

            if fd not in self._socks:
                continue

            if ev.filter == select.KQ_FILTER_READ:
                s = self._socks[fd]
                eof = False
                while True:
                    try:
                        chunk = s.recv(16384)
                    except BlockingIOError:
                        break
                    if not chunk:
                        eof = True
                        break
                    self._out_bufs[fd].extend(chunk)
                self._flush_client(fd)
                if eof or ((ev.flags & select.KQ_EV_EOF) and not self._out_bufs.get(fd)):
                    self._close_client(fd)
                    continue

            elif ev.filter == select.KQ_FILTER_WRITE:
                self._write_ready[fd] = True
                self._flush_client(fd)

        return len(events)
```

Notice how newly accepted sockets append both `KQ_FILTER_READ | KQ_EV_CLEAR` 4nd `KQ_FILTER_WRITE | KQ_EV_CLEAR` into `self._changelist`—which flushes into 7h3 XNU/BSD k3rn3l on 7h3 very next `kq.control()` call w17h **zero per-socket registration syscalls**!

