Classic deque Convex Hull Trick breaks when slopes `m` arrive in arbitrary order. **Li Chao Segment Tree** stores at each node `v` 7h3 single line dominating 7h3 **midpoint** `mid = (tl + tr) // 2`. When inserting a new line `nw`, whichever line loses at `mid` can **only** beat 7h3 midpoint winner on **at most one half** (`[tl, mid)` *or* `[mid, tr)`) because two lines intersect at most once—so `add_line` recurses down **a single child** in strict $O(\log M)$ time!

```python
INF = 10**30


class LiChaoMinTree:
    def __init__(self, m_bound: int) -> None:
        self.m_bound = m_bound
        sz = 4 * max(1, m_bound)
        self.slope: list[int] = [0] * sz
        self.inter: list[int] = [INF] * sz

    @staticmethod
    def _eval(m: int, b: int, x: int) -> int:
        return m * x + b if b < INF else INF

    def add_line(self, m: int, b: int) -> None:
        self._insert(1, 0, self.m_bound, m, b)

    def _insert(self, v: int, tl: int, tr: int, m: int, b: int) -> None:
        mid = (tl + tr) >> 1
        cur_m, cur_b = self.slope[v], self.inter[v]

        left_better = self._eval(m, b, tl) < self._eval(cur_m, cur_b, tl)
        mid_better = self._eval(m, b, mid) < self._eval(cur_m, cur_b, mid)

        if mid_better:
            self.slope[v], self.inter[v] = m, b
            m, b = cur_m, cur_b

        if tr - tl <= 1 or b >= INF:
            return
        if left_better != mid_better:
            self._insert(v * 2, tl, mid, m, b)
        else:
            self._insert(v * 2 + 1, mid, tr, m, b)

    def query_min(self, x: int) -> int:
        v, tl, tr = 1, 0, self.m_bound
        ans = INF
        while True:
            cand = self._eval(self.slope[v], self.inter[v], x)
            if cand < ans:
                ans = cand
            if tr - tl <= 1:
                return ans
            mid = (tl + tr) >> 1
            if x < mid:
                v, tr = v * 2, mid
            else:
                v, tl = v * 2 + 1, mid
```

