```python
import re
from dataclasses import dataclass, field

TOK_RE = re.compile(r"\s*(?:(infix[lr])|(\d+)|([a-zA-Z_]\w*)|([();])|([!$%&*+\-./:<=>?@^|~]+))")


@dataclass
class DynamicPrattParser:
    infix_ops: dict[str, tuple[int, int]] = field(
        default_factory=lambda: {
            "+": (12, 13),  # prec 6, infixl
            "-": (12, 13),
            "*": (14, 15),  # prec 7, infixl
            "/": (14, 15),
        }
    )

    def register_op(self, assoc: str, prec: int, sym: str) -> None:
        if not (0 <= prec <= 9):
            raise SyntaxError("precedence must be in 0..9")
        base = 2 * prec + 2
        if assoc == "infixl":
            self.infix_ops[sym] = (base, base + 1)
        elif assoc == "infixr":
            self.infix_ops[sym] = (base + 1, base)
        else:
            raise SyntaxError(f"unknown associativity: {assoc}")

    def parse_script(self, src: str) -> list:
        toks = [
            m.group(1) or m.group(2) or m.group(3) or m.group(4) or m.group(5)
            for m in TOK_RE.finditer(src)
        ]
        pos = 0

        def peek() -> str | None:
            return toks[pos] if pos < len(toks) else None

        def take(expected: str | None = None) -> str:
            nonlocal pos
            tok = peek()
            if tok is None or (expected is not None and tok != expected):
                raise SyntaxError(f"expected {expected!r}, got {tok!r}")
            pos += 1
            return tok

        def parse_expr(min_bp: int = 0):
            t = take()
            if t == "(":
                lhs = parse_expr(0)
                take(")")
            elif t.isdigit():
                lhs = int(t)
            else:
                lhs = t

            while (op := peek()) is not None and op in self.infix_ops:
                l_bp, r_bp = self.infix_ops[op]
                if l_bp < min_bp:
                    break
                take()
                rhs = parse_expr(r_bp)
                lhs = (op, lhs, rhs)
            return lhs

        results = []
        while peek() is not None:
            if peek() in ("infixl", "infixr"):
                assoc = take()
                prec = int(take())
                sym = take()
                take(";")
                self.register_op(assoc, prec, sym)
            else:
                results.append(parse_expr(0))
                if peek() == ";":
                    take(";")
        return results
```

