```ts
export function findImportCycles(adj: Map<string, string[]>): string[][] {
  let clock = 0;
  const idx = new Map<string, number>();
  const low = new Map<string, number>();
  const onStack = new Set<string>();
  const stack: string[] = [];
  const cycles: string[][] = [];

  const dfs = (u: string) => {
    idx.set(u, clock);
    low.set(u, clock);
    clock++;
    stack.push(u);
    onStack.add(u);

    for (const v of adj.get(u) ?? []) {
      if (!idx.has(v)) {
        dfs(v);
        low.set(u, Math.min(low.get(u)!, low.get(v)!));
      } else if (onStack.has(v)) {
        low.set(u, Math.min(low.get(u)!, idx.get(v)!));
      }
    }

    if (low.get(u) === idx.get(u)) {
      const scc: string[] = [];
      while (true) {
        const w = stack.pop()!;
        onStack.delete(w);
        scc.push(w);
        if (w === u) break;
      }
      if (scc.length > 1 || (adj.get(u) ?? []).includes(u)) {
        cycles.push(scc);
      }
    }
  };

