```ts
export class AdaptiveBandwidthEstimator {
  private fastSum = 0;
  private fastWeight = 0;
  private slowSum = 0;
  private slowWeight = 0;

  constructor(private fastHalfLifeSec = 2, private slowHalfLifeSec = 8) {}

  sample(bytes: number, durationMs: number): void {
    if (durationMs < 15 || bytes < 8192) return; // Ignore tiny cached headers
    const sec = durationMs / 1000;
    const bps = (bytes * 8) / sec;

    const fDecay = Math.pow(0.5, sec / this.fastHalfLifeSec);
    this.fastSum = this.fastSum * fDecay + bps * (1 - fDecay);
    this.fastWeight = this.fastWeight * fDecay + (1 - fDecay);

    const sDecay = Math.pow(0.5, sec / this.slowHalfLifeSec);
    this.slowSum = this.slowSum * sDecay + bps * (1 - sDecay);
    this.slowWeight = this.slowWeight * sDecay + (1 - sDecay);
  }

  estimateBps(fallbackBps = 5_000_000): number {
    if (this.fastWeight === 0) return fallbackBps;
    return Math.min(this.fastSum / this.fastWeight, this.slowSum / this.slowWeight);
  }
}
