```java
import java.util.Arrays;

public final class FlatIpv4LpmTrie {
    private final int[] children;
    private final int[] payload;
    private int nodeCount = 1;

    public FlatIpv4LpmTrie(int maxNodes) {
        this.children = new int[maxNodes * 2];
        this.payload = new int[maxNodes];
        Arrays.fill(this.children, -1);
        Arrays.fill(this.payload, -1);
    }

    public void insert(int ipv4Bits, int prefixLen, int tagId) {
        int cur = 0;
        for (int i = 0; i < prefixLen; i++) {
            int bit = (ipv4Bits >>> (31 - i)) & 1;
            int slot = (cur << 1) | bit;
            int nxt = children[slot];
            if (nxt == -1) {
                nxt = nodeCount++;
                children[slot] = nxt;
            }
            cur = nxt;
        }
        payload[cur] = tagId;
    }

    public int longestPrefixMatch(int ipv4Bits) {
        int cur = 0;
        int best = payload[0];
        for (int i = 0; i < 32; i++) {
            int bit = (ipv4Bits >>> (31 - i)) & 1;
            cur = children[(cur << 1) | bit];
            if (cur == -1) break;
            if (payload[cur] != -1) best = payload[cur];
        }
        return best;
    }
}
