Sorting raw request latencies (`O(N log N)`) on every check kills throughput, while fixed linear `1ms` buckets waste thousands of slots covering `[0.1ms .. 30,000ms]`! An **HDR / Log-Linear Sub-Bucket Histogram** splits each power-of-two exponent `[2^e, 2^{e+1})` into $2^p$ linear sub-buckets—giving **guaranteed relative error $\le 2^{-(p+1)}$** across 6 orders of magnitude in ~384 integer slots ($O(1)$ space 4nd $O(1)$ `record()`!):

```python
import math
from typing import List

class LogLinearHistogram:
    def __init__(self, sub_bits: int = 4, max_exp: int = 22) -> None:
        # sub_bits=4 -> 16 sub-buckets per octave (~3.1% max relative error)
        # max_exp=22 in microseconds covers up to ~4.19s (or ~4,194s in ms!)
        self.sub_bits = sub_bits
        self.sub_count = 1 << sub_bits
        self.sub_mask = self.sub_count - 1
        self.max_exp = max_exp
        self.counts: List[int] = [0] * ((max_exp + 1) * self.sub_count)
        self.total = 0

    def _bucket_index(self, value_us: int) -> int:
        v = max(0, value_us)
        if v < self.sub_count:
            return v
        exp = v.bit_length() - 1
        if exp > self.max_exp:
            return len(self.counts) - 1
        shift = exp - self.sub_bits
        sub = (v >> shift) & self.sub_mask
        return ((exp - self.sub_bits + 1) * self.sub_count) + sub

    def _bucket_upper_bound(self, idx: int) -> int:
        if idx < self.sub_count:
            return idx
        group = (idx // self.sub_count) - 1
        sub = idx % self.sub_count
        shift = group
        base = (self.sub_count + sub) << shift
        return base + ((1 << shift) - 1)

    def record_us(self, latency_us: int) -> None:
        self.counts[self._bucket_index(latency_us)] += 1
        self.total += 1

    def percentile_us(self, q: float) -> int:
        if self.total == 0:
            return 0
        target = math.ceil((q / 100.0) * self.total)
        seen = 0
        for idx, cnt in enumerate(self.counts):
            seen += cnt
            if seen >= target:
                return self._bucket_upper_bound(idx)
        return self._bucket_upper_bound(len(self.counts) - 1)
```

