import asyncio
from typing import Any, Awaitable, Callable, Dict, Tuple, TypeVar

T = TypeVar("T")

class ResilientSingleflight:
    def __init__(self) -> None:
        self._calls: Dict[str, asyncio.Task[Any]] = {}

    def forget(self, key: str, expected_task: asyncio.Task[Any] | None = None) -> None:
        cur = self._calls.get(key)
        if cur is not None and (expected_task is None or cur is expected_task):
            self._calls.pop(key, None)

    async def do(
        self,
        key: str,
        fn: Callable[[], Awaitable[T]],
        forget_after_s: float | None = 0.5,
    ) -> Tuple[T, bool]:
        existing = self._calls.get(key)
        if existing is not None:
            return await asyncio.shield(existing), True

        task: asyncio.Task[T] = asyncio.create_task(fn())
        self._calls[key] = task

        loop = asyncio.get_running_loop()
        timer = None
        if forget_after_s is not None and forget_after_s > 0:
            timer = loop.call_later(forget_after_s, self.forget, key, task)

        try:
            res = await asyncio.shield(task)
            return res, False
        finally:
            if timer is not None:
                timer.cancel()
            self.forget(key, task)
