#include <array>
#include <bit>
#include <cstddef>
#include <cstdint>

class SizeClassSlab {
    struct FreeNode { FreeNode* next; };
    // Bins: 0->64B, 1->128B, 2->256B, 3->512B
    std::array<FreeNode*, 4> bins_{};
    std::byte* arena_cur_;
    std::byte* arena_end_;

    static constexpr size_t bin_index(size_t bytes) noexcept {
        if (bytes <= 64) return 0;
        return std::bit_width(bytes - 1) - 6; // 65..128 -> 1, 129..256 -> 2, 257..512 -> 3
    }

public:
    SizeClassSlab(std::byte* buf_64b_aligned, size_t cap) noexcept
        : arena_cur_(buf_64b_aligned), arena_end_(buf_64b_aligned + cap) {}

    void* alloc(size_t bytes) noexcept {
        if (bytes > 512) return nullptr;
        const size_t idx = bin_index(bytes);
        if (FreeNode* head = bins_[idx]) {
            bins_[idx] = head->next;
            return head;
        }
        const size_t slot_sz = size_t{64} << idx;
        if (arena_cur_ + slot_sz > arena_end_) return nullptr;
        void* p = arena_cur_;
        arena_cur_ += slot_sz;
        return p;
    }

    void dealloc(void* p, size_t bytes) noexcept {
        const size_t idx = bin_index(bytes);
        auto* node = static_cast<FreeNode*>(p);
        node->next = bins_[idx];
        bins_[idx] = node;
    }
};
