```ts
export function scoreFuzzyPath(query: string, target: string): number {
  if (!query) return 1;
  const qLen = query.length, tLen = target.length;
  if (qLen > tLen) return 0;
  const qLow = query.toLowerCase(), tLow = target.toLowerCase();

  let qi = 0, score = 0, streak = 0;
  for (let ti = 0; ti < tLen && qi < qLen; ti++) {
    if (tLow[ti] === qLow[qi]) {
      let pts = 10;
      if (streak > 0) pts += 12 * streak;
      const prev = ti > 0 ? target[ti - 1] : '/';
      if (prev === '/' || prev === '-' || prev === '_' || prev === '.') {
