```ts
export class PeakSegmentTree {
  private tree: Float32Array;
  private n: number;

  constructor(samples: Float32Array) {
    this.n = samples.length;
    this.tree = new Float32Array(this.n * 2);
    for (let i = 0; i < this.n; i++) {
      this.tree[this.n + i] = Math.abs(samples[i]);
    }
    for (let i = this.n - 1; i > 0; i--) {
      const a = this.tree[i * 2], b = this.tree[i * 2 + 1];
      this.tree[i] = a > b ? a : b;
    }
  }

  queryMax(left: number, rightExclusive: number): number {
    let l = left + this.n, r = rightExclusive + this.n;
    let peak = 0;
