from enum import IntEnum
import struct


class ParquetCryptoModule(IntEnum):
    FOOTER = 0
    COLUMN_META_DATA = 1
    DATA_PAGE = 2
    DICTIONARY_PAGE = 3
    DATA_PAGE_HEADER = 4
    DICTIONARY_PAGE_HEADER = 5
    COLUMN_INDEX = 6
    OFFSET_INDEX = 7
    BLOOM_FILTER_HEADER = 8
    BLOOM_FILTER_BITSET = 9


def build_parquet_module_aad(
    file_aad: bytes,
    module_type: ParquetCryptoModule,
    row_group_ordinal: int = -1,
    column_ordinal: int = -1,
    page_ordinal: int = -1,
) -> bytes:
    if module_type == ParquetCryptoModule.FOOTER:
        return file_aad + struct.pack("<b", int(module_type))

    if not (0 <= row_group_ordinal <= 32767 and 0 <= column_ordinal <= 32767):
        raise ValueError("Row group and column ordinals must fit signed int16 [0..32767]")

    page_scoped = {
        ParquetCryptoModule.DATA_PAGE,
        ParquetCryptoModule.DATA_PAGE_HEADER,
    }
    if module_type in page_scoped:
        if not (0 <= page_ordinal <= 32767):
            raise ValueError("DataPage modules require non-negative int16 page_ordinal")
        return file_aad + struct.pack(
            "<bhhh", int(module_type), row_group_ordinal, column_ordinal, page_ordinal
