```java
import java.util.Arrays;

public final class LongCuckooSet {
    private static final long EMPTY = 0L;
    private final int mask;
    private final long[] t1;
    private final long[] t2;
    private boolean hasZero;

    public LongCuckooSet(int halfCapPow2) {
        this.mask = halfCapPow2 - 1;
        this.t1 = new long[halfCapPow2];
        this.t2 = new long[halfCapPow2];
    }

    private int h1(long k) { return (int) ((k * 0x9E3779B97F4A7C15L) >>> 32) & mask; }
    private int h2(long k) { return (int) ((k * 0xC2B2AE3D27D4EB4FL) >>> 32) & mask; }

    public boolean contains(long k) {
        if (k == EMPTY) return hasZero;
        return t1[h1(k)] == k || t2[h2(k)] == k;
    }

    public boolean add(long k) {
        if (k == EMPTY) { boolean prev = hasZero; hasZero = true; return !prev; }
        if (contains(k)) return false;
        long cur = k;
        for (int kick = 0; kick < 64; kick++) {
            int i1 = h1(cur);
            long evicted1 = t1[i1];
            t1[i1] = cur;
            if (evicted1 == EMPTY) return true;
            int i2 = h2(evicted1);
            long evicted2 = t2[i2];
            t2[i2] = evicted1;
            if (evicted2 == EMPTY) return true;
            cur = evicted2;
        }
        throw new IllegalStateException("Cycle limit exceeded; resize table");
    }
}
