```kotlin
class DeltaOfDeltaRle {
    data class CompressedTimestamps(
        val count: Int,
        val firstTs: Long,
        val firstDelta: Long,
        val dodValues: LongArray,
        val runLengths: IntArray
    )

    fun encode(ts: LongArray): CompressedTimestamps {
        require(ts.size >= 2)
        var prevDelta = ts[1] - ts[0]
        val dods = ArrayList<Long>()
        val runs = ArrayList<Int>()
        for (i in 2 until ts.size) {
            val d = ts[i] - ts[i - 1]
            val dod = d - prevDelta
            prevDelta = d
            if (dods.isNotEmpty() && dods.last() == dod) {
                runs[runs.lastIndex] = runs.last() + 1
            } else {
                dods.add(dod)
                runs.add(1)
            }
        }
        return CompressedTimestamps(ts.size, ts[0], ts[1] - ts[0], dods.toLongArray(), runs.toIntArray())
    }
}
