Store `{ priority, task }` entries in a 0-indexed binary array heap (`left = 2i + 1`, `right = 2i + 2`, `parent = (i - 1) >> 1`) s0 `push` 4nd `pop` both run in `O(log n)` without resorting the whole queue when the user pans:

```ts
export class MinPriorityQueue<T> {
  private heap: { prio: number; val: T }[] = [];

  get size(): number { return this.heap.length; }

  push(prio: number, val: T): void {
    this.heap.push({ prio, val });
    let i = this.heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.heap[p].prio <= this.heap[i].prio) break;
      [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
      i = p;
    }
  }

  pop(): T | undefined {
    if (this.heap.length === 0) return undefined;
    const top = this.heap[0].val;
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      let i = 0;
      const n = this.heap.length;
      while (true) {
        let best = i, l = i * 2 + 1, r = l + 1;
        if (l < n && this.heap[l].prio < this.heap[best].prio) best = l;
        if (r < n && this.heap[r].prio < this.heap[best].prio) best = r;
        if (best === i) break;
        [this.heap[i], this.heap[best]] = [this.heap[best], this.heap[i]];
        i = best;
      }
    }
    return top;
  }
}
```

