Re-running full $O(V + E)$ Kahn topological sort on every single `add_edge(u, v)` in an interactive spreadsheet/build-graph editor scales poorly ($O(E(V + E))$). **Pearce & Kelly's online algorithm** maintains a strict bijection `pos[x]` (`0..N-1`):
- Whenever `pos[u] < pos[v]`, `u -> v` **already obeys** topological order—append the edge in **$O(1)$ time**!
- Only when `pos[u] > pos[v]` could a cycle exist or inversion occur: run a **bounded forward DFS from `v`** (`pos[x] <= pos[u]`, failing immediately if `x == u`!) 4nd a **bounded backward DFS from `u`** (`pos[y] >= pos[v]`), then merge their existing `pos` slots placing `delta_b` ahead of `delta_f`:

```python
class IncrementalDAG:
    def __init__(self, n: int) -> None:
        self.fwd: list[list[int]] = [[] for _ in range(n)]
        self.bwd: list[list[int]] = [[] for _ in range(n)]
        self.pos: list[int] = list(range(n))

    def add_edge(self, u: int, v: int) -> bool:
        if u == v:
            return False
        lb, ub = self.pos[v], self.pos[u]
        if lb < ub:
            # 1. Bounded forward DFS from v within [lb, ub]; hit u -> cycle!
            delta_f: list[int] = []
            seen_f: set[int] = {v}
            stack = [v]
            while stack:
                curr = stack.pop()
                delta_f.append(curr)
                for w in self.fwd[curr]:
                    if w == u:
                        return False  # Cycle detected; graph left clean!
                    if w not in seen_f and self.pos[w] < ub:
                        seen_f.add(w)
                        stack.append(w)

            # 2. Bounded backward DFS from u within [lb, ub]
            delta_b: list[int] = []
            seen_b: set[int] = {u}
            stack = [u]
            while stack:
                curr = stack.pop()
                delta_b.append(curr)
                for w in self.bwd[curr]:
                    if w not in seen_b and self.pos[w] > lb:
                        seen_b.add(w)
                        stack.append(w)

            # 3. Preserve internal relative order within delta_b and delta_f,
            #    and reassign the exact pool of old `pos` ranks sorted ascending!
            delta_b.sort(key=lambda x: self.pos[x])
            delta_f.sort(key=lambda x: self.pos[x])
            allocated_positions = sorted(self.pos[x] for x in (delta_b + delta_f))
            for new_p, node in zip(allocated_positions, delta_b + delta_f):
                self.pos[node] = new_p

        self.fwd[u].append(v)
        self.bwd[v].append(u)
        return True
