export function rasterizeStroke(
  x0: number,
  y0: number,
  x1: number,
  y1: number,
  visit: (gx: number, gy: number) => void,
): void {
  let cx = x0 | 0, cy = y0 | 0;
  const tx = x1 | 0, ty = y1 | 0;
  const dx = Math.abs(tx - cx), sx = cx < tx ? 1 : -1;
  const dy = -Math.abs(ty - cy), sy = cy < ty ? 1 : -1;
  let err = dx + dy;

  while (true) {
    visit(cx, cy);
    if (cx === tx && cy === ty) break;
    const e2 = err * 2;
    if (e2 >= dy) { err += dy; cx += sx; }
    if (e2 <= dx) { err += dx; cy += sy; }
  }
}
