```ts
export class FastBloom {
  private words: Uint32Array;
  private mask: number;

  constructor(pow2Bits = 21, private readonly k = 6) {
    const totalBits = 1 << pow2Bits;
    this.words = new Uint32Array(totalBits >>> 5);
    this.mask = totalBits - 1;
  }

  private hashes(str: string): [number, number] {
    let h1 = 0x811c9dc5, h2 = 0x01000193;
    for (let i = 0; i < str.length; i++) {
      const c = str.charCodeAt(i);
      h1 = Math.imul(h1 ^ c, 0x01000193);
      h2 = Math.imul(h2 ^ c, 0x85ebca6b);
    }
    return [h1 >>> 0, (h2 | 1) >>> 0];
  }

  add(key: string): void {
    const [h1, h2] = this.hashes(key);
    for (let i = 0; i < this.k; i++) {
      const bit = (h1 + Math.imul(i, h2)) & this.mask;
      this.words[bit >>> 5] |= 1 << (bit & 31);
    }
  }

  mightHave(key: string): boolean {
    const [h1, h2] = this.hashes(key);
    for (let i = 0; i < this.k; i++) {
      const bit = (h1 + Math.imul(i, h2)) & this.mask;
      if ((this.words[bit >>> 5] & (1 << (bit & 31))) === 0) return false;
    }
    return true;
  }
}
```

