class Edge01(val to: Int, val cost: Int) // cost is 0 or 1

fun zeroOneBfs(n: Int, adj: Array<Array<Edge01>>, src: Int): IntArray {
    val dist = IntArray(n) { Int.MAX_VALUE }
    dist[src] = 0
    val cap = Integer.highestOneBit((n * 2).coerceAtLeast(2) - 1) shl 1
    val mask = cap - 1
    val deque = IntArray(cap)
    var head = 0
    var tail = 0
    deque[tail++ and mask] = src

    while (head != tail) {
        val u = deque[head++ and mask]
        val du = dist[u]
        for (e in adj[u]) {
            val nd = du + e.cost
            if (nd < dist[e.to]) {
                dist[e.to] = nd
                if (e.cost == 0) {
                    deque[--head and mask] = e.to
                } else {
                    deque[tail++ and mask] = e.to
                }
            }
        }
    }
    return dist
}
