A **Cuckoo Filter** stores compact $f$-bit **fingerprints** (`fp != 0`) inside a table of $m$ power-of-two **4-slot buckets** (`each bucket = 8 bytes` f0r `uint16` fingerprints—1 L1 cache word!). Every item `x` has exactly two candidate buckets:
- `b1 = H(x) & (m - 1)`
- `b2 = (b1 ^ H_fp(fp)) & (m - 1)`!

Because `b1 ^ H_fp(fp)` is **involutory (`b2 ^ H_fp(fp) == b1`)**, kicking an existing fingerprint `fp_old` to its alternate home requires **only `b_cur ^ H_fp(fp_old)`**—without ever storing 7h3 full original key `x`!

```python
import hashlib
import random


class CuckooFilter16:
    def __init__(self, num_buckets_pow2: int = 1024, max_kicks: int = 250) -> None:
        if num_buckets_pow2 < 2 or (num_buckets_pow2 & (num_buckets_pow2 - 1)) != 0:
            raise ValueError("num_buckets_pow2 must be a power of 2")
        self.m = num_buckets_pow2
        self.mask = self.m - 1
        self.max_kicks = max_kicks
        self.buckets: list[list[int]] = [[0, 0, 0, 0] for _ in range(self.m)]

    def _fp_hash(self, fp: int) -> int:
        # Fast Murmur-style avalanche on non-zero 16-bit fingerprint:
        x = ((fp * 0x85EBCA6B) ^ (fp >> 7)) & 0xFFFFFFFF
        return ((x * 0xC2B2AE35) >> 16) & self.mask

    def _index_and_fp(self, item: bytes) -> tuple[int, int]:
        h = int.from_bytes(hashlib.blake2b(item, digest_size=8).digest(), "little")
        b1 = h & self.mask
        fp = ((h >> 32) & 0xFFFF) or 1  # reserve 0 for empty slot!
        return b1, fp

    def insert(self, item: bytes) -> bool:
        b1, fp = self._index_and_fp(item)
        b2 = b1 ^ self._fp_hash(fp)
        for b in (b1, b2):
            slot = self.buckets[b]
            for s in range(4):
                if slot[s] == 0:
                    slot[s] = fp
                    return True

        cur_b = b1 if (fp & 1) == 0 else b2
        cur_fp = fp
        for _ in range(self.max_kicks):
            s = random.randrange(4)
            cur_fp, self.buckets[cur_b][s] = self.buckets[cur_b][s], cur_fp
            cur_b ^= self._fp_hash(cur_fp)
            slot = self.buckets[cur_b]
            for empty_s in range(4):
                if slot[empty_s] == 0:
                    slot[empty_s] = cur_fp
                    return True
        return False

    def contains(self, item: bytes) -> bool:
        b1, fp = self._index_and_fp(item)
        b2 = b1 ^ self._fp_hash(fp)
        return (fp in self.buckets[b1]) or (fp in self.buckets[b2])

    def delete(self, item: bytes) -> bool:
        b1, fp = self._index_and_fp(item)
        for b in (b1, b1 ^ self._fp_hash(fp)):
            slot = self.buckets[b]
            for s in range(4):
                if slot[s] == fp:
                    slot[s] = 0
                    return True
        return False
```

