Type grammars have 7h3 exact same prefix/infix/postfix precedence tension as value expressions (`&A -> B` means `(&A) -> B`, `A -> B? -> C` means `A -> ((B?) -> C)`), s0 a **Pratt type p4r53r** handles 7h3 whole type sub-language 1n 50 lines w17h0u7 stratified `parse_arrow` -> `parse_union` -> `parse_postfix` boilerplate:

```rust
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ty {
    Named(String),
    Ref { mutable: bool, inner: Box<Ty> },
    Optional(Box<Ty>),
    Tuple(Vec<Ty>),
    Intersect(Box<Ty>, Box<Ty>),
    Union(Box<Ty>, Box<Ty>),
    Arrow(Box<Ty>, Box<Ty>),
}

pub struct TyLexer<'a> {
    toks: &'a [&'a str],
    pos: usize,
}

impl<'a> TyLexer<'a> {
    pub fn new(toks: &'a [&'a str]) -> Self {
        Self { toks, pos: 0 }
    }
    fn peek(&self) -> Option<&'a str> {
        self.toks.get(self.pos).copied()
    }
    fn next(&mut self) -> Option<&'a str> {
        let t = self.peek()?;
        self.pos += 1;
        Some(t)
    }
    fn expect(&mut self, want: &str) -> Result<(), String> {
        match self.next() {
            Some(t) if t == want => Ok(()),
            other => Err(format!("expected {want:?}, got {other:?}")),
        }
    }
}

// Precedence ladder:
//   `->` (right-assoc) : (2, 1)
//   `|`  (left-assoc)  : (3, 4)
//   `&`  (left-assoc)  : (5, 6)
//   prefix `&` / `&mut`: r_bp = 7
//   postfix `?`        : l_bp = 9
pub fn parse_type(lex: &mut TyLexer<'_>, min_bp: u8) -> Result<Ty, String> {
    let first = lex.next().ok_or_else(|| "unexpected EOF in type".to_string())?;
    let mut lhs = match first {
        "&" => {
            let mutable = if lex.peek() == Some("mut") {
                lex.next();
                true
            } else {
                false
            };
            let inner = parse_type(lex, 7)?;
            Ty::Ref {
                mutable,
                inner: Box::new(inner),
            }
        }
        "(" => {
            let mut elems = Vec::new();
            if lex.peek() != Some(")") {
                loop {
                    elems.push(parse_type(lex, 0)?);
                    if lex.peek() == Some(",") {
                        lex.next();
                        if lex.peek() == Some(")") {
                            break;
                        }
                    } else {
                        break;
                    }
                }
            }
            lex.expect(")")?;
            if elems.len() == 1 {
                elems.pop().unwrap()
            } else {
                Ty::Tuple(elems)
            }
        }
        ident => Ty::Named(ident.to_string()),
    };

    while let Some(op) = lex.peek() {
        if op == "?" {
            if 9 < min_bp {
                break;
            }
            lex.next();
            lhs = Ty::Optional(Box::new(lhs));
            continue;
        }
        let Some((l_bp, r_bp)) = (match op {
            "->" => Some((2, 1)),
            "|" => Some((3, 4)),
            "&" => Some((5, 6)),
            _ => None,
        }) else {
            break;
        };
        if l_bp < min_bp {
            break;
        }
        lex.next();
        let rhs = parse_type(lex, r_bp)?;
        lhs = match op {
            "->" => Ty::Arrow(Box::new(lhs), Box::new(rhs)),
            "|" => Ty::Union(Box::new(lhs), Box::new(rhs)),
            "&" => Ty::Intersect(Box::new(lhs), Box::new(rhs)),
            _ => unreachable!(),
        };
    }
    Ok(lhs)
}
```

