#include <math.h>
#include <stdint.h>
#include <string.h>

typedef uint64_t Value;

#define SIGN_BIT ((uint64_t)0x8000000000000000ULL)
#define QNAN     ((uint64_t)0x7ffc000000000000ULL) // bits 50..62 all 1s!
#define CANON_NAN ((uint64_t)0x7ff8000000000000ULL) // bit 50 == 0 -> NEVER matches QNAN!

static inline Value numberToValue(double num) {
    if (isnan(num)) {
        return CANON_NAN; // scrub x86 negative NaN (0xfff8...) & arbitrary payloads!
    }
    Value bits;
    memcpy(&bits, &num, sizeof(double));
    return bits;
}

static inline int isObj(Value v) {
    return (v & (QNAN | SIGN_BIT)) == (QNAN | SIGN_BIT);
}
