```sql
CREATE OR REPLACE FUNCTION enforce_pipeline_dag_acyclic()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
    found_cycle boolean;
BEGIN
    IF NEW.src_step = NEW.dst_step THEN
        RAISE EXCEPTION 'Self-loop edge (%) is forbidden', NEW.src_step;
    END IF;

    -- Serialize concurrent edge mutations ONLY within the same pipeline_id!
    PERFORM pg_advisory_xact_lock(2147483647, NEW.pipeline_id::bigint);

    WITH RECURSIVE reach(node) AS (
        SELECT e.dst_step
        FROM pipeline_edges e
        WHERE e.pipeline_id = NEW.pipeline_id
          AND e.src_step = NEW.dst_step
        UNION
        SELECT e.dst_step
        FROM reach r
        JOIN pipeline_edges e
          ON e.pipeline_id = NEW.pipeline_id
         AND e.src_step = r.node
    )
    SELECT EXISTS (SELECT 1 FROM reach WHERE node = NEW.src_step)
      INTO found_cycle;

    IF found_cycle THEN
        RAISE EXCEPTION 'Cycle detected in pipeline % adding % -> %',
            NEW.pipeline_id, NEW.src_step, NEW.dst_step;
    END IF;

    RETURN NEW;
END;
$$;
```

