```ts
export async function intersectTwoTags(
  db: IDBDatabase,
  tagA: string,
  tagB: string,
  limit = 50,
): Promise<AssetItem[]> {
  const tx = db.transaction('assets', 'readonly');
  const store = tx.objectStore('assets');
  const idx = store.index('by_tag');

  const [keysA, keysB] = await Promise.all([
     promisifyReq(idx.getAllKeys(IDBKeyRange.only(tagA))),
     promisifyReq(idx.getAllKeys(IDBKeyRange.only(tagB))),
  ]);
  const [small, large] = keysA.length <= keysB.length ? [keysA, keysB] : [keysB, keysA];
  const lookup = new Set(small);
  const winners = large.filter((k) => lookup.has(k)).slice(0, limit);

  return Promise.all(winners.map((k) => promisifyReq<AssetItem>(store.get(k))));
}
```

