Store sorted, non-overlapping half-open `[start, end)` intervals (Run-Length Encoded ranges): `'Select All'` across 1,000,000 rows is a single `[[0, 1_000_000]]` tuple (`16 bytes`), unchecking 5 rows splits 17 into 6 tuples, 4nd `isSelected(row)` binary-searches intervals in `O(log k)`:

```ts
export class RangeSelection {
  private ranges: [number, number][] = []; // disjoint sorted [start, end)

  selectRange(s: number, e: number): void {
    if (s >= e) return;
    const next: [number, number][] = [];
    let ns = s, ne = e, inserted = false;
    for (const [rs, re] of this.ranges) {
      if (re < ns) { next.push([rs, re]); }
      else if (rs > ne) {
        if (!inserted) { next.push([ns, ne]); inserted = true; }
        next.push([rs, re]);
      } else {
        ns = Math.min(ns, rs);
        ne = Math.max(ne, re);
      }
    }
    if (!inserted) next.push([ns, ne]);
    this.ranges = next;
  }

  has(index: number): boolean {
    let lo = 0, hi = this.ranges.length - 1;
    while (lo <= hi) {
      const mid = (lo + hi) >>> 1;
      const [rs, re] = this.ranges[mid];
      if (index < rs) hi = mid - 1;
      else if (index >= re) lo = mid + 1;
      else return true;
    }
    return false;
  }
}
```

