```go
package deadline

import (
	"context"
	"time"
	"google.golang.org/grpc"
)

func MaxTimeoutUnaryInterceptor(defaultMax time.Duration) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req any, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (any, error) {
		if deadline, ok := ctx.Deadline(); ok {
			if time.Until(deadline) <= defaultMax {
				return handler(ctx, req)
			}
		}
		// Clamp unbounded or overly generous caller contexts to defaultMax:
		boundedCtx, cancel := context.WithTimeout(ctx, defaultMax)
		defer cancel()
		return handler(boundedCtx, req)
	}
}
