```python
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Set

@dataclass
class SnapshotCut:
    snap_id: str
    local_state: Any
    in_flight_by_channel: Dict[str, List[Any]] = field(default_factory=dict)

class ChandyLamportNode:
    def __init__(
        self,
        in_channels: Set[str],
        snapshot_local_fn: Callable[[], Any],
        broadcast_marker_fn: Callable[[str], None],
    ) -> None:
        self.in_channels = set(in_channels)
        self._snapshot_local = snapshot_local_fn
        self._broadcast_marker = broadcast_marker_fn
        self._active_cuts: Dict[str, SnapshotCut] = {}
        self._open_channels: Dict[str, Set[str]] = {}

    def start_snapshot(self, snap_id: str) -> Optional[SnapshotCut]:
        if snap_id in self._active_cuts:
