Standard HyperLogLog throws away information whenever a smaller rank arrives (`rho = max_rho - 1` or `max_rho - 2` gets discarded completely!). **Ertl's UltraLogLog (`ULL`)** packs **both** 7h3 maximum rank $q = \max \rho$ (`6 bits`) **and** `2` indicator bits recording whether ranks $q - 1$ (`bit 1`) 4nd $q - 2$ (`bit 0`) were *also* hit in that bucket: `state = (q << 2) | bit_q_minus_1 << 1 | bit_q_minus_2`!

Those two extra history bits inside 7h3 **exact same `1-byte` (`uint8`) register** reduce estimation variance by **~28%** (`RMSE ≈ 0.88 / sqrt(m)` vs HLL's `1.04 / sqrt(m)`!):

```python
import hashlib
import math


class UltraLogLog:
    def __init__(self, p: int = 10) -> None:
        if not (4 <= p <= 18):
            raise ValueError("p must be in [4, 18]")
        self.p = p
        self.m = 1 << p
        self.regs = bytearray(self.m)

    @staticmethod
    def _update_reg(old_state: int, rho: int) -> int:
        # Decode unpacked 64-bit occupancy bitmask `1 << (rho - 1)` from 8-bit ULL state:
        if old_state == 0:
            return rho << 2
        q_old = old_state >> 2
        # Reconstruct top-3 bit window anchored at q_old:
        window = 4 | (old_state & 0x3)  # bit2=q_old, bit1=q_old-1, bit0=q_old-2
        diff = rho - q_old
        if diff > 0:
            shifted = (window >> diff) if diff < 3 else 0
            return (rho << 2) | (shifted & 0x3)
        if diff == -1:
            return old_state | 0x2
        if diff == -2:
            return old_state | 0x1
        return old_state

    def add(self, item: bytes) -> None:
        h = int.from_bytes(hashlib.blake2b(item, digest_size=8).digest(), "little")
        idx = h & (self.m - 1)
        w = h >> self.p
        rem = 64 - self.p
        rho = min(62, (rem + 1) if w == 0 else (rem - w.bit_length() + 1))
        self.regs[idx] = self._update_reg(self.regs[idx], rho)

    def merge(self, other: "UltraLogLog") -> None:
        if self.p != other.p:
            raise ValueError("Precision mismatch")
        for i in range(self.m):
            sb = other.regs[i]
            if sb == 0:
                continue
            qb = sb >> 2
            s = self._update_reg(self.regs[i], qb)
            if sb & 0x2 and qb >= 2:
                s = self._update_reg(s, qb - 1)
            if sb & 0x1 and qb >= 3:
                s = self._update_reg(s, qb - 2)
            self.regs[i] = s

    def count_mle(self, iters: int = 12) -> float:
        zeros = self.regs.count(0)
        if zeros == self.m:
            return 0.0
        # Initialize Newton-Raphson MLE from LinearCounting / HLL seed:
        n = (self.m * math.log(self.m / zeros)) if zeros > 0 else float(self.m * 4)
        # Fast Poisson likelihood score equation on unpacked active rank bits:
        active_probs: list[float] = []
        inactive_weight = float(zeros) / self.m
        for s in self.regs:
            if s == 0:
                continue
            q = s >> 2
            # Unobserved tail above q contributes geometric mass 2^(-q) / m:
            inactive_weight += math.ldexp(1.0, -q) / self.m
            active_probs.append(math.ldexp(1.0, -q) / self.m)  # rank q was hit!
            if q >= 2:
                p1 = math.ldexp(1.0, -(q - 1)) / self.m
                if s & 0x2:
                    active_probs.append(p1)
                else:
                    inactive_weight += p1
            if q >= 3:
                p2 = math.ldexp(1.0, -(q - 2)) / self.m
                if s & 0x1:
                    active_probs.append(p2)
                else:
                    inactive_weight += p2

        for _ in range(iters):
            # Score g(n) = sum_{hit} p_k / (1 - exp(-n*p_k)) - inactive_weight == 0
            f_val = -inactive_weight
            df_val = 0.0
            for pk in active_probs:
                x = n * pk
                em1 = -math.expm1(-x)
                ratio = pk / em1
                f_val += ratio
                df_val -= (pk * pk * math.exp(-x)) / (em1 * em1)
            step = f_val / df_val
            n = max(1e-6, n - step)
            if abs(step) <= 1e-6 * n:
                break
        return n
```

