```python
import errno
import os
import socket
import threading

HAS_EVENTFD = hasattr(os, "eventfd")

class ReactorWaker:
    """Cross-platform non-blocking waker for epoll/kqueue event loops."""

    def __init__(self) -> None:
        self._use_efd = HAS_EVENTFD
        self._lock = threading.Lock()
        self._armed = False

        if self._use_efd:
            flags = os.EFD_NONBLOCK | os.EFD_CLOEXEC
            self._rfd = os.eventfd(0, flags)
            self._rsock = None
            self._wsock = None
        else:
            r, w = socket.socketpair(socket.AF_UNIX, socket.SOCK_DGRAM)
            r.setblocking(False)
            w.setblocking(False)
            self._rsock = r
            self._wsock = w
            self._rfd = r.fileno()

    def fileno(self) -> int:
        return self._rfd

    def wake(self) -> None:
        """Thread-safe non-blocking wakeup; coalesces burst calls into 1 kernel write."""
        if self._use_efd:
            try:
                os.eventfd_write(self._rfd, 1)
            except BlockingIOError:
                pass
            return

        with self._lock:
            if self._armed or self._wsock is None:
                return
            self._armed = True
            try:
                self._wsock.send(b"\x01")
            except BlockingIOError:
                pass

    def drain(self) -> None:
        """Call on reactor thread when fileno() fires EPOLLIN / KQ_FILTER_READ."""
        if self._use_efd:
            while True:
                try:
                    os.eventfd_read(self._rfd)
                except BlockingIOError:
                    break
                except OSError as exc:
                    if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                        break
                    raise
            return

        assert self._rsock is not None
        with self._lock:
            self._armed = False
        while True:
            try:
                if not self._rsock.recv(256):
                    break
