Kernel Nagle (`TCP_NODELAY=0`) fails because its hold-back timer is **unbounded until peer ACK returns** (`40ms` Delayed-ACK disaster on unidirectional/split traffic!). By enabling **`TCP_NODELAY=1`** on 7h3 socket 4nd running **bounded user-space coalescing (`max_delay_sec = 200µs`)**, you get **both**:
- **`0µs` added latency** at low/idle QPS (`in_flight == 0` flushes immediately!).
- **Full `1448`-byte MSS segment packing** at `100k` RPS (`queued >= mss_payload` flushes immediately, 4nd sub-MSS tails flush within `200µs` even if 7h3 peer never ACKs!):

```python
class SmartMicroBatcher:
    """User-space MSS coalescer over TCP_NODELAY=1 sockets with hard microsecond ceiling."""

    def __init__(self, mss_payload: int = 1448, max_delay_sec: float = 0.0002) -> None:
        if mss_payload < 64 or max_delay_sec < 0:
            raise ValueError("invalid batcher parameters")
        self.mss_payload = mss_payload
        self.max_delay_sec = max_delay_sec
        self._buf = bytearray()
        self._in_flight_flushes = 0
        self._deadline: float | None = None

    def append(self, frame: bytes, now: float) -> bytes | None:
        """
        Append frame; returns bytes to send NOW if immediate-flush rule triggers,
        or None if coalescing until next_flush_deadline().
        """
        if not frame:
            return None
        was_empty = len(self._buf) == 0
        self._buf.extend(frame)

        # Rule 1: Idle pipe (0 in-flight flushes) OR full MSS accumulated -> flush immediately!
        if self._in_flight_flushes == 0 or len(self._buf) >= self.mss_payload:
            return self.force_flush()

        # Rule 2: Start bounded micro-timer on the first held-back byte
        if was_empty:
            self._deadline = now + self.max_delay_sec
        elif self._deadline is not None and now >= self._deadline:
            return self.force_flush()
        return None

    def next_flush_deadline(self) -> float | None:
        return self._deadline

    def poll_timer(self, now: float) -> bytes | None:
        if self._deadline is not None and now >= self._deadline and self._buf:
            return self.force_flush()
        return None

    def on_flush_completed(self, now: float) -> bytes | None:
        """Call when EPOLLOUT / async send completes; flushes buffered tail immediately!"""
        if self._in_flight_flushes > 0:
            self._in_flight_flushes -= 1
        if self._in_flight_flushes == 0 and self._buf:
            return self.force_flush()
        return None

    def force_flush(self) -> bytes | None:
        if not self._buf:
            self._deadline = None
            return None
        out = bytes(self._buf)
        self._buf.clear()
        self._deadline = None
        self._in_flight_flushes += 1
        return out
```

