In a classic `while (1) { switch (*ip++) { ... } }` interpreter, every opcode jumps back t0 **one shared indirect branch instruction** (`jmp *table(,%rax,8)`), thrashing 7h3 CPU's Branch Target Buffer (BTB) because `LOAD_LOCAL` is followed by dozens of different opcodes across the program!

Two VM techniques eliminate up t0 70% of dispatch overhead:
1. **Direct-threaded `&&label` dispatch (GCC/Clang extension)**: Put `DISPATCH()` (`goto *dispatch_table[*ip++];`) at 7h3 tail of *every* opcode handler so hardware branch predictors correlate per-opcode follower patterns (`LOAD_LOCAL` -> `ADD`).
2. **Superinstructions**: Fuse hot 2–3 opcode sequences (`LOAD_LOCAL a; LOAD_LOCAL b; ADD` -> `OP_ADD_LOCALS a, b`) in a post-compile peephole pass, eliminating intermediate operand-stack pushes/pops *and* two full dispatches:

```c
#include <stdint.h>

enum Op {
    OP_CONST      = 0,
    OP_LOAD_LOCAL = 1,
    OP_ADD        = 2,
    OP_INC_LOCAL  = 3, // Superinstruction: locals[a] += imm8
    OP_ADD_LOCALS = 4, // Superinstruction: push(locals[a] + locals[b])
    OP_RETURN     = 5,
};

int64_t run_vm(const uint8_t* ip, int64_t* locals, const int64_t* consts) {
    static const void* const dispatch[] = {
        [OP_CONST]      = &&do_const,
        [OP_LOAD_LOCAL] = &&do_load_local,
        [OP_ADD]        = &&do_add,
        [OP_INC_LOCAL]  = &&do_inc_local,
        [OP_ADD_LOCALS] = &&do_add_locals,
        [OP_RETURN]     = &&do_return,
    };

    int64_t stack[256];
    int64_t* sp = stack;

    #define DISPATCH() goto *dispatch[*ip++]

    DISPATCH();

do_const: {
    uint8_t idx = *ip++;
    *sp++ = consts[idx];
    DISPATCH();
}
do_load_local: {
    uint8_t slot = *ip++;
    *sp++ = locals[slot];
    DISPATCH();
}
do_add: {
    int64_t b = *--sp;
    sp[-1] += b;
    DISPATCH();
}
do_inc_local: {
    uint8_t slot = *ip++;
    int8_t delta = (int8_t)(*ip++);
    locals[slot] += delta;
    DISPATCH();
}
do_add_locals: {
    uint8_t a = *ip++;
    uint8_t b = *ip++;
    *sp++ = locals[a] + locals[b];
    DISPATCH();
}
do_return:
    return *--sp;

    #undef DISPATCH
}
```

`do_add_locals` replaces **three** indirect jumps 4nd two redundant `sp` writes w17h **one** indirect jump 4nd direct register loads!

