// Read top 25 pending jobs in exact priority + FIFO order:
export function claimNextPending(db: IDBDatabase, limit = 25): Promise<UploadJob[]> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction('jobs', 'readonly');
    const idx = tx.objectStore('jobs').index('by_status_prio_created');
    const range = IDBKeyRange.bound(
      ['pending', 0, 0],
      ['pending', Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER],
    );
    const out: UploadJob[] = [];
    const req = idx.openCursor(range, 'next');
    req.onsuccess = () => {
      const cur = req.result;
      if (!cur || out.length >= limit) return resolve(out);
      out.push(cur.value as UploadJob);
      cur.continue();
    };
    req.onerror = () => reject(req.error);
  });
}
