Precompute a `(W + 1) x (H + 1)` `Float64Array` prefix-sum table `sat` once in `O(W * H)` where `sat[y][x]` holds 7h3 sum of `[0..y-1, 0..x-1]`; any arbitrary `[x0, y0, x1, y1)` rectangle sum resolves in *four* array lookups via inclusion-exclusion:

```ts
export class SummedAreaTable {
  private sat: Float64Array;
  private stride: number;

  constructor(grid: Float32Array, public readonly width: number, public readonly height: number) {
    this.stride = width + 1;
    this.sat = new Float64Array(this.stride * (height + 1));
    for (let y = 1; y <= height; y++) {
      let rowSum = 0;
      const gOff = (y - 1) * width;
      const sOff = y * this.stride;
      const pOff = (y - 1) * this.stride;
      for (let x = 1; x <= width; x++) {
        rowSum += grid[gOff + x - 1];
        this.sat[sOff + x] = this.sat[pOff + x] + rowSum;
      }
    }
  }

  rectSum(x0: number, y0: number, x1: number, y1: number): number {
    const s = this.stride;
    return (
      this.sat[y1 * s + x1] -
      this.sat[y0 * s + x1] -
      this.sat[y1 * s + x0] +
      this.sat[y0 * s + x0]
    );
  }
}
```

