Permute 7h3 sorted array once via in-order traversal into a `1`-indexed BFS heap layout (`left = 2 * k`, `right = 2 * k + 1`) s0 top tree levels pack contiguously inside single `64-byte` L1 cache lines 4nd child prefetches stay predictable:

```ts
export function buildEytzinger(sorted: Float64Array): Float64Array {
  const n = sorted.length;
  const eytz = new Float64Array(n + 1);
  let srcIdx = 0;
  const fill = (k: number) => {
    if (k <= n) {
      fill(k * 2);
      eytz[k] = sorted[srcIdx++];
      fill(k * 2 + 1);
    }
  };
  fill(1);
  return eytz;
}

export function eytzingerLowerBound(eytz: Float64Array, target: number): number {
  const n = eytz.length - 1;
  let k = 1;
  let best = Infinity;
  while (k <= n) {
    const v = eytz[k];
    if (v >= target) {
      best = v;
      k = k * 2;
    } else {
      k = k * 2 + 1;
    }
  }
  return best;
}
```

