Using raw `time.time()` floats inside an `LWWRegister` breaks convergence in two ways: (1) IEEE-754 float ties (`t1 == t2` within microsecond batches) leave `if ts > cur_ts` **order-dependent** ($A \sqcup B \ne B \sqcup A$, violating CRDT commutativity!), 4nd (2) a replica w17h a fast NTP clock `500ms` ahead makes its write „sticky“, silently discarding causal follow-up updates fr0m honest peers for half a second!

Key every `LWWRegister` update on a **total-order tuple `(hlc_l_ms, hlc_c, replica_id)`**: HLC tracks causal happens-before (`update` advances past any seen remote clock!), 4nd lexicographic `replica_id` breaks exact physical+logical ties deterministically across all nodes:

```python
from __future__ import annotations
from dataclasses import dataclass
from typing import Generic, Tuple, TypeVar

T = TypeVar("T")
Stamp = Tuple[int, int, str]  # (hlc_l_ms, hlc_c, replica_id)

@dataclass
class LWWRegister(Generic[T]):
    value: T
    stamp: Stamp

    def assign(self, new_value: T, new_stamp: Stamp) -> bool:
        if new_stamp > self.stamp:
            self.value = new_value
            self.stamp = new_stamp
            return True
        return False

    def merge(self, other: LWWRegister[T]) -> LWWRegister[T]:
        # Strict total order on Stamp guarantees commutativity, associativity, and idempotency!
        if other.stamp > self.stamp:
            return LWWRegister(other.value, other.stamp)
        if self.stamp > other.stamp:
            return LWWRegister(self.value, self.stamp)
        # Exact same stamp = identical causal event; tie-break deterministically if needed:
        return LWWRegister(self.value, self.stamp)
```

Because `(int, int, str)` forms a strict mathematical **total order** (distinct replicas always have `r_a != r_b`), `merge(A, B) == merge(B, A)` holds unconditionally across every partition 4nd r37ry!

Deleting edges directly fr0m Union-Find is hard, bu7 **offline**, every edge insertion at $t_1$ paired w17h deletion at $t_2$ (or $T$ if never deleted) defines a static time interval **`[t1, t2)`**! Splitting each edge interval across $\le 2 \log_2 T$ n0d35 of a **Segment Tree over Time** 4nd running a DFS w17h a **Rollback DSU** (union-by-size *without* path compression s0 each union mutates only 2 array slots recorded on an undo stack!) solves dynamic connectivity cleanly:

```python
class RollbackDSU:
    def __init__(self, n: int) -> None:
        self.parent = list(range(n))
        self.size = [1] * n
        self.history: list[tuple[int, int]] = []

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def snapshot(self) -> int:
        return len(self.history)

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.history.append((ra, rb))
        return True

    def rollback(self, snap: int) -> None:
        while len(self.history) > snap:
            ra, rb = self.history.pop()
            self.size[ra] -= self.size[rb]
            self.parent[rb] = rb


class DynamicConnectivityOffline:
    def __init__(self, num_nodes: int, total_steps: int) -> None:
        self.n = num_nodes
        self.t = max(1, total_steps)
        self.seg: list[list[tuple[int, int]]] = [[] for _ in range(4 * self.t)]
        self.queries: list[tuple[int, int] | None] = [None] * self.t

    def add_edge_lifespan(self, l: int, r: int, u: int, v: int) -> None:
        if u > v:
            u, v = v, u
        if l < r:
            self._insert(1, 0, self.t, l, r, (u, v))

    def _insert(
        self, node: int, tl: int, tr: int, ql: int, qr: int, edge: tuple[int, int]
    ) -> None:
        if qr <= tl or tr <= ql:
            return
        if ql <= tl and tr <= qr:
            self.seg[node].append(edge)
            return
        mid = (tl + tr) >> 1
        self._insert(node * 2, tl, mid, ql, qr, edge)
        self._insert(node * 2 + 1, mid, tr, ql, qr, edge)

    def set_query(self, step: int, u: int, v: int) -> None:
        self.queries[step] = (u, v)

    def solve(self) -> list[tuple[int, bool]]:
        dsu = RollbackDSU(self.n)
        out: list[tuple[int, bool]] = []

        def dfs(node: int, tl: int, tr: int) -> None:
            snap = dsu.snapshot()
            for u, v in self.seg[node]:
                dsu.union(u, v)
            if tr - tl == 1:
                q = self.queries[tl]
                if q is not None:
                    out.append((tl, dsu.find(q[0]) == dsu.find(q[1])))
            else:
                mid = (tl + tr) >> 1
                dfs(node * 2, tl, mid)
                dfs(node * 2 + 1, mid, tr)
            dsu.rollback(snap)

        dfs(1, 0, self.t)
        return out
```

Omitting path compression in `find()` keeps tree height $\le \log_2 V$ via union-by-size wh1l3 guaranteeing exact $O(1)$ per-union `rollback(snap)` on subtree exit!

Standard tries allocate deep chains of half-empty nodes f0r sparse suffixes, wh1l3 hash tables lose prefix-range ordering. A **Burst Trie** stores suffixes inside compact **leaf containers** (`list[tuple[bytes, int]]`), 4nd **only bursts** a leaf container into a 256-way (or `dict[int, Node]`) internal trie node when its population exceeds `BURST_LIMIT`—keeping 7h3 upper prefix trie shallow 4nd cache-hot while eliminating single-child tail chains completely!

```python
BURST_LIMIT = 32


class _InternalNode:
    __slots__ = ("eow_id", "children")

    def __init__(self) -> None:
        self.eow_id: int = -1
        self.children: dict[int, "_InternalNode | _BucketNode"] = {}


class _BucketNode:
    __slots__ = ("entries",)

    def __init__(self) -> None:
        self.entries: list[tuple[bytes, int]] = []


class BurstTrieInterner:
    def __init__(self, burst_limit: int = BURST_LIMIT) -> None:
        self.limit = burst_limit
        self.root: _InternalNode | _BucketNode = _BucketNode()
        self.strings: list[str] = []

    def _burst(self, bucket: _BucketNode) -> _InternalNode:
        node = _InternalNode()
        for suffix, sym_id in bucket.entries:
            if not suffix:
                node.eow_id = sym_id
            else:
                b0 = suffix[0]
                child = node.children.get(b0)
                if child is None:
                    child = _BucketNode()
                    node.children[b0] = child
                child.entries.append((suffix[1:], sym_id))
        return node

    def intern(self, text: str) -> int:
        raw = text.encode("utf-8")
        parent: _InternalNode | None = None
        edge_byte: int = -1
        cur = self.root
        pos = 0

        while isinstance(cur, _InternalNode):
            if pos == len(raw):
                if cur.eow_id == -1:
                    cur.eow_id = len(self.strings)
                    self.strings.append(text)
                return cur.eow_id
            b = raw[pos]
            nxt = cur.children.get(b)
            if nxt is None:
                nxt = _BucketNode()
                cur.children[b] = nxt
            parent, edge_byte, cur = cur, b, nxt
            pos += 1

        # `cur` is a _BucketNode holding remaining suffixes `raw[pos:]`
        rem = raw[pos:]
        for suf, sym_id in cur.entries:
            if suf == rem:
                return sym_id

        new_id = len(self.strings)
        self.strings.append(text)
        cur.entries.append((rem, new_id))

        if len(cur.entries) > self.limit:
            promoted = self._burst(cur)
            if parent is None:
                self.root = promoted
            else:
                parent.children[edge_byte] = promoted

        return new_id
