```python
import errno
import selectors
import signal
import socket
from typing import Iterable

class SignalWakeBridge:
    """Race-free C-level signal wakeup pipe integrated into Python selectors."""

    def __init__(self, sigs: Iterable[int] = (signal.SIGTERM, signal.SIGINT)) -> None:
        self._rsock, self._wsock = socket.socketpair(socket.AF_UNIX, socket.SOCK_STREAM)
        self._rsock.setblocking(False)
        self._wsock.setblocking(False)

        self._prev_handlers: dict[int, object] = {}
        # CPython requires a Python handler registered (even a no-op) for set_wakeup_fd to fire!
        for sig in sigs:
            self._prev_handlers[sig] = signal.signal(sig, lambda _s, _f: None)

        self._prev_wakeup_fd = signal.set_wakeup_fd(
            self._wsock.fileno(), warn_on_full_buffer=False
        )

    def register(self, sel: selectors.BaseSelector) -> selectors.SelectorKey:
        return sel.register(self._rsock, selectors.EVENT_READ, data=self)

    def drain_signals(self) -> list[int]:
        """Drain all pending signal bytes from wakeup socket until EAGAIN."""
        received: list[int] = []
        while True:
            try:
                chunk = self._rsock.recv(256)
            except BlockingIOError:
                break
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    break
                raise
            if not chunk:
                break
            received.extend(chunk)
        return received

    def close(self, sel: selectors.BaseSelector | None = None) -> None:
        signal.set_wakeup_fd(self._prev_wakeup_fd)
        for sig, prev in self._prev_handlers.items():
            signal.signal(sig, prev)
        if sel is not None:
            try:
                sel.unregister(self._rsock)
            except Exception:
                pass
        self._rsock.close()
        self._wsock.close()
```

