```rust
pub struct BitNfa64 {
    char_mask: [u64; 256], // bit i == 1 iff position i accepts `byte`
    follow: [u64; 64],     // bit j == 1 iff position j can immediately follow position i
    first: u64,            // positions reachable right from start
    last: u64,             // positions whose completion reaches accept
    nullable: bool,        // true iff empty string matches
}

impl BitNfa64 {
    pub fn new(
        char_mask: [u64; 256],
        follow: [u64; 64],
        first: u64,
        last: u64,
        nullable: bool,
    ) -> Self {
        Self {
            char_mask,
            follow,
            first,
            last,
            nullable,
        }
    }

    #[inline]
    fn expand_follow(&self, mut active: u64) -> u64 {
        let mut next_possible = 0u64;
        while active != 0 {
            let idx = active.trailing_zeros() as usize;
            next_possible |= self.follow[idx];
            active &= active - 1; // clear lowest set bit (BLSR instruction)
        }
        next_possible
    }

    /// Full-string exact match in O(|input| * popcnt(active)) register ops
    pub fn is_full_match(&self, input: &[u8]) -> bool {
        if input.is_empty() {
            return self.nullable;
        }
        // Positions allowed to match input[0] are `self.first`
        let mut reachable = self.first & self.char_mask[input[0] as usize];
        if reachable == 0 {
            return false;
        }
        for &b in &input[1..] {
            let allowed = self.expand_follow(reachable);
            reachable = allowed & self.char_mask[b as usize];
            if reachable == 0 {
                return false;
            }
        }
        (reachable & self.last) != 0
    }
}
```

