#include <stddef.h>
#include <stdint.h>

typedef struct {
    uint32_t end_offset; // exclusive bytecode offset where this line run ends
    uint32_t line;
} LineRun;

uint32_t resolveFaultLine(
    const uint8_t* code_start,
    const uint8_t* current_ip,
    const LineRun* runs,
    size_t num_runs
) {
    // current_ip points ONE PAST the executing instruction/operands!
    size_t fault_offset = (current_ip > code_start)
        ? (size_t)(current_ip - code_start - 1)
        : 0;

    size_t lo = 0, hi = num_runs;
