$$\sum_{i=1}^{k} a_i = k \cdot \sum_{i=1}^{k} d_i - \sum_{i=1}^{k} (i - 1) d_i$$

And initializing from an existing `arr` takes **$O(N)$ time** (not $O(N \log N)$!) by propagating each slot once t0 its immediate tree parent `j = i + (i & -i)`:

```python
class RangeFenwick:
    def __init__(self, arr: list[int]) -> None:
        self.n = len(arr)
        self.b1 = [0] * (self.n + 1)
        self.b2 = [0] * (self.n + 1)

        # Build difference terms in O(N), then push to immediate parent i + (i & -i)
        prev = 0
        for idx, val in enumerate(arr, start=1):
            diff = val - prev
            prev = val
            self.b1[idx] += diff
            self.b2[idx] += diff * (idx - 1)
            parent = idx + (idx & -idx)
            if parent <= self.n:
                self.b1[parent] += self.b1[idx]
                self.b2[parent] += self.b2[idx]

    def _add(self, bit: list[int], idx: int, val: int) -> None:
        n = self.n
        while idx <= n:
            bit[idx] += val
            idx += idx & -idx

    def _sum(self, bit: list[int], idx: int) -> int:
        s = 0
        while idx > 0:
            s += bit[idx]
            idx &= idx - 1
        return s

    def range_add(self, l: int, r: int, delta: int) -> None:
        if l >= r:
            return
        # Convert 0-indexed [l, r) -> 1-indexed [l + 1, r]
        li, ri = l + 1, r
        self._add(self.b1, li, delta)
        self._add(self.b1, ri + 1, -delta)
        self._add(self.b2, li, delta * (li - 1))
        self._add(self.b2, ri + 1, -delta * ri)

    def prefix_sum(self, k: int) -> int:
        return k * self._sum(self.b1, k) - self._sum(self.b2, k)

    def range_sum(self, l: int, r: int) -> int:
        return self.prefix_sum(r) - self.prefix_sum(l)
```

