```python
from dataclasses import dataclass


@dataclass(slots=True)
class TSTNode:
    ch: str
    lo: "TSTNode | None" = None
    eq: "TSTNode | None" = None
    hi: "TSTNode | None" = None
    is_end: bool = False


class TernarySearchTree:
    def __init__(self) -> None:
        self.root: TSTNode | None = None

    def insert(self, word: str) -> None:
        if not word:
            return
        if self.root is None:
            self.root = TSTNode(word[0])
        cur = self.root
        i = 0
        n = len(word)
        while True:
            c = word[i]
            if c < cur.ch:
                if cur.lo is None:
                    cur.lo = TSTNode(c)
                cur = cur.lo
            elif c > cur.ch:
                if cur.hi is None:
                    cur.hi = TSTNode(c)
                cur = cur.hi
            else:
                i += 1
                if i == n:
                    cur.is_end = True
                    return
                if cur.eq is None:
                    cur.eq = TSTNode(word[i])
                cur = cur.eq

    @classmethod
    def from_sorted(cls, sorted_words: list[str]) -> "TernarySearchTree":
        tst = cls()
        # Explicit iterative range stack avoids recursion limit on 500k words!
        work: list[tuple[int, int]] = [(0, len(sorted_words))]
        while work:
            l, r = work.pop()
            if l >= r:
                continue
            mid = (l + r) >> 1
            tst.insert(sorted_words[mid])
            work.append((mid + 1, r))
            work.append((l, mid))
        return tst
