var ErrLeaseLost = errors.New("leader lease lost before safety margin")

func RunWithGuardedLease(
	parent context.Context,
	ttl time.Duration,
	renewFn func(context.Context) error,
	workerFn func(context.Context) error,
) error {
	workCtx, cancel := context.WithCancelCause(parent)
	defer cancel(nil)

	safeMargin := ttl / 5
