```python
import hashlib
import math
from typing import Iterable, List

class GossipBloomDigest:
    def __init__(self, num_bits: int = 65536, num_hashes: int = 5) -> None:
        if num_bits <= 0 or (num_bits & 7) != 0:
            raise ValueError("num_bits must be a positive multiple of 8")
        self.num_bits = num_bits
        self.num_hashes = num_hashes
        self.bits = bytearray(num_bits // 8)

    @classmethod
    def optimal_for(cls, expected_items: int, fp_rate: float = 0.01) -> "GossipBloomDigest":
        n = max(1, expected_items)
        m = int(math.ceil(-n * math.log(fp_rate) / (math.log(2.0) ** 2)))
        m = ((m + 63) // 64) * 64  # Align to 64-bit boundary
        k = max(1, int(round((m / n) * math.log(2.0))))
        return cls(num_bits=m, num_hashes=k)

    def _positions(self, key: str) -> Iterable[int]:
        # Kirsch-Mitzenmacher double hashing: 2 64-bit hashes generate k probes!
        d = hashlib.blake2b(key.encode("utf-8"), digest_size=16).digest()
        h1 = int.from_bytes(d[:8], "big")
        h2 = int.from_bytes(d[8:], "big") or 1
        for i in range(self.num_hashes):
            yield (h1 + i * h2) % self.num_bits

    def add(self, key: str) -> None:
        for pos in self._positions(key):
            self.bits[pos >> 3] |= 1 << (pos & 7)

    def might_contain(self, key: str) -> bool:
        for pos in self._positions(key):
            if not (self.bits[pos >> 3] & (1 << (pos & 7))):
                return False
        return True

    def missing_from_peer(self, local_keys: Iterable[str]) -> List[str]:
        # Any key returning False is 100% guaranteed missing on the peer!
        return [k for k in local_keys if not self.might_contain(k)]
```

