2. **Missing `read(tfd, &expirations, 8)` under `EPOLLET`:** Every 10ms tick increments an internal kernel `uint64_t` expiration counter inside `tfd`. Once `counter >= 1`, `tfd` stays continuously readable—so **no new `0 -> 1` readiness edge occurs** until you call `read(tfd, &exp, sizeof(uint64_t))` 70 reset `counter` back 70 `0`!

```c
#include <stdint.h>
#include <sys/epoll.h>
#include <sys/timerfd.h>
#include <unistd.h>

int create_periodic_timerfd(int epfd, long period_ns) {
    int tfd = timerfd_create(CLOCK_MONOTONIC, TFD_NONBLOCK | TFD_CLOEXEC);
    if (tfd < 0) return -1;

    struct itimerspec its = {
        .it_interval = { .tv_sec = period_ns / 1000000000L, .tv_nsec = period_ns % 1000000000L },
        .it_value    = { .tv_sec = period_ns / 1000000000L, .tv_nsec = period_ns % 1000000000L },
    };
    if (timerfd_settime(tfd, 0, &its, NULL) < 0) {
        close(tfd);
        return -1;
    }

    struct epoll_event ev = { .events = EPOLLIN | EPOLLET, .data.fd = tfd };
    epoll_ctl(epfd, EPOLL_CTL_ADD, tfd, &ev);
    return tfd;
}

// Inside epoll_wait handler: MUST drain 8-byte uint64_t until EAGAIN!
uint64_t drain_timerfd(int tfd) {
    uint64_t total_ticks = 0, ticks = 0;
    while (read(tfd, &ticks, sizeof(ticks)) == sizeof(ticks)) {
        total_ticks += ticks; // >1 tells you how many 10ms ticks your reactor overrun missed!
    }
    return total_ticks;
}
