import errno
import os

SPLICE_FLAGS = getattr(os, "SPLICE_F_MOVE", 1) | getattr(os, "SPLICE_F_NONBLOCK", 2)

class SplicePipeRelay:
    """Zero-copy Linux kernel pipe relay between two non-blocking socket fds."""

    def __init__(self, chunk_bytes: int = 65536) -> None:
        self.chunk_bytes = chunk_bytes
        self._pipe_rd, self._pipe_wr = os.pipe2(os.O_NONBLOCK | os.O_CLOEXEC)
        self.buffered_in_pipe = 0
        self.src_eof = False

    def pump(self, src_fd: int, dst_fd: int) -> tuple[int, bool]:
        """
        Move as many bytes as possible src_fd -> pipe -> dst_fd.
        Returns (bytes_forwarded_to_dst, relay_completely_finished).
        """
        forwarded = 0

        while True:
            # Step 1: Flush any bytes already parked inside kernel pipe out to dst_fd first!
            while self.buffered_in_pipe > 0:
                try:
                    w = os.splice(self._pipe_rd, dst_fd, self.buffered_in_pipe, flags=SPLICE_FLAGS)
                except BlockingIOError:
                    return forwarded, False
                except OSError as exc:
                    if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                        return forwarded, False
                    raise
                if w == 0:
                    return forwarded, False
                self.buffered_in_pipe -= w
                forwarded += w

            if self.src_eof:
                return forwarded, True

            # Step 2: Pull next page batch from src_fd into empty kernel pipe
            try:
                r = os.splice(src_fd, self._pipe_wr, self.chunk_bytes, flags=SPLICE_FLAGS)
            except BlockingIOError:
                return forwarded, False
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    return forwarded, False
                raise

            if r == 0:
                self.src_eof = True
                return forwarded, True
            self.buffered_in_pipe += r

    def close(self) -> None:
        if self._pipe_rd >= 0:
            os.close(self._pipe_rd)
            self._pipe_rd = -1
        if self._pipe_wr >= 0:
            os.close(self._pipe_wr)
            self._pipe_wr = -1
```

