```python
from dataclasses import dataclass, field
import heapq
from typing import Callable

@dataclass(order=True)
class _TimerNode:
    deadline: float
    seq: int
    callback: Callable[[], None] = field(compare=False)
    cancelled: bool = field(default=False, compare=False)

class MonotonicTimerHeap:
    """Min-heap reactor timer scheduler with O(1) cancel and amortized compaction."""

    def __init__(self) -> None:
        self._heap: list[_TimerNode] = []
        self._seq = 0
        self._cancelled_count = 0

    def schedule_at(self, deadline: float, callback: Callable[[], None]) -> _TimerNode:
        self._seq += 1
        node = _TimerNode(deadline=deadline, seq=self._seq, callback=callback)
        heapq.heappush(self._heap, node)
        return node

    def cancel(self, node: _TimerNode) -> None:
        if not node.cancelled:
            node.cancelled = True
            self._cancelled_count += 1
            # Compact in O(N) once dead tombstones exceed half the heap (min 64)
            if self._cancelled_count >= 64 and self._cancelled_count * 2 >= len(self._heap):
                self._compact()

    def _compact(self) -> None:
        self._heap = [n for n in self._heap if not n.cancelled]
        heapq.heapify(self._heap)
        self._cancelled_count = 0

    def _discard_head_tombstones(self) -> None:
        while self._heap and self._heap[0].cancelled:
            heapq.heappop(self._heap)
            self._cancelled_count -= 1

    def poll_timeout_sec(self, now: float) -> float | None:
        """Return exact timeout for selector.select(timeout): None=infinite, 0.0=overdue."""
        self._discard_head_tombstones()
        if not self._heap:
            return None
        return max(0.0, self._heap[0].deadline - now)

    def fire_expired(self, now: float) -> int:
        """Run all callbacks with deadline <= now; ignores newly added >now timers."""
        fired = 0
        while True:
            self._discard_head_tombstones()
            if not self._heap or self._heap[0].deadline > now:
                break
            node = heapq.heappop(self._heap)
            node.callback()
            fired += 1
        return fired
```

