import bisect
from typing import List, Optional, Tuple

class ContiguousAckTracker:
    def __init__(self, initial_base_seq: int = 1) -> None:
        self.base_seq = initial_base_seq
        self._ranges: List[Tuple[int, int]] = []

    def ack(self, seq: int) -> Optional[int]:
        if seq < self.base_seq:
            return self.highest_contiguous()

        idx = bisect.bisect_left(self._ranges, (seq, seq))
        lo, hi = seq, seq

        # Merge with left neighbor if overlapping or adjacent (prev_hi + 1 >= lo):
        if idx > 0 and self._ranges[idx - 1][1] + 1 >= lo:
            idx -= 1
            lo = min(lo, self._ranges[idx][0])
            hi = max(hi, self._ranges[idx][1])
            self._ranges.pop(idx)

        # Merge with any right neighbors that are overlapping or adjacent (next_lo <= hi + 1):
        while idx < len(self._ranges) and self._ranges[idx][0] <= hi + 1:
            lo = min(lo, self._ranges[idx][0])
            hi = max(hi, self._ranges[idx][1])
            self._ranges.pop(idx)

        self._ranges.insert(idx, (lo, hi))
        return self.highest_contiguous()

    def highest_contiguous(self) -> Optional[int]:
        if self._ranges and self._ranges[0][0] == self.base_seq:
            return self._ranges[0][1]
        return None

    def gap_count(self) -> int:
        return max(0, len(self._ranges) - 1)
