from typing import Any

def encode_resp_pipeline(commands: list[list[bytes | str | int]]) -> bytearray:
    '''Pack multiple Redis commands into one contiguous RESP2 buffer for a single send().'''
    out = bytearray()
    for cmd in commands:
        out.extend(f"*{len(cmd)}\r\n".encode("ascii"))
        for arg in cmd:
            b = arg if isinstance(arg, bytes) else str(arg).encode("utf-8")
            out.extend(f"${len(b)}\r\n".encode("ascii"))
            out.extend(b)
            out.extend(b"\r\n")
    return out

_NEED_MORE = object()

class RespStreamParser:
    '''Incremental non-blocking RESP2 parser safe across arbitrary TCP/AF_UNIX chunk splits.'''

    def __init__(self) -> None:
        self._buf = bytearray()

    def feed_and_parse(self, chunk: bytes | bytearray | memoryview) -> list[Any]:
        if chunk:
            self._buf.extend(chunk)
        results: list[Any] = []
        pos = 0
        while pos < len(self._buf):
            val, next_pos = self._parse_one(pos)
            if val is _NEED_MORE:
                break
            results.append(val)
            pos = next_pos
        if pos > 0:
            del self._buf[:pos]
        return results

    def _parse_one(self, pos: int) -> tuple[Any, int]:
        nl = self._buf.find(b"\r\n", pos)
        if nl == -1:
            return _NEED_MORE, pos
        prefix = self._buf[pos]
        head = bytes(self._buf[pos + 1 : nl])
        cur = nl + 2

        if prefix == ord("+"):
            return head.decode("utf-8", errors="replace"), cur
        if prefix == ord("-"):
            return RuntimeError(head.decode("utf-8", errors="replace")), cur
        if prefix == ord(":"):
            return int(head), cur
        if prefix == ord("$"):
            length = int(head)
            if length == -1:
                return None, cur
            end = cur + length
            if len(self._buf) < end + 2:
                return _NEED_MORE, pos  # rollback cursor cleanly until full bulk body arrives!
            data = bytes(self._buf[cur:end])
            return data, end + 2
        if prefix == ord("*"):
            count = int(head)
            if count == -1:
                return None, cur
            items = []
            for _ in range(count):
                item, cur = self._parse_one(cur)
                if item is _NEED_MORE:
                    return _NEED_MORE, pos  # rollback entire nested array cleanly!
                items.append(item)
            return items, cur

        raise ValueError(f"invalid RESP prefix byte: {prefix:#x}")
```

