  url: string,
  init: RequestInit,
  totalBudgetMs = 2500,
  perTryMs = 700,
  maxAttempts = 3,
): Promise<Response> {
  const overallSignal = AbortSignal.timeout(totalBudgetMs);
  let lastErr: unknown;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    if (attempt > 0) {
      const ceilMs = Math.min(1000, 80 * (1 << (attempt - 1)));
      const sleepMs = Math.random() * ceilMs;
