          () => {
            clearTimeout(t);
            reject(overallSignal.reason);
          },
          { once: true },
        );
      });
    }
    const attemptSignal = AbortSignal.any([overallSignal, AbortSignal.timeout(perTryMs)]);
    try {
      const res = await fetch(url, { ...init, signal: attemptSignal });
