    cutoff TIMESTAMPTZ,
    batch_size INT DEFAULT 5000,
    max_batches INT DEFAULT 1000,
    pause_sec DOUBLE PRECISION DEFAULT 0.05
)
LANGUAGE plpgsql AS $$
DECLARE
    deleted_rows INT;
    i INT := 0;
BEGIN
    WHILE i < max_batches LOOP
        SET LOCAL lock_timeout = '100ms';

        WITH doomed AS (
            SELECT id
            FROM outbox_events
            WHERE published_at IS NOT NULL
              AND published_at < cutoff
            LIMIT batch_size
            FOR UPDATE SKIP LOCKED
        )
        DELETE FROM outbox_events o
        USING doomed d
        WHERE o.id = d.id;

        GET DIAGNOSTICS deleted_rows = ROW_COUNT;
        COMMIT;

        EXIT WHEN deleted_rows < batch_size;
        i := i + 1;
        PERFORM pg_sleep(pause_sec);
    END LOOP;
END;
$$;

-- Execute paced online cleanup:
