from typing import List, Sequence, Set

class GridQuorumTopology:
    def __init__(self, grid: Sequence[Sequence[str]]) -> None:
        if not grid or not grid[0]:
            raise ValueError("grid must be non-empty")
        cols = len(grid[0])
        if any(len(row) != cols for row in grid):
            raise ValueError("grid must be rectangular")
        self.grid: List[List[str]] = [list(r) for r in grid]
        self.num_rows = len(self.grid)
        self.num_cols = cols

    def read_quorum(self, row_idx: int) -> Set[str]:
        # Any complete row (size = C) intersects every column!
        return set(self.grid[row_idx % self.num_rows])

    def write_quorum(self, row_idx: int, col_idx: int) -> Set[str]:
        # Full row + full column (size = R + C - 1) guarantees BOTH W-W and R-W intersection!
        r_set = set(self.grid[row_idx % self.num_rows])
        c_set = {self.grid[r][col_idx % self.num_cols] for r in range(self.num_rows)}
        return r_set | c_set

    @staticmethod
    def intersects(q1: Set[str], q2: Set[str]) -> bool:
        return bool(q1 & q2)

# Verify 5x5 = 25-node cluster: Read touches 5 nodes, Write touches 9 nodes (vs 13+13 majority!):
g = GridQuorumTopology([[f"n-{r}-{c}" for c in range(5)] for r in range(5)])
for r1 in range(5):
    for r2 in range(5):
        for c2 in range(5):
            assert g.intersects(g.read_quorum(r1), g.write_quorum(r2, c2))
            assert g.intersects(g.write_quorum(r1, 0), g.write_quorum(r2, c2))
```

