```python
class ChunkedBodyDecoder:
    '''Incremental RFC 9112 HTTP/1.1 chunked transfer decoder for non-blocking sockets.'''

    def __init__(self, max_chunk_bytes: int = 16 * 1024 * 1024) -> None:
        self._buf = bytearray()
        self._max_chunk = max_chunk_bytes
        self._rem_in_chunk: int | None = None  # None = reading size line; -1 = reading final CRLF/trailers
        self.complete = False

    def feed(self, data: bytes | bytearray | memoryview) -> bytes:
        if self.complete:
            raise ValueError("chunked stream already completed")
        if data:
            self._buf.extend(data)

        out = bytearray()
        pos = 0
        n = len(self._buf)

        while not self.complete:
            if self._rem_in_chunk is None:
                nl = self._buf.find(b"\r\n", pos)
                if nl == -1:
                    break
                # Strip optional ';chunk-ext=val' before parsing hex size
                line = bytes(self._buf[pos:nl]).split(b";", 1)[0].strip()
                chunk_sz = int(line, 16)
                if chunk_sz < 0 or chunk_sz > self._max_chunk:
                    raise ValueError(f"invalid chunk size: {chunk_sz}")
                pos = nl + 2
                if chunk_sz == 0:
                    self._rem_in_chunk = -1
                else:
                    self._rem_in_chunk = chunk_sz

            elif self._rem_in_chunk > 0:
                avail = n - pos
                if avail == 0:
                    break
                take = min(avail, self._rem_in_chunk)
                out.extend(self._buf[pos : pos + take])
                pos += take
                self._rem_in_chunk -= take
                if self._rem_in_chunk == 0:
                    # Must consume trailing \r\n after chunk payload
                    if n - pos < 2:
                        break
                    if self._buf[pos : pos + 2] != b"\r\n":
                        raise ValueError("missing CRLF after chunk data")
                    pos += 2
                    self._rem_in_chunk = None

            else:
                # Consume optional trailer headers until empty line \r\n
                if self._buf.startswith(b"\r\n", pos):
                    pos += 2
                    self.complete = True
                else:
                    end_tr = self._buf.find(b"\r\n\r\n", pos)
                    if end_tr == -1:
                        break
                    pos = end_tr + 4
                    self.complete = True

        if pos > 0:
            del self._buf[:pos]
        return bytes(out)

def encode_chunk_iov(payload: bytes | memoryview) -> list[bytes | memoryview]:
    '''Return vectored buffers for os.writev(); empty payload emits terminating 0-chunk.'''
    mv = memoryview(payload)
    if len(mv) == 0:
        return [b"0\r\n\r\n"]
    hdr = f"{len(mv):x}\r\n".encode("ascii")
    return [hdr, mv, b"\r\n"]
```

