import socket
import sys

def tune_interactive_tcp_socket(
    sock: socket.socket,
    notsent_lowat_bytes: int = 16384,
    user_timeout_ms: int = 20000,
) -> dict[str, bool]:
    '''
    Tune an AF_INET / AF_INET6 stream socket for low-latency multiplexed RPC/HTTP2:
    1. TCP_NODELAY = 1 (defeat Nagle + Delayed ACK)
    2. TCP_NOTSENT_LOWAT (defeat local SO_SNDBUF head-of-line bufferbloat)
    3. TCP_USER_TIMEOUT (abort PMTUD/NAT blackholes in Send-Q > 0 within user_timeout_ms)
    '''
    applied = {"nodelay": False, "notsent_lowat": False, "user_timeout": False}
    if sock.family not in (socket.AF_INET, socket.AF_INET6):
        return applied

    sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
    applied["nodelay"] = True

    plat = sys.platform
    lowat_opt: int | None = getattr(socket, "TCP_NOTSENT_LOWAT", None)
    if lowat_opt is None:
        if plat.startswith("linux"):
            lowat_opt = 25
        elif plat == "darwin":
            lowat_opt = 0x201

    if lowat_opt is not None and notsent_lowat_bytes > 0:
        try:
            sock.setsockopt(socket.IPPROTO_TCP, lowat_opt, notsent_lowat_bytes)
            applied["notsent_lowat"] = True
        except OSError:
            pass

    if user_timeout_ms > 0:
        uto_opt: int | None = getattr(socket, "TCP_USER_TIMEOUT", None)
        if uto_opt is None and plat.startswith("linux"):
            uto_opt = 18
        if uto_opt is not None:
            try:
                sock.setsockopt(socket.IPPROTO_TCP, uto_opt, user_timeout_ms)
                applied["user_timeout"] = True
            except OSError:
                pass
        elif plat == "darwin":
            # macOS TCP_RXT_CONNDROPTIME (0x80) takes integer seconds!
            secs = max(1, round(user_timeout_ms / 1000))
            try:
                sock.setsockopt(socket.IPPROTO_TCP, 0x80, secs)
                applied["user_timeout"] = True
            except OSError:
                pass

    return applied
```

