```python
import errno
import selectors
import socket
from typing import Callable

class HalfCloseRpcConn:
    '''Non-blocking AF_UNIX / TCP half-close RPC state machine immune to EOF busy-spin.'''

    def __init__(
        self,
        sel: selectors.BaseSelector,
        conn: socket.socket,
        handler: Callable[[bytes], bytes],
        max_req_bytes: int = 8 * 1024 * 1024,
    ) -> None:
        self._sel = sel
        self._conn = conn
        self._handler = handler
        self._max_req = max_req_bytes
        self._rx = bytearray()
        self._tx = memoryview(b"")
        self._tx_offset = 0
        self.closed = False

        conn.setblocking(False)
        sel.register(conn, selectors.EVENT_READ, data=self)

    def on_events(self, mask: int) -> None:
        if self.closed:
            return
        try:
            if mask & selectors.EVENT_READ:
                self._handle_read()
            if not self.closed and (mask & selectors.EVENT_WRITE):
                self._handle_write()
        except Exception:
            self.close()

    def _handle_read(self) -> None:
        while True:
            try:
                chunk = self._conn.recv(65536)
            except BlockingIOError:
                return
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    return
                raise

            if not chunk:
                # Client called shutdown(SHUT_WR)! Compute reply & MUST disarm EVENT_READ!
                resp = self._handler(bytes(self._rx))
                self._rx.clear()
                self._tx = memoryview(resp)
                self._tx_offset = 0
                # Optimistic immediate flush before arming EVENT_WRITE:
                self._handle_write(initial_flush=True)
                return

            self._rx.extend(chunk)
            if len(self._rx) > self._max_req:
                raise ValueError("request exceeded max_req_bytes")

    def _handle_write(self, initial_flush: bool = False) -> None:
        while self._tx_offset < len(self._tx):
            try:
                n = self._conn.send(self._tx[self._tx_offset :])
            except BlockingIOError:
                if initial_flush:
                    # Switch strictly from EVENT_READ -> EVENT_WRITE (no EOF spin!)
                    self._sel.modify(self._conn, selectors.EVENT_WRITE, data=self)
                return
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    if initial_flush:
                        self._sel.modify(self._conn, selectors.EVENT_WRITE, data=self)
                    return
                raise
            self._tx_offset += n

        # Entire response flushed cleanly!
        self.close()

    def close(self) -> None:
        if not self.closed:
            self.closed = True
            try:
                self._sel.unregister(self._conn)
            except Exception:
                pass
            self._conn.close()
```

