```c
int compute_epoll_timeout_ms(int64_t next_deadline_ns, int64_t now_ns) {
    if (next_deadline_ns < 0) return -1; // no timers armed -> sleep indefinitely
    int64_t delta_ns = next_deadline_ns - now_ns;
    if (delta_ns <= 0) return 0;         // already overdue -> poll non-blocking once & fire!
    // Ceiling division: (delta_ns + 999,999) / 1,000,000 prevents sub-ms 0-spin!
    int64_t ms = (delta_ns + 999999LL) / 1000000LL;
    return (ms > INT32_MAX) ? INT32_MAX : (int)ms;
}
