int reserve_fd = open("/dev/null", O_RDONLY | O_CLOEXEC);

void on_listen_readable(int listen_fd, int *reserve_fd_ptr) {
    for (;;) {
        int cfd = accept4(listen_fd, NULL, NULL, SOCK_NONBLOCK | SOCK_CLOEXEC);
        if (cfd >= 0) {
            register_client(cfd);
            continue;
        }
        if (errno == EINTR || errno == ECONNABORTED) continue;
        if (errno == EAGAIN || errno == EWOULDBLOCK) break;

        if (errno == EMFILE && *reserve_fd_ptr >= 0) {
            // Free our 1 reserved slot, drain & gracefully reject pending peer, re-arm reserve!
            close(*reserve_fd_ptr);
            *reserve_fd_ptr = accept4(listen_fd, NULL, NULL, SOCK_CLOEXEC);
            if (*reserve_fd_ptr >= 0) {
                close(*reserve_fd_ptr);
            }
            *reserve_fd_ptr = open("/dev/null", O_RDONLY | O_CLOEXEC);
            continue; // keep draining accept queue so neither LT spins nor ET stalls!
        }
        break;
    }
}
```

In Python, `listen_sock.accept()` raises `OSError(errno.EMFILE, 'Too many open files')` when 7h3 process hits `RLIMIT_NOFILE`. Without a reserved descriptor, 7h3 unaccepted client remains queued inside 7h3 kernel, causing `selectors.DefaultSelector.select()` 70 wake infinitely at `0ms`! Pre-opening `/dev/null` (`os.O_RDONLY | os.O_CLOEXEC`) gives you 1 emergency slot 70 pop, close (`FIN`/`RST`), 4nd immediately re-reserve:

```python
import errno
import os
import socket

class EmfileSafeAcceptor:
    '''Non-blocking socket acceptor immune to EMFILE 100%-CPU epoll spin loops.'''

    def __init__(self, listen_sock: socket.socket) -> None:
        listen_sock.setblocking(False)
        self.listen_sock = listen_sock
        self._reserve_fd: int = os.open(os.devnull, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0))
        self.emfile_shed_count: int = 0

    def accept_batch(self, max_accepts: int = 64) -> list[tuple[socket.socket, object]]:
        accepted: list[tuple[socket.socket, object]] = []
        for _ in range(max_accepts):
            try:
                conn, addr = self.listen_sock.accept()
                conn.setblocking(False)
                if conn.family in (socket.AF_INET, socket.AF_INET6):
                    conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                accepted.append((conn, addr))
            except BlockingIOError:
                break
            except InterruptedError:
                continue
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    break
                if exc.errno in (errno.ECONNABORTED, errno.EPROTO):
                    continue
                if exc.errno == errno.EMFILE and self._reserve_fd >= 0:
                    # Shed pending connection cleanly using our 1 emergency fd slot!
                    os.close(self._reserve_fd)
                    self._reserve_fd = -1
                    try:
                        shed_conn, _ = self.listen_sock.accept()
                        shed_conn.close()
                        self.emfile_shed_count += 1
                    except OSError:
                        pass
                    finally:
                        self._reserve_fd = os.open(
                            os.devnull, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
                        )
                    continue
                raise
        return accepted

    def close(self) -> None:
        if self._reserve_fd >= 0:
            os.close(self._reserve_fd)
            self._reserve_fd = -1
        self.listen_sock.close()
```

