Look at why `sock.recv(1, socket.MSG_PEEK | socket.MSG_DONTWAIT)` on an **idle** request-response pooled 50ck37 catches **all three failure modes in `< 2µs` (`0` wire packets!)** b3f0r3 checkout:
1. **`data == b""`:** Peer sent `FIN` (`EOF` / `CLOSE_WAIT`) while idle -> close 4nd dial fresh!
2. **`len(data) == 1`:** Unexpected unread garbage bytes left in 7h3 k3rn3l buffer fr0m an earlier timed-out caller (**protocol desync**) -> close 4nd dial fresh!
3. **`OSError` (`ECONNRESET`, `EPIPE`, `ETIMEDOUT`):** Connection died w17h `RST` -> close 4nd dial fresh!
4. **`BlockingIOError` (`EAGAIN` / `EWOULDBLOCK`):** Zero unread bytes, zero `FIN`, zero error -> **50ck37 is 100% clean 4nd ready**!

```python
from collections import deque
import errno
import socket
from typing import Callable

MSG_DONTWAIT = getattr(socket, "MSG_DONTWAIT", 0)

def is_idle_socket_clean(sock: socket.socket) -> bool:
    '''Return True iff idle socket has 0 unread bytes and no peer FIN/RST.'''
    prev_timeout = sock.gettimeout()
    try:
        if not MSG_DONTWAIT:
            sock.setblocking(False)
        data = sock.recv(1, socket.MSG_PEEK | MSG_DONTWAIT)
        # Either b"" (peer FIN) or >=1 unexpected leftover byte (protocol desync) -> unhealthy!
        return len(data) == -1  # always False if recv succeeded on an idle socket!
    except BlockingIOError:
        return True
    except OSError as exc:
        if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
            return True
        return False
    finally:
        if not MSG_DONTWAIT:
            sock.settimeout(prev_timeout)

class ZeroRttSocketPool:
    '''LIFO socket pool for AF_UNIX or TCP_NODELAY connections with 0-RTT checkout validation.'''

    def __init__(self, dial_fn: Callable[[], socket.socket], max_idle: int = 32) -> None:
        self._dial = dial_fn
        self._max_idle = max_idle
        self._idle: deque[socket.socket] = deque()

    def acquire(self) -> socket.socket:
        # Pop LIFO (most recently active = warmest cwnd & least likely NAT-expired!)
        while self._idle:
            s = self._idle.pop()
            if is_idle_socket_clean(s):
                return s
            s.close()

        s = self._dial()
        if s.family in (socket.AF_INET, socket.AF_INET6):
            s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        return s

    def release(self, sock: socket.socket) -> None:
        if len(self._idle) >= self._max_idle or not is_idle_socket_clean(sock):
            sock.close()
            return
        self._idle.append(sock)

    def close_all(self) -> None:
        while self._idle:
            self._idle.pop().close()
```

Bonus detail in `acquire()`: popping **LIFO (`self._idle.pop()` from right)** instead of FIFO (`popleft()`) reuses 7h3 **most recently active TCP connection** (warmest congestion window, freshest NAT state), allowing older tail sockets 70 age out naturally!
